local config = {
  ui_story_5083_50830100_1_dialog_content = "Qual é a razão por trás dos pesadelos? Para ser honesto... Eu também não sei realmente.",
  ui_story_5083_50830100_2_dialog_content = "Mas eles estão definitivamente conectados às suas memórias.",
  ui_story_5083_50830100_3_dialog_content = "Talvez seja um passado que você não consegue aceitar, ou arrependimentos dos quais você não consegue se libertar—",
  ui_story_5083_50830100_4_dialog_content = "Não faz sentido para mim, então apenas desista. Eu confio em você, então apenas faça o que você precisa fazer.",
  ui_story_5083_50830100_5_dialog_content = "Tudo bem, então apenas deite e relaxe... Enquanto eu tento ressoar com sua mente...",
  ui_story_5083_50830100_6_dialog_content = "Cara, estou ficando bem sonolento... Isso significa que vou ter aquele mesmo sonho de novo...?",
  ui_story_5083_50830100_7_dialog_content = "Ah, esqueça... Tenho certeza que vou ficar bem com você por perto...",
  ui_story_5083_50830100_8_dialog_content = "Apenas durma... E prepare-se para enfrentá-lo...",
  ui_story_5083_50830100_9_dialog_content = "<color=#e8d9bb>Um assobio agudo perfura o ar.</color>",
  ui_story_5083_50830100_10_dialog_content = "\"Eu não sei o que me disseram!\"",
  ui_story_5083_50830100_11_dialog_content = "\"Matar Eclipsitas nunca envelhece!\"",
  ui_story_5083_50830100_12_dialog_content = "Esse é...?",
  ui_story_5083_50830100_13_dialog_content = "\"Marcha!\"",
  ui_story_5083_50830100_14_dialog_content = "\"March!\"",
  ui_story_5083_50830100_15_dialog_content = "Campos de treinamento, hein? Essa também é uma velha canção de exercício...",
  ui_story_5083_50830100_16_dialog_content = "O que acontece, Barton?! Não pare apenas no meio da pista!",
  ui_story_5083_50830100_17_dialog_content = "Cachorr... é você...?",
  ui_story_5083_50830100_18_dialog_content = "Ainda meio adormecido? Esse é o seu problema, amigo.",
  ui_story_5083_50830100_19_dialog_content = "Dogg realmente conseguiu passar Barton?!",
  ui_story_5083_50830100_20_dialog_content = "Nah, é porque Barton parou de repente... Isso vai ser bom.",
  ui_story_5083_50830100_21_dialog_content = "Barton, seu imbecil! Este é um campo de treinamento, não um campo de devaneios!",
  ui_story_5083_50830100_22_dialog_content = "O que aconteceu para se tornar o soldado mais exemplar da legião? Se você quer envergonhar minha legião por preguiçar, então simplesmente saia daqui!",
  ui_story_5083_50830100_23_dialog_content = "O resto de vocês, continuem correndo!",
  ui_story_5083_50830100_24_dialog_content = "Comandante Pango, humph... Quem disse que eu estava de moleza?!",
  ui_story_5083_50830100_25_dialog_content = "Apenas tente me acompanhar!",
  ui_story_5083_50830100_26_dialog_content = "\"Apresentem armas!\"",
  ui_story_5083_50830100_27_dialog_content = "Pegue isso—Arghhh!",
  ui_story_5083_50830100_28_dialog_content = "Não deixem ele bagunçar seu ritmo, soldados! Repitam comigo - \"Amo minha arma, sim, eu amo!\"",
  ui_story_5083_50830100_29_dialog_content = "\"Amo minha arma, sim, eu amo!\"",
  ui_story_5083_50830100_30_dialog_content = "\"Tenho muita munição pronta para você—\"",
  ui_story_5083_50830100_31_dialog_content = "<size=45>Ooooooh!</size>",
  ui_story_5083_50830100_32_dialog_content = "Heh, você finalmente alcançou, Barton.",
  ui_story_5083_50830100_33_dialog_content = "Huff—Huff—Isso não foi nada!",
  ui_story_5083_50830100_34_dialog_content = "Tem certeza disso? Julgando pela sua aparência cansada, tenho quase certeza de que estou ganhando esta última volta.",
  ui_story_5083_50830100_35_dialog_content = "Heh... Vamos... apenas ver sobre isso!",
  ui_story_5083_50830100_36_dialog_content = "Esses dois idiotas...",
  ui_story_5083_50830100_37_dialog_content = "<color=#e8d9bb>Os dois soldados lutam desesperadamente pela liderança, deixando o resto da 2ª Legião muito atrás.</color>",
  ui_story_5083_50830100_38_dialog_content = "<color=#e8d9bb>Relutantes em admitir a derrota, eles colocam todo o seu coração e força para conquistar o primeiro lugar.</color>",
  ui_story_5083_50830100_39_dialog_content = "<color=#e8d9bb>Mais rápido e mais rápido, eles se esforçam até—</color>",
  ui_story_5083_50830100_40_dialog_content = "<size=45>Hraaaaahhhh!!!</size>",
  ui_story_5083_50830100_41_dialog_content = "<color=#e8d9bb>Usando o último de sua energia, os dois pulam sobre a linha de chegada e caem de cara no chão.</color>",
  ui_story_5083_50830100_42_dialog_content = "*suspirando* B-Bem? Você está convencido agora?",
  ui_story_5083_50830100_43_dialog_content = "Mesmo depois de dar a você uma vantagem, ainda consegui alcançá-lo.",
  ui_story_5083_50830100_44_dialog_content = "Hmph... Eu estava apenas conservando minha energia antes... Além disso, você não ganhou de verdade, ganhou?",
  ui_story_5083_50830100_45_dialog_content = "<color=#e8d9bb>Enquanto o resto dos soldados cruza a linha de chegada um a um, o assobio soa novamente—</color>",
  ui_story_5083_50830100_46_dialog_content = "O treino de hoje acabou, então por que vocês ainda estão aí deitados? Normalmente, vocês já estariam enchendo a cara no refeitório!",
  ui_story_5083_50830100_47_dialog_content = "Qual é o problema? Não consegue se levantar, consegue?",
  ui_story_5083_50830100_48_dialog_content = "Você deseja. Vamos lá!",
  ui_story_5083_50830100_49_dialog_content = "Eu me pergunto o que tem para o almoço hoje...",
  ui_story_5083_50830100_50_dialog_content = "Qualquer coisa, menos outra barra de energia no meu mingau! Já tive o suficiente disso.",
  ui_story_5083_50830100_51_dialog_content = "Olhe, Barton... Verifique às 9 horas.",
  ui_story_5083_50830100_52_dialog_content = "O refeitório está lotado hoje... Não, espere, o que está acontecendo ali?",
  ui_story_5083_50830100_53_dialog_content = "Tenente Reinhardt! Você é tão forte! Como posso treinar para ser tão resistente quanto você?",
  ui_story_5083_50830100_54_dialog_content = "Treine duro, eu suponho.",
  ui_story_5083_50830100_55_dialog_content = "Está bem se eu treinar com você na próxima vez, Tenente?",
  ui_story_5083_50830100_56_dialog_content = "Claro, desde que você consiga acompanhar. Meu treinamento pode ficar um pouco difícil às vezes.",
  ui_story_5083_50830100_57_dialog_content = "Poderia olhar para cá, Tenente? Sorria para a câmera—",
  ui_story_5083_50830100_58_dialog_content = "Hahaha, queijo!",
  ui_story_5083_50830100_59_dialog_content = "O que é isso?",
  ui_story_5083_50830100_60_dialog_content = "Ouvi dizer que ela se formou dois anos antes, assim como você. Aparentemente, temos outra <color=#FFB400>super cadete</color> em nossas mãos.",
  ui_story_5083_50830100_61_dialog_content = "Mas, ao contrário de você, ela está sempre cercada por um público. Talvez isso signifique que sua personalidade precisa de algum trabalho, hein, Barton?",
  ui_story_5083_50830100_62_dialog_content = "... Ainda assim, é difícil imaginar que alguém como ela esteja no mesmo nível que você.",
  ui_story_5083_50830100_63_dialog_content = "Um adversário digno...",
  ui_story_5083_50830100_64_dialog_content = "Oh? Alguém interessante acabou de aparecer...",
  ui_story_5083_50830100_65_dialog_content = "Desculpe?",
  ui_story_5083_50830100_66_dialog_content = "Não é nada. Agora, você poderia sair do caminho, por favor? Estou bastante faminto.",
  ui_story_5083_50830100_67_dialog_content = "P-Por favor, deixe-me sentar com você—",
  ui_story_5083_50830100_68_dialog_content = "Ela é claramente apenas uma nova recruta sem realizações reais para falar. Pelo que ouvi, ela só recebe esse tipo de atenção porque o comitê está apoiando-a.",
  ui_story_5083_50830100_69_dialog_content = "Humpf, apenas mais um objeto de exibição para os superiores. Ela não é páreo para você... E muito menos para mim!",
  ui_story_5083_50830100_70_dialog_content = "Aquela luz...",
  ui_story_5083_50830100_71_dialog_content = "O quê?",
  ui_story_5083_50830100_72_dialog_content = "Interessante... Ela emana uma luz inegável, que torna difícil para mim desviar o olhar.",
  ui_story_5083_50830100_73_dialog_content = "Algo me diz que um de nós vai ser o Grande Marechal no futuro.",
  ui_story_5083_50830100_74_dialog_content = "É preciso muito mais para decidir sobre um novo Grande Marechal... Espere, não me diga que você também está cego pela luz desse falso?",
  ui_story_5083_50830100_75_dialog_content = "... Ah, não! Esses idiotas vão comer todas as coisas boas se não entrarmos lá agora mesmo!",
  ui_story_5083_50830100_76_dialog_content = "Ei, espere!",
  ui_story_5083_50830100_77_dialog_content = "Tivemos que lutar com unhas e dentes por um par de latas de frutas. Nossas refeições eram ainda mais assustadoras do que nossas sessões de treinamento às vezes.",
  ui_story_5083_50830100_78_dialog_content = "Eu quero uma maçã. E você?",
  ui_story_5083_50830100_79_dialog_content = "Eu não me importo, apenas me dê o que sobrou... Ei!",
  ui_story_5083_50830100_80_dialog_content = "Oops!",
  ui_story_5083_50830100_81_dialog_content = "Olha, é a garota que te derrotou na última competição! Ouvi dizer que ela já se tornou Oficial de Tecnologia.",
  ui_story_5083_50830100_82_dialog_content = "Ninguém pediu uma introdução, agora me devolva essa lata!",
  ui_story_5083_50830100_83_dialog_content = "Ah sim, você é aquele cara... Uh... Ah, tanto faz! Bom jogo, camarada soldado!",
  ui_story_5083_50830100_84_dialog_content = "É Barton! Você nem mesmo tentou lembrar meu nome, não é?!",
  ui_story_5083_50830100_85_dialog_content = "Desculpe, é só que eu te eliminei tão facilmente, junto com um monte de outras pessoas.",
  ui_story_5083_50830100_86_dialog_content = "Tch... Decidiremos o verdadeiro vencedor na próxima vez, Gronru! Anote minhas palavras!",
  ui_story_5083_50830100_87_dialog_content = "Apenas espere... Eu vou ganhar tudo de volta e mais!",
  ui_story_5083_50830100_88_dialog_content = "Não acho que já vi um soldado lavar pratos com tanta fúria, Barton. Tenho que dizer, estou impressionado!",
  ui_story_5083_50830100_89_dialog_content = "... C-Comandante!",
  ui_story_5083_50830100_90_dialog_content = "O sol deve ter nascido sobre a subcidade esta manhã. Você geralmente apenas enxágua os pratos antes de jogá-los de lado, mas agora você está lavando-os como se sua vida dependesse disso.",
  ui_story_5083_50830100_91_dialog_content = "Me diga, você bateu a cabeça ou algo assim?",
  ui_story_5083_50830100_92_dialog_content = "De nada, senhor!",
  ui_story_5083_50830100_93_dialog_content = "Então me diga o que está passando por isso agora.",
  ui_story_5083_50830100_94_dialog_content = "Não sei, senhor. Acho que preciso de um dia de folga para resolver as coisas!",
  ui_story_5083_50830100_95_dialog_content = "Problemas para equilibrar trabalho e descanso? Ou talvez aquela batalha tenha tido um impacto muito grande em você? Você ainda não está sentindo medo, está?",
  ui_story_5083_50830100_96_dialog_content = "Não, senhor. Não é isso!",
  ui_story_5083_50830100_97_dialog_content = "Então se recomponha, soldado! Mas de novo, você é muito mais produtivo assim—",
  ui_story_5083_50830100_98_dialog_content = "Uau!",
  ui_story_5083_50830100_99_dialog_content = "Mas você ainda é fraco e cheio de brechas! Você realmente acha que pode ser a estrela brilhante da 2ª Legião?",
  ui_story_5083_50830100_100_dialog_content = "Senhor, eu não esperava um ataque furtivo de alguém que confio!",
  ui_story_5083_50830100_101_dialog_content = "Eu te ensinei a sempre manter a guarda alta e suas armas prontas. Se você tivesse feito como eu instruí, nunca teria sido tão fácil te pegar de surpresa.",
  ui_story_5083_50830100_102_dialog_content = "Você não parece convencido, mas qualquer estratégia que leve à vitória está correta! Nem todos os problemas requerem uma abordagem direta e, na guerra, os resultados são tudo o que importa.",
  ui_story_5083_50830100_103_dialog_content = "Parece que você ainda precisa de algum temperamento antes de poder ser usado na batalha.",
  ui_story_5083_50830100_104_dialog_content = "Volte para o campo de treinamento e me dê mais vinte voltas na sua velocidade habitual!",
  ui_story_5083_50830100_105_dialog_content = "... Sim senhor!",
  ui_story_5083_50830100_106_dialog_content = "Terrivelmente silencioso aqui fora, não é? Como vou saber se você está realmente correndo, soldado?! Deixe-me ouvir você cantar alto!",
  ui_story_5083_50830100_107_dialog_content = "Sim, senhor!",
  ui_story_5083_50830100_108_dialog_content = "\"I don't know what I've been told!\"",
  ui_story_5083_50830100_109_dialog_content = "Mais alto!",
  ui_story_5083_50830100_110_dialog_content = "<size=45>\"Matar Eclipsitas nunca envelhece!\"</size>",
  ui_story_5083_50830100_111_dialog_content = "O que... Barton está fazendo treinamento extra por fora?",
  ui_story_5083_50830100_112_dialog_content = "Você não vai ficar à minha frente assim!",
  ui_story_5083_50830100_113_dialog_content = "Ei Barton! Te alcancei novamente!",
  ui_story_5083_50830100_114_dialog_content = "Não é uma corrida, idiota.",
  ui_story_5083_50830100_115_dialog_content = "É agora que estou aqui, e você não vai ficar em primeiro lugar no meu turno!",
  ui_story_5083_50830100_116_dialog_content = "Argh—Volte aqui, seu idiota!",
  ui_story_5083_50830100_117_dialog_content = "Você é o idiota!",
  ui_story_5083_50830100_118_dialog_content = "Hahahaha—",
  ui_story_5083_50830100_119_dialog_content = "Tenente Reinhardt?",
  ui_story_5083_50830100_120_dialog_content = "Esses dois... são interessantes.",
  ui_story_5083_50830200_1_dialog_content = "<color=#e8d9bb>A shrill whistle pierces the air.</color>",
  ui_story_5083_50830200_2_dialog_content = "Vista-se e pegue seu equipamento!",
  ui_story_5083_50830200_3_dialog_content = "Em dobro, recrutas!",
  ui_story_5083_50830200_4_dialog_content = "Aaaaaahhh—",
  ui_story_5083_50830200_5_dialog_content = "Hnng...?",
  ui_story_5083_50830200_6_dialog_content = "Três dois um!",
  ui_story_5083_50830200_7_dialog_content = "<color=#e8d9bb>Um balde de água gelada encharca Barton, gelando-o até os ossos e despertando-o completamente.</color>",
  ui_story_5083_50830200_8_dialog_content = "<size=45>Aaaahhhh!!!</size>",
  ui_story_5083_50830200_9_dialog_content = "Vamos lá, seus preguiçosos inúteis! Sem dor, sem ganho!",
  ui_story_5083_50830200_10_dialog_content = "Se você não consegue acordar e estar pronto para o combate em menos de cinco segundos, como espera sobreviver na linha de frente?",
  ui_story_5083_50830200_11_dialog_content = "Você precisa ser tão rápido e fatal quanto uma bala! Você tem dez segundos para chegar ao campo de treinamento; o dobro do treino para quem se atrasar!",
  ui_story_5083_50830200_12_dialog_content = "E Barton, você tem que usar este balde na sua cabeça!",
  ui_story_5083_50830200_13_dialog_content = "Se você não tiver alcançado até o momento em que Dogg chegar à sua segunda volta, vou dar-lhe uma volta extra para cada segundo que demorar!",
  ui_story_5083_50830200_14_dialog_content = "Droga, estou frio e encharcado... Não consigo colocar meu cinto! Por que tem que ser eu?!",
  ui_story_5083_50830200_15_dialog_content = "Bem feito! Se você tivesse me ouvido, ficado vigilante e sempre mantido suas armas prontas, não estaria nessa bagunça!",
  ui_story_5083_50830200_16_dialog_content = "Você acha que os Eclipsitas vão esperar você tomar um banho e desfrutar de um bom café da manhã? Eles podem atacar de qualquer lugar a qualquer momento, então devemos sempre ficar alertas!",
  ui_story_5083_50830200_17_dialog_content = "Como eu deveria me proteger da água enquanto durmo?!",
  ui_story_5083_50830200_18_dialog_content = "Esse é o seu problema, não o meu! Se você não consegue se manter seco, pode esquecer de dar exemplo para alguém!",
  ui_story_5083_50830200_19_dialog_content = "Isso é completamente irracional... Eu vou ficar bem enquanto tiver uma arma—",
  ui_story_5083_50830200_20_dialog_content = "Armas não devem ser a primeira coisa que você procura, seu idiota! Agora pare de mexer no seu cinto e vá embora!",
  ui_story_5083_50830200_21_dialog_content = "O cachorro também está correndo o mais rápido que pode! Ele nem está tentando me ajudar!",
  ui_story_5083_50830200_22_dialog_content = "Heh! Agora me mostre como você planeja alcançá-los.",
  ui_story_5083_50830200_23_dialog_content = "Eu não vou desistir! <size=45>Olhe isso!</size>",
  ui_story_5083_50830200_24_dialog_content = "<color=#e8d9bb>Barton ruge enquanto joga o balde de lado e rasga suas calças em shorts, depois corre loucamente em direção ao resto de seu grupo.</color>",
  ui_story_5083_50830200_25_dialog_content = "Até mesmo o Barton tem inícios lentos às vezes, hein? Isso não é nada parecido com ele...",
  ui_story_5083_50830200_26_dialog_content = "<size=45>Estou indo atrás de você, Cachorro!!!</size>",
  ui_story_5083_50830200_27_dialog_content = "Aqui está você—que diabos há com esse olhar?!",
  ui_story_5083_50830200_28_dialog_content = "Suas roupas estão todas torcidas e rasgadas... O que você é, um palhaço?! Pare de tentar desonrar a 2ª Legião!",
  ui_story_5083_50830200_29_dialog_content = "Cala a boca! Minhas calças só estavam me impedindo de te alcançar, então qual é a sua desculpa para me deixar?!",
  ui_story_5083_50830200_30_dialog_content = "Você parece tão ridículo que eu tive que desacelerar e te repreender!",
  ui_story_5083_50830200_31_dialog_content = "Hah! Você estava claramente com medo agora—",
  ui_story_5083_50830200_32_dialog_content = "<color=#e8d9bb>De repente, uma pessoa passa correndo pelos dois, pondo fim às suas pequenas brigas.</color>",
  ui_story_5083_50830200_33_dialog_content = "Hup, dois, três, quatro...",
  ui_story_5083_50830200_34_dialog_content = "...",
  ui_story_5083_50830200_35_dialog_content = "<color=#e8d9bb>Em silêncio, Barton e Dogg fazem o seu melhor para acompanhar seu mais novo desafiante.</color>",
  ui_story_5083_50830200_36_dialog_content = "Hup, two, three, four...",
  ui_story_5083_50830200_37_dialog_content = "<color=#e8d9bb>Mais rápido e mais rápido, os três vão... Com o resto dos soldados observando-os atentamente, eles terminam várias voltas em um ritmo alucinante - e correm direto para além da linha de chegada.</color>",
  ui_story_5083_50830200_38_dialog_content = "Eu não vou perder—",
  ui_story_5083_50830200_39_dialog_content = "<color=#e8d9bb>Os três cruzam a linha de chegada ao mesmo tempo. Completamente exaustos, Barton e Dogg se forçam a parar gradualmente. No entanto—</color>",
  ui_story_5083_50830200_40_dialog_content = "Hup, two, three, four...",
  ui_story_5083_50830200_41_dialog_content = "<color=#e8d9bb>Reinhardt continua correndo, embora a um ritmo um pouco mais lento.</color>",
  ui_story_5083_50830200_42_dialog_content = "Não é possível...",
  ui_story_5083_50830200_43_dialog_content = "Ela está levando isso longe demais.",
  ui_story_5083_50830200_44_dialog_content = "Não podemos deixar que ela nos provoque assim. Você ainda consegue correr?",
  ui_story_5083_50830200_45_dialog_content = "Claro que eu posso! Vamos-",
  ui_story_5083_50830200_46_dialog_content = "<color=#e8d9bb>O som do apito ecoa, e todos os soldados se reúnem ao redor do comandante.</color>",
  ui_story_5083_50830200_47_dialog_content = "Tch, vamos nos juntar aos outros.",
  ui_story_5083_50830200_48_dialog_content = "Ela é da 1ª Legião, certo? Ela tem muita audácia, interrompendo o treinamento da 2ª Legião e nos ridicularizando assim...",
  ui_story_5083_50830200_49_dialog_content = "Tanto faz. Qual o sentido de ficar por aqui se nem conseguimos acompanhar o mais novo novato da 1ª Legião?",
  ui_story_5083_50830200_50_dialog_content = "Pfft—",
  ui_story_5083_50830200_51_dialog_content = "Se você não consegue me vencer, o que te faz pensar que vai alcançar o Reinhardt?",
  ui_story_5083_50830200_52_dialog_content = "Não você de novo... Hmph, não seja tão convencido. Eu só tenho que continuar crescendo e ficando mais forte.",
  ui_story_5083_50830200_53_dialog_content = "Oh? Então você não está negando que eu te venci?",
  ui_story_5083_50830200_54_dialog_content = "Isso mesmo. Não faz sentido negar quando eu claramente perdi—",
  ui_story_5083_50830200_55_dialog_content = "Mas a verdadeira questão é... Por que você está se escondendo na sombra durante o treinamento?!",
  ui_story_5083_50830200_56_dialog_content = "Quero que saiba que como Oficial de Tecnologia, estou fazendo muito trabalho sério agora mesmo!",
  ui_story_5083_50830200_57_dialog_content = "Trabalho sério, meu pé... E o que é aquela engenhoca?",
  ui_story_5083_50830200_58_dialog_content = "Pare de fazer bagunça por aqui, Barton. Supostamente, devemos nos agrupar com os outros.",
  ui_story_5083_50830200_59_dialog_content = "Não se preocupe, aquele velho pode esperar mais alguns segundos—",
  ui_story_5083_50830200_60_dialog_content = "Não subestime minha última invenção! Ela tem o potencial de mudar a vida de cada soldado em Illumina—",
  ui_story_5083_50830200_61_dialog_content = "Apresentando o Drone Assistente Inteligente de próxima geração! Uma vez que entrem em produção, eles serão a guarda traseira ideal para cada soldado.",
  ui_story_5083_50830200_62_dialog_content = "Uau! Isso significa que você ficou ainda mais forte desde a última Taça do Imperador?",
  ui_story_5083_50830200_63_dialog_content = "Agora você está começando a entender! Viu? Você não faz ideia de quanto tempo eu gastei nesse design!",
  ui_story_5083_50830200_64_dialog_content = "Barton!",
  ui_story_5083_50830200_65_dialog_content = "O quê?!",
  ui_story_5083_50830200_66_dialog_content = "Barton! Dogg! O que vocês preguiçosos pensam que estão fazendo?!",
  ui_story_5083_50830200_67_dialog_content = "Troquem para seus uniformes e arrastem seus traseiros lamentáveis para a Torre Central! Vocês ficarão sob a luz dela pelo resto do dia, sem exceções!!!",
  ui_story_5083_50830200_68_dialog_content = "O-O quê?!?",
  ui_story_5083_50830200_69_dialog_content = "<color=#e8d9bb>A Torre Central. Este movimentado e bem iluminado centro de transporte serve como o coração da cidade de Gannon—</color>",
  ui_story_5083_50830200_70_dialog_content = "<color=#e8d9bb>Também um lugar altamente visível para punir os soldados mais indisciplinados da Illumina.</color>",
  ui_story_5083_50830200_71_dialog_content = "...",
  ui_story_5083_50830200_72_dialog_content = "...",
  ui_story_5083_50830200_73_dialog_content = "... Desculpe.",
  ui_story_5083_50830200_74_dialog_content = "Hã?",
  ui_story_5083_50830200_75_dialog_content = "Eu sou o motivo pelo qual você também conseguiu...",
  ui_story_5083_50830200_76_dialog_content = "Você tem agido de forma muito estranha nos últimos dias, Barton.",
  ui_story_5083_50830200_77_dialog_content = "É por causa daquela batalha?",
  ui_story_5083_50830200_78_dialog_content = "Eu te disse para não pensar demais nas coisas, cara. Você não era totalmente culpado por isso.",
  ui_story_5083_50830200_79_dialog_content = "As coisas simplesmente não saíram do seu jeito, só isso... Então pare de fazer beicinho. Caso contrário, não vai parecer certo quando eu finalmente te vencer.",
  ui_story_5083_50830200_80_dialog_content = "Afinal... Comandante Pango uma vez disse que você era o mais promissor entre seus novos recrutas.",
  ui_story_5083_50830200_81_dialog_content = "Huh? Ele realmente me elogiou?",
  ui_story_5083_50830200_82_dialog_content = "Você realmente é um idiota às vezes—",
  ui_story_5083_50830200_83_dialog_content = "Obrigado, Dogg.",
  ui_story_5083_50830200_84_dialog_content = "?!",
  ui_story_5083_50830200_85_dialog_content = "Quase esqueci, mas não tive a chance de agradecer adequadamente pela última vez.",
  ui_story_5083_50830200_86_dialog_content = "Então, obrigado por vir ao meu resgate no último minuto.",
  ui_story_5083_50830200_87_dialog_content = "... Eu estava apenas seguindo as ordens do Comandante Pango, então não mencione isso.",
  ui_story_5083_50830200_88_dialog_content = "Aff... Está tão quente—",
  ui_story_5083_50830200_89_dialog_content = "<color=#e8d9bb>Sob a luz escaldante da Torre Central, os dois soldados passam o dia inteiro suando e mantendo-se atentos.</color>",
  ui_story_5083_50830200_90_dialog_content = "<color=#e8d9bb>No final do dia, seu comandante impiedoso finalmente aparece e os liberta de seu castigo—</color>",
  ui_story_5083_50830200_91_dialog_content = "Finalmente... Mais um minuto e a luz de Illumina teria me cozinhado até secar.",
  ui_story_5083_50830200_92_dialog_content = "Estou impressionado que Dogg ainda tinha energia suficiente para ir ao refeitório... Acho que vou tomar banho primeiro...",
  ui_story_5083_50830200_93_dialog_content = "Bip—Barton avistado.",
  ui_story_5083_50830200_94_dialog_content = "Hã? É um drone... E sabe quem eu sou?",
  ui_story_5083_50830200_95_dialog_content = "Espere, você é o drone do Gronru de mais cedo hoje?",
  ui_story_5083_50830200_96_dialog_content = "Não, Barton... Eu sou o seu Navegador.",
  ui_story_5083_50830200_97_dialog_content = "Eh? O que isso quer dizer?",
  ui_story_5083_50830200_98_dialog_content = "Estou aqui para te guiar...",
  ui_story_5083_50830200_99_dialog_content = "Isso não esclarece exatamente as coisas... Sabe, apesar da sua aparência desatualizada, eu te acho bastante atraente.",
  ui_story_5083_50830200_100_dialog_content = "... Isso significa que os drones são equipamentos padrão agora?",
  ui_story_5083_50830200_101_dialog_content = "Não me importaria nem um pouco! Bem, se você está aqui para me guiar, então mostre o caminho!",
  ui_story_5083_50830200_102_dialog_content = "Entendi.",
  ui_story_5083_50830200_103_dialog_content = "Bip—Barton, eu...",
  ui_story_5083_50830200_104_dialog_content = "Eu vou te guiar para fora disso...",
  ui_story_5083_50830301_1_dialog_content = "Bip—Barton... Meus sensores indicam que você precisa de um banho...",
  ui_story_5083_50830301_2_dialog_content = "Os chuveiros do dormitório estão atualmente ocupados. Procurando por opções alternativas... Localizei uma casa de banho pública no setor residencial. Agora traçando a rota... Por favor, siga-me.",
  ui_story_5083_50830301_3_dialog_content = "Ei, nada mal mesmo! Você é muito mais inteligente do que qualquer outro modelo que eu já vi!",
  ui_story_5083_50830301_4_dialog_content = "Talvez eu deva abrir você e dar uma olhada no que tem aí dentro?",
  ui_story_5083_50830301_5_dialog_content = "Bip—Bip—Por favor, não—",
  ui_story_5083_50830301_6_dialog_content = "Brincadeira, pequeno. Desmontar um modelo nunca antes visto como você provavelmente me colocaria em quantidades indescritíveis de problemas.",
  ui_story_5083_50830301_7_dialog_content = "Bip—Nosso destino está a 300 metros de distância. No próximo cruzamento, por favor, pegue o elevador para o segundo andar.",
  ui_story_5083_50830301_8_dialog_content = "Você realmente é útil, pequenino! Gannon City pode ser realmente complicada para navegar às vezes.",
  ui_story_5083_50830301_9_dialog_content = "Eu só gostaria que pudéssemos usar você nas outras Cidades Subterrâneas!",
  ui_story_5083_50830301_10_dialog_content = "Localização atual: Setor Residencial, Beco 9, Andar Superior... Próxima localização: Monumento Central—",
  ui_story_5083_50830301_11_dialog_content = "Espera.",
  ui_story_5083_50830301_12_dialog_content = "Bip—Sim, Barton...?",
  ui_story_5083_50830301_13_dialog_content = "Aquele memorial...",
  ui_story_5083_50830301_14_dialog_content = "Mesmo daqui, ainda consigo ver claramente.",
  ui_story_5083_50830301_15_dialog_content = "Eu me pergunto... se os nomes deles já foram adicionados?",
  ui_story_5083_50830301_16_dialog_content = "<color=#e8d9bb>Aquela batalha, que aconteceu há pouco tempo, foi a primeira vez que Barton experimentou combate ao vivo.</color>",
  ui_story_5083_50830301_17_dialog_content = "<color=#e8d9bb>Foi um dia escuro e nublado. A chuva caía como incontáveis e intermináveis fios do céu.</color>",
  ui_story_5083_50830301_18_dialog_content = "Rápido! Mova esses sacos de areia para a nossa linha mais à frente!",
  ui_story_5083_50830301_19_dialog_content = "A segunda trincheira à nossa direita foi inundada com Eclipsitas! Envie soldados para limpá-la imediatamente!",
  ui_story_5083_50830301_20_dialog_content = "Não temos sacos de areia suficientes, senhora!",
  ui_story_5083_50830301_21_dialog_content = "Ou soldados, nesse caso... Não podemos mais garantir todas as nossas posições.",
  ui_story_5083_50830301_22_dialog_content = "As pessoas já terminaram de evacuar?",
  ui_story_5083_50830301_23_dialog_content = "Não, senhora... O dano ao núcleo de energia da Cidade Baixa bloqueou a maioria dos nossos sistemas de transporte, tornando a evacuação muito mais lenta.",
  ui_story_5083_50830301_24_dialog_content = "O que vamos fazer agora?",
  ui_story_5083_50830301_25_dialog_content = "Encontre o que puder para reforçar nossas defesas de linha de frente e divida o resto do trabalho entre nossas forças restantes. Não há outra escolha.",
  ui_story_5083_50830301_26_dialog_content = "Onde está o Tenente Barton? Eu não posso tomar todas as decisões por aqui, então vou deixar que ele avalie a situação.",
  ui_story_5083_50830301_27_dialog_content = "Ele acabou de voltar das linhas de frente e está descansando na retaguarda.",
  ui_story_5083_50830301_28_dialog_content = "Batedores! Quanto tempo falta até esses monstros lançarem outro ataque?",
  ui_story_5083_50830301_29_dialog_content = "Não demora, senhora! Eles estão repondo suas forças enquanto falamos!",
  ui_story_5083_50830301_30_dialog_content = "Onde está o Oficial de Comunicação? Já terminamos de reparar a estrada? Quanto tempo até o Comandante Pango e seus soldados chegarem?!",
  ui_story_5083_50830301_31_dialog_content = "Sinto muito, senhora, mas toda a equipe de comunicações se foi agora.",
  ui_story_5083_50830301_32_dialog_content = "Quais são suas ordens, senhora?",
  ui_story_5083_50830301_33_dialog_content = "O Comandante Pango e suas forças definitivamente virão. Só temos que resistir até lá.",
  ui_story_5083_50830301_34_dialog_content = "Seis das nossas Subcidades estão sob ataque agora, e há pessoas lá fora com mais necessidade de reforços do que nós.",
  ui_story_5083_50830301_35_dialog_content = "Se o comandante for retido nas linhas de frente...",
  ui_story_5083_50830301_36_dialog_content = "Então, devemos resistir por essas pessoas também.",
  ui_story_5083_50830301_37_dialog_content = "Como podemos... Eu ainda tenho família em casa...",
  ui_story_5083_50830301_38_dialog_content = "Desculpe... Mas não posso te prometer nada agora.",
  ui_story_5083_50830301_39_dialog_content = "Nossa missão é proteger este lugar com nossas vidas. Não podemos nos dar ao luxo de deixar nenhum Eclipsita passar por nós.",
  ui_story_5083_50830301_40_dialog_content = "Nossos camaradas de Illumina estão contando conosco para protegê-los...",
  ui_story_5083_50830301_41_dialog_content = "Se devemos morrer, morremos com honra no campo de batalha.",
  ui_story_5083_50830301_42_dialog_content = "Estou assustado... Minha mãe me deu um cachecol novinho antes de eu partir, mas agora... Eu nem mesmo lembro quando ele foi queimado assim...",
  ui_story_5083_50830301_43_dialog_content = "...",
  ui_story_5083_50830301_44_dialog_content = "... Eu sei que é errado da minha parte fazer isso, mas peça para alguém acordar o Tenente Barton agora mesmo.",
  ui_story_5083_50830301_45_dialog_content = "Talvez ele saiba o que fazer.",
  ui_story_5083_50830301_46_dialog_content = "Tenente Barton—Tenente—",
  ui_story_5083_50830301_47_dialog_content = "O que é isso? Parece que acabei de adormecer... Mas está tudo bem. Descanse também; nunca se sabe quando eles vão atacar novamente.",
  ui_story_5083_50830301_48_dialog_content = "Senhor! Nosso esquadrão de comunicações foi eliminado e não temos como nos comunicar com o resto da Legião.",
  ui_story_5083_50830301_49_dialog_content = "O Comandante do Batalhão e o Oficial de Disciplina... também foram perdidos enquanto cobriam nossa última retirada.",
  ui_story_5083_50830301_50_dialog_content = "Entendido... De acordo com a cadeia de comando, eu deveria estar no comando agora, certo?",
  ui_story_5083_50830301_51_dialog_content = "Passe-me o mapa.",
  ui_story_5083_50830301_52_dialog_content = "Nossos batedores relatam que os Eclipsitas estão se concentrando nas terras altas ao norte. Não temos como atacá-los à distância agora.",
  ui_story_5083_50830301_53_dialog_content = "A maioria das funções da Subcidade foram desativadas após a primeira onda de ataques.",
  ui_story_5083_50830301_54_dialog_content = "Neste momento, não temos como saber se ou quando o comandante chegará com reforços.",
  ui_story_5083_50830301_55_dialog_content = "Além disso... Alguns dos soldados acreditam que deveríamos abandonar esta posição e evacuar junto com os civis.",
  ui_story_5083_50830301_56_dialog_content = "Mas isso significaria abandonar toda a Cidade Baixa, senhor!",
  ui_story_5083_50830301_57_dialog_content = "Quantas pessoas ainda temos?",
  ui_story_5083_50830301_58_dialog_content = "Menos de trezentos... Simplesmente não temos números suficientes para defender esta Subcidade mais.",
  ui_story_5083_50830301_59_dialog_content = "... Isso é muito mais difícil do que qualquer simulação militar, isso é certo.",
  ui_story_5083_50830301_60_dialog_content = "Não consigo acreditar que aquele velho pensou que poderíamos defender uma cidade inteira sozinhos... Se não tivéssemos arriscado nossas vidas para abrir caminho, provavelmente teríamos morrido lá atrás.",
  ui_story_5083_50830301_61_dialog_content = "Parece que só nos resta uma opção...",
  ui_story_5083_50830301_62_dialog_content = "Tenente Barton! <size=45>Um mensageiro chegou!</size>",
  ui_story_5083_50830301_63_dialog_content = "Entre. Por favor, me diga se você tem algumas boas notícias para nós.",
  ui_story_5083_50830301_64_dialog_content = "Sim, senhor! O ataque surpresa do Comandante Pango foi um enorme sucesso, e três subcidades foram salvas! Eles estão a caminho desta posição enquanto falamos!",
  ui_story_5083_50830301_65_dialog_content = "Suas ordens são para resistir até que eles cheguem!",
  ui_story_5083_50830301_66_dialog_content = "Pensei que você disse que eram boas notícias? Você viu o estado em que estamos agora?!",
  ui_story_5083_50830301_67_dialog_content = "Peço desculpas, senhor... O Comandante Pango sabe o quão difícil deve ser, mas três cidades baixas não teriam sido salvas se não fosse pela bravura e sacrifícios de seus soldados.",
  ui_story_5083_50830301_68_dialog_content = "Então, por favor, confie nele. A ajuda chegará em breve, senhor.",
  ui_story_5083_50830301_69_dialog_content = "Os Eclipsitas estão em movimento, Tenente Barton. Quais são suas ordens?",
  ui_story_5083_50830301_70_dialog_content = "Se recuarmos para a Subcidade antes da evacuação estar completa, não há garantia de que os Eclipsitas simplesmente não nos contornarão...",
  ui_story_5083_50830301_71_dialog_content = "Mas esta posição já está em ruínas... Não será fácil impedir que seja invadida—",
  ui_story_5083_50830301_72_dialog_content = "Então, nós atacamos.",
  ui_story_5083_50830301_73_dialog_content = "I'm sorry?",
  ui_story_5083_50830301_74_dialog_content = "Como oficial comandante, estou ordenando que todos os soldados se preparem para atacar o inimigo!",
  ui_story_5083_50830301_75_dialog_content = "Não podemos deixar esses monstros escaparem impunes!",
  ui_story_5083_50830301_76_dialog_content = "Pense nas pessoas que estão contando conosco! Pense em seus pais de volta em Gannon City... Você está disposto a se entregar e morrer como covardes neste lugar?",
  ui_story_5083_50830301_77_dialog_content = "P-Por favor, acalme-se, Tenente! As ordens do Comandante Pango eram para manter esta posição!",
  ui_story_5083_50830301_78_dialog_content = "Como você pode dizer isso? Estamos lutando sem parar há dez dias seguidos. Você está realmente sugerindo que nos escondamos aqui e esperemos pelo inevitável?",
  ui_story_5083_50830301_79_dialog_content = "Você não consegue sentir o medo em seus corações? Porque eu consigo, e me recuso a deixá-los morrer aqui!",
  ui_story_5083_50830301_80_dialog_content = "Os soldados da 2ª Legião nunca recuam e nunca se rendem!",
  ui_story_5083_50830301_81_dialog_content = "Se todos nós vamos morrer, então pelo menos vamos sair em uma explosão de glória!",
  ui_story_5083_50830301_82_dialog_content = "Barton... Você...",
  ui_story_5083_50830301_83_dialog_content = "Estamos indo direto ao inimigo e não vamos parar até forçá-los a recuar!",
  ui_story_5083_50830301_84_dialog_content = "<size=45>Todas as forças, peguem suas armas e fortaleçam sua determinação—</size>",
  ui_story_5083_50830301_85_dialog_content = "<size=45>ATAAAACAR!!!</size>",
  ui_story_5083_50830302_1_dialog_content = "<color=#e8d9bb>O chamado às armas de Barton ressoa na desolação da luz pré-amanhecer. Enquanto as chamas ameaçam engolir a Subcidade, uma luta brutal se desenrola.</color>",
  ui_story_5083_50830302_2_dialog_content = "Continue atirando! Não desista!",
  ui_story_5083_50830302_3_dialog_content = "Nós os pegamos desprevenidos! Agora é a nossa chance—",
  ui_story_5083_50830302_4_dialog_content = "*Rugido*",
  ui_story_5083_50830302_5_dialog_content = "Não pare! Nosso objetivo é retomar o terreno elevado e dar às nossas forças a chance de transportar nossa artilharia pesada para lá!",
  ui_story_5083_50830302_6_dialog_content = "<color=#e8d9bb>O clarim continua a sinalizar o avanço deles, e os bravos soldados de Illumina avançam ainda mais nas fileiras do inimigo.</color>",
  ui_story_5083_50830302_7_dialog_content = "Graaaaaah!",
  ui_story_5083_50830302_8_dialog_content = "Continue!",
  ui_story_5083_50830302_9_dialog_content = "<color=#e8d9bb>Sempre que o soldado segurando o clarim cai, outro rapidamente toma seu lugar.</color>",
  ui_story_5083_50830302_10_dialog_content = "Onde estão os artilheiros? Não fiquem para trás ainda!",
  ui_story_5083_50830302_11_dialog_content = "<color=#e8d9bb>Neste campo de batalha brutal, o rosto de Barton já está coberto de sangue e suor. Mesmo assim, ele ainda lidera a carga com a bandeira de Illumina erguida.</color>",
  ui_story_5083_50830302_12_dialog_content = "Eu te dou cobertura, agora vá!",
  ui_story_5083_50830302_13_dialog_content = "<color=#e8d9bb>Com uma bandeira em uma mão e a arma de fogo do seu camarada na outra, ele abre fogo contra os Eclipsitas enquanto eles descem a encosta—</color>",
  ui_story_5083_50830302_14_dialog_content = "Você não vai pegar isso de volta de mim!!!",
  ui_story_5083_50830302_15_dialog_content = "<color=#e8d9bb>Com um único impulso poderoso, Barton perfura o Eclipsite com sua bandeira e a planta firmemente no topo da colina. Logo, a luz de Illumina brilha nos olhos de cada soldado presente—</color>",
  ui_story_5083_50830302_16_dialog_content = "Venha me pegar, seus monstros imundos!",
  ui_story_5083_50830302_17_dialog_content = "Barton—!",
  ui_story_5083_50830302_18_dialog_content = "Essa voz... Cãozinho?!",
  ui_story_5083_50830302_19_dialog_content = "<color=#e8d9bb>Com o romper da aurora, Barton finalmente vê o campo de batalha através de sua visão manchada de sangue. À distância, um batalhão inteiro de soldados aparece.</color>",
  ui_story_5083_50830302_20_dialog_content = "Seu idiota... Não acredito que você correu direto para o ventre da fera!",
  ui_story_5083_50830302_21_dialog_content = "Acho que não há volta agora... Todas as forças, preparem-se para atacar o inimigo!",
  ui_story_5083_50830302_22_dialog_content = "Proteja o terreno elevado a todo custo, para que o Tenente Barton possa continuar a disparar fogo supressor!",
  ui_story_5083_50830302_23_dialog_content = "Sim, senhor!",
  ui_story_5083_50830302_24_dialog_content = "Hahaha! Meu reforço finalmente chegou, Eclipsitas—agora morram!",
  ui_story_5083_50830302_25_dialog_content = "<color=#e8d9bb>O clarim sinaliza carga após carga sangrenta. Os valentes soldados de Illumina continuam seu ataque implacável e, em breve, a maré escura recua sob a luz da alvorada.</color>",
  ui_story_5083_50830302_26_dialog_content = "<color=#e8d9bb>Enquanto o sol brilha sobre o campo de batalha, os corpos de inúmeros soldados são vistos formando uma barricada ao redor da Cidade Baixa. Mesmo na morte, eles continuam a defender sua casa.</color>",
  ui_story_5083_50830302_27_dialog_content = "Ei Barton... Você ainda está vivo?",
  ui_story_5083_50830302_28_dialog_content = "Urgh... Acho que sim... Não consigo ver através de todo esse sangue no meu rosto, mas não parece que estou faltando nenhuma parte importante.",
  ui_story_5083_50830302_29_dialog_content = "Seu idiota...",
  ui_story_5083_50830302_30_dialog_content = "Você estava prestes a morrer neste lugar, sabia disso? Que pesadelo...",
  ui_story_5083_50830302_31_dialog_content = "Shiu! Ouviu isso?",
  ui_story_5083_50830302_32_dialog_content = "<color=#e8d9bb>À medida que o sol fica mais brilhante, um poderoso chifre soa sem parar—</color>",
  ui_story_5083_50830302_33_dialog_content = "É a nossa força principal... O velhote finalmente chegou...",
  ui_story_5083_50830302_34_dialog_content = "Eles sério... Apareceram quando disseram que iriam... Droga...",
  ui_story_5083_50830302_35_dialog_content = "Dogg! Barton!",
  ui_story_5083_50830302_36_dialog_content = "... Onde diabos estão aqueles dois idiotas?!",
  ui_story_5083_50830302_37_dialog_content = "<color=#e8d9bb>Ao ver as pilhas de corpos espalhados pelo campo de batalha, o comandante de sangue-frio da 2ª Legião murmura em um tom trêmulo.</color>",
  ui_story_5083_50830302_38_dialog_content = "Todas essas crianças... Não...",
  ui_story_5083_50830302_39_dialog_content = "Cachorro! Barton! Você... Seus malditos idiotas!!! Não me diga...",
  ui_story_5083_50830302_40_dialog_content = "Você...",
  ui_story_5083_50830302_41_dialog_content = "Vocês idiotas ainda estão vivos!",
  ui_story_5083_50830302_42_dialog_content = "Comandante... Nossa missão... está completa, senhor.",
  ui_story_5083_50830302_43_dialog_content = "Desculpe, velhote... Não desistimos de nenhuma parte da Subcidade... mas... algumas coisas podem ter sido danificadas durante a luta...",
  ui_story_5083_50830302_44_dialog_content = "Isso mesmo... Ao repelir os Eclipsitas, você protegeu esta Subcidade e impediu que as outras duas fossem invadidas... Vocês venceram, rapazes.",
  ui_story_5083_50830302_45_dialog_content = "Barton... essa é a sua primeira vez liderando tropas e a taxa de baixas já é quase de um para dez?!",
  ui_story_5083_50830302_46_dialog_content = "<size=45>Como ousa você!!!</size> Eu deveria te submeter a uma corte marcial por desobedecer ordens e bancar o herói!!!",
  ui_story_5083_50830302_47_dialog_content = "Se matar é uma coisa, mas você quase matou o Dogg também!",
  ui_story_5083_50830302_48_dialog_content = "Mas ainda estamos vivos, não estamos?",
  ui_story_5083_50830302_49_dialog_content = "Nada disso teria acontecido se você tivesse apenas me ouvido!",
  ui_story_5083_50830302_50_dialog_content = "Vou registrar esse incidente no relatório e considerar seu primeiro comando um fracasso completo!",
  ui_story_5083_50830302_51_dialog_content = "O quê?! Mas você nos deu uma missão impossível! Se não tivéssemos levado a luta aos Eclipsitas, teríamos sido superados há muito tempo!",
  ui_story_5083_50830302_52_dialog_content = "Ei! Volte aqui, seu velho fedorento! Eu exijo uma explicação melhor do que essa!!",
  ui_story_5083_50830302_53_dialog_content = "Droga... Ele não viu o quão ruim estava aqui, e ainda está me dando problemas... Quase ficamos presos neste inferno!",
  ui_story_5083_50830302_54_dialog_content = "Dê um descanso, Barton. O comandante está apenas preocupado com você.",
  ui_story_5083_50830302_55_dialog_content = "Ele só está te repreendendo porque você quase morreu, só isso.",
  ui_story_5083_50830302_56_dialog_content = "Assim que ele percebeu que nossas comunicações estavam fora do ar, ele me enviou e à minha equipe à frente para fornecer reforços.",
  ui_story_5083_50830302_57_dialog_content = "...",
  ui_story_5083_50830302_58_dialog_content = "Agora levante-se. É hora de voltarmos...",
  ui_story_5083_50830302_59_dialog_content = "Vencemos? Vencemos! Eu realmente sobrevivi...",
  ui_story_5083_50830302_60_dialog_content = "Mas o líder do pelotão e os outros...",
  ui_story_5083_50830302_61_dialog_content = "Quase todos eles caíram em batalha...",
  ui_story_5083_50830302_62_dialog_content = "Um batalhão inteiro de soldados... assim como os reforços...",
  ui_story_5083_50830302_63_dialog_content = "... Quando me levantei agora, percebi que o comandante estava procurando nossos corpos o tempo todo... É por isso que sua voz estava tremendo mais cedo?",
  ui_story_5083_50830302_64_dialog_content = "Fiz a escolha errada, Dogg?",
  ui_story_5083_50830302_65_dialog_content = "Não adianta se preocupar com isso agora.",
  ui_story_5083_50830302_66_dialog_content = "Havia mais Eclipsitas do que nossos batedores relataram originalmente.",
  ui_story_5083_50830302_67_dialog_content = "Independentemente do que aconteceu, você conseguiu completar a missão.",
  ui_story_5083_50830302_68_dialog_content = "Não só você defendeu esta Subcidade, como também matou um grande número de Eclipsitas.",
  ui_story_5083_50830302_69_dialog_content = "... Os bravos homens e mulheres que lutaram ao seu lado morreram honrosamente e sem arrependimentos. Tenho certeza disso.",
  ui_story_5083_50830302_70_dialog_content = "Se... Se eu não tivesse dado a ordem para atacar...",
  ui_story_5083_50830302_71_dialog_content = "Haveria mais deles de pé agora?",
  ui_story_5083_50830302_72_dialog_content = "Não pense nisso.",
  ui_story_5083_50830302_73_dialog_content = "Isto é guerra, Barton. Ao contrário das nossas simulações militares, nada é garantido aqui.",
  ui_story_5083_50830302_74_dialog_content = "Mesmo os maiores comandantes não têm como saber se uma batalha seguirá de acordo com suas ordens.",
  ui_story_5083_50830302_75_dialog_content = "Mapas e modelos nunca podem refletir todas as partes da batalha, ou o espírito destemido dos soldados de Illumina.",
  ui_story_5083_50830302_76_dialog_content = "Sua contraofensiva foi bem-sucedida e você saiu vitorioso. Esses são os resultados da sua primeira vez no comando.",
  ui_story_5083_50830302_77_dialog_content = "Vitorioso, né...",
  ui_story_5083_50830302_78_dialog_content = "Quanto a onde melhorar e como salvar ainda mais vidas na próxima vez... Isso é para você pensar enquanto continuamos avançando.",
  ui_story_5083_50830302_79_dialog_content = "Talvez você tome uma decisão diferente na próxima vez. De qualquer forma, o resultado desta batalha já está decidido.",
  ui_story_5083_50830302_80_dialog_content = "E como sobreviventes, temos que suportar tudo. Não apenas o bom, mas também o ruim.",
  ui_story_5083_50830302_81_dialog_content = "Aceitando o resultado da batalha e compartilhando nossa vitória com o resto...",
  ui_story_5083_50830302_82_dialog_content = "É tudo o que podemos fazer como comandantes agora.",
  ui_story_5083_50830400_1_dialog_content = "Bip—Você tem uma nova mensagem, Barton.",
  ui_story_5083_50830400_2_dialog_content = "A seguinte mensagem é do Comandante Pango da 2ª Legião, e não reflete minhas opiniões pessoais—",
  ui_story_5083_50830400_3_dialog_content = "Ei, moleque! Você ainda não está deitado na cama, está?!",
  ui_story_5083_50830400_4_dialog_content = "Só porque não é dia de treino não significa que você pode relaxar!",
  ui_story_5083_50830400_5_dialog_content = "Leve seu traseiro arrependido para o setor residencial! Tenho um trabalho só para você!",
  ui_story_5083_50830400_6_dialog_content = "E esse trabalho é para, uh... Ahem, garantir que ninguém esteja vendendo suprimentos por baixo dos panos lá fora.",
  ui_story_5083_50830400_7_dialog_content = "Você tem um dia para terminar a missão! Não importa se você conseguir ou não, contanto que passe o dia inteiro no setor residencial! E nem pense em voltar mais cedo, entendeu?! Dispensado!",
  ui_story_5083_50830400_8_dialog_content = "Doce!",
  ui_story_5083_50830400_9_dialog_content = "Bip—Por que você está tão feliz? O comandante estava gritando com você.",
  ui_story_5083_50830400_10_dialog_content = "Ha, você não sabe disso, sabe? Passamos pelo andar superior do setor residencial o tempo todo, mas é proibido para passear.",
  ui_story_5083_50830400_11_dialog_content = "Eles estão sempre construindo novos prédios lá embaixo, então eu sempre quis conferir por mim mesmo!",
  ui_story_5083_50830400_12_dialog_content = "Bip—Por favor, pare de me sacudir...",
  ui_story_5083_50830400_13_dialog_content = "<size=45>Uhul! Hora de se divertir!!!</size>",
  ui_story_5083_50830400_14_dialog_content = "Você está parecendo muito elegante, Barton. Ouvi dizer que você está indo para o setor residencial hoje?",
  ui_story_5083_50830400_15_dialog_content = "Isso mesmo! Alguém precisa de algo do centro de distribuição? Estou indo para lá, então apenas me entregue seus vouchers, e eu pego suas coisas.",
  ui_story_5083_50830400_16_dialog_content = "H-Ei! Um de cada vez, ou os vouchers vão virar uma bagunça. Além disso, só consigo carregar até um certo ponto!",
  ui_story_5083_50830400_17_dialog_content = "O comandante disse que lhe deu uma missão, mas parece que ele só quer lhe dar um dia de folga.",
  ui_story_5083_50830400_18_dialog_content = "É mesmo? Acho que as habilidades sociais dele não são muito melhores que as suas, hein?",
  ui_story_5083_50830400_19_dialog_content = "... Apenas desapareça já, seu idiota!",
  ui_story_5083_50830400_20_dialog_content = "Confira! É a nova área de alocação que eles colocaram bem ao lado do setor residencial!",
  ui_story_5083_50830400_21_dialog_content = "Bip—Deve haver uma palavra melhor para isso do que plopped, Barton...",
  ui_story_5083_50830400_22_dialog_content = "Não faço ideia do que você está falando. Agora me aponte o lugar mais próximo para diversão; ainda tenho muitas compras para fazer!",
  ui_story_5083_50830400_23_dialog_content = "... E a sua missão?",
  ui_story_5083_50830400_24_dialog_content = "Ah, não se preocupe com isso. Até o Dogg acha que estou aqui para um descanso, então vamos apenas confiar nele.",
  ui_story_5083_50830400_25_dialog_content = "O Comandante Pango praticamente o criou. Eu não acho que ninguém conheça o velhote melhor do que ele.",
  ui_story_5083_50830400_26_dialog_content = "Agora vamos nos divertir! Mostre o caminho!",
  ui_story_5083_50830400_27_dialog_content = "Beep—Sim, Barton... Descobri um lugar conhecido como Arcade Oculto a 60 metros de distância, no beco à nossa direita.",
  ui_story_5083_50830400_28_dialog_content = "Um fliperama, hein... Eles realmente têm esse tipo de coisa na área de alocação? Ainda estamos em guerra, afinal... Vamos dar uma olhada.",
  ui_story_5083_50830400_29_dialog_content = "S-Sério?! Esses devem ser os videogames que eu ouvi falar na academia—",
  ui_story_5083_50830400_30_dialog_content = "Bem-vindo ao Arcade Oculto. Embora ainda estejamos em guerra, espero sinceramente que você encontre alguma paz e diversão aqui.",
  ui_story_5083_50830400_31_dialog_content = "Todos os nossos jogos foram projetados e desenvolvidos pelo chefe do fliperama. Novos clientes têm direito a uma rodada de jogo grátis!",
  ui_story_5083_50830400_32_dialog_content = "Se você alcançar uma pontuação alta no Naval King, pode escolher um prêmio que corresponda à sua pontuação!",
  ui_story_5083_50830400_33_dialog_content = "Caso falhe em sua tentativa, simplesmente troque seus vouchers por fichas e continue jogando para uma pontuação ainda mais alta!",
  ui_story_5083_50830400_34_dialog_content = "Seu chefe me parece um verdadeiro vencedor! Observe isso, vou vencer todo o nível de uma vez só!",
  ui_story_5083_50830400_35_dialog_content = "Fim de jogo! Pontuação: 5.",
  ui_story_5083_50830400_36_dialog_content = "Peço desculpas, senhor, mas você precisa de uma pontuação de 500 para uma camiseta do Rei Naval ou uma pontuação de 1.000 para o próprio jogo. Gostaria de trocar seus vales por alguns tokens?",
  ui_story_5083_50830400_37_dialog_content = "Porra certo que eu faço! Aqui está.",
  ui_story_5083_50830400_38_dialog_content = "Agora assista a isto—!",
  ui_story_5083_50830400_39_dialog_content = "Fim de jogo! Pontuação: 40.",
  ui_story_5083_50830400_40_dialog_content = "Ei, quantos vales custa para comprar aquela camiseta do Naval King?",
  ui_story_5083_50830400_41_dialog_content = "Heheh... Como você gastou o suficiente para obter o status VIP, agora tem o privilégio de comprá-lo por um voucher de 100 pontos. Gostaria de adquirir?",
  ui_story_5083_50830400_42_dialog_content = "Uau Barton, não pensei que você gostaria tanto dessa camisa.",
  ui_story_5083_50830400_43_dialog_content = "O-O que você está fazendo aqui?!",
  ui_story_5083_50830400_44_dialog_content = "Acontece que sou o desenvolvedor por trás de todos esses jogos! Bem, eu e o Negador.",
  ui_story_5083_50830400_45_dialog_content = "Dificilmente. Você é quem fez todo o trabalho, já que eu realmente não me importo com essas coisas.",
  ui_story_5083_50830400_46_dialog_content = "A propósito, Denier é meu júnior!",
  ui_story_5083_50830400_47_dialog_content = "Eu ouvi falar de você, Barton... Não é uma pontuação ruim que você conseguiu.",
  ui_story_5083_50830400_48_dialog_content = "Uh, oi... Escute Gronru, suas máquinas de jogo engoliram um monte dos meus vouchers.",
  ui_story_5083_50830400_49_dialog_content = "Eu deveria usar alguns deles para comprar coisas para meus companheiros de equipe, então você poderia...",
  ui_story_5083_50830400_50_dialog_content = "Hahaha, eu não esperava que você fosse tão ruim em videogames! Ainda assim, estou grato que você tenha gostado tanto deles.",
  ui_story_5083_50830400_51_dialog_content = "Agora eu sei que será um enorme sucesso com todos!",
  ui_story_5083_50830400_52_dialog_content = "Parece que testá-los aqui foi a decisão certa afinal. Eu até recuperei parte do dinheiro que investi nesses jogos!",
  ui_story_5083_50830400_53_dialog_content = "... Espere, então você está administrando um negócio privado para lucrar aqui?",
  ui_story_5083_50830400_54_dialog_content = "Quer dizer, nós oferecemos testes gratuitos... Então isso não deve ser um problema, certo?",
  ui_story_5083_50830400_55_dialog_content = "Suspiro, é um grande problema, Gronru. Quando você for preso, tente não me arrastar junto com você.",
  ui_story_5083_50830400_56_dialog_content = "Como se! Eu vou dizer a eles que você me ajudou a construir todas essas máquinas de jogos!",
  ui_story_5083_50830400_57_dialog_content = "O quê?! Eu-Eu só ajudei porque você me ordenou, Oficial de Tecnologia!",
  ui_story_5083_50830400_58_dialog_content = "Sim, mas você gostou, não é?",
  ui_story_5083_50830400_59_dialog_content = "No que diz respeito à pesquisa... Acho que foi bem divertido.",
  ui_story_5083_50830400_60_dialog_content = "Vê? E eu posso dizer que você também está interessado nesses jogos, Barton. Acha que pode me deixar fora do gancho desta vez?",
  ui_story_5083_50830400_61_dialog_content = "Bem, eu gosto de mexer com novos gadgets tanto quanto o próximo. Sabe de uma coisa, me devolva os vouchers, e vou fingir que isso nunca aconteceu.",
  ui_story_5083_50830400_62_dialog_content = "Ah, não seja assim! Qual o problema em patrocinar um pouco o nosso estabelecimento?",
  ui_story_5083_50830400_63_dialog_content = "Afinal, cada nova peça de tecnologia que eu desenvolvo é projetada para ajudar soldados de linha de frente como você.",
  ui_story_5083_50830400_64_dialog_content = "Ajudar, huh... Espera, isso me lembra! Você reconhece este drone?",
  ui_story_5083_50830400_65_dialog_content = "Huh? Para onde foi?",
  ui_story_5083_50830400_66_dialog_content = "Que drone?",
  ui_story_5083_50830400_67_dialog_content = "É este drone de aparência antiga que veio até mim mais cedo hoje. Ele se chama de meu Navegador!",
  ui_story_5083_50830400_68_dialog_content = "Eu tenho seguido e conversado com ele o dia todo.",
  ui_story_5083_50830400_69_dialog_content = "Uau, isso soa bem tecnológico, não é, Negador?",
  ui_story_5083_50830400_70_dialog_content = "Concordo. Não acho que a Illumina tenha esse tipo de tecnologia inteligente ainda, e para você dizer que é \"antiga\" faz ainda menos sentido...",
  ui_story_5083_50830400_71_dialog_content = "Sério? Porque eu pensei que você o fez. Imagino onde o pequeno foi... Bem, tenho certeza que ele não pode se perder, já que é um drone de navegação e tudo mais.",
  ui_story_5083_50830400_72_dialog_content = "Eu vou mostrar para você na próxima vez que eu tiver uma chance.",
  ui_story_5083_50830400_73_dialog_content = "Gostaria de dar uma olhada também... Qualquer coisa que leve a um futuro mais forte sempre me interessará.",
  ui_story_5083_50830400_74_dialog_content = "Aqui estão seus vouchers, Barton. Não se esqueça de manter este lugar como nosso pequeno segredo, okay?",
  ui_story_5083_50830400_75_dialog_content = "Com certeza, e obrigado! Raramente tenho a chance de ver esta parte da cidade, então ainda não estou pronto para voltar. Que tal eu oferecer a vocês dois uma boa refeição?",
  ui_story_5083_50830400_76_dialog_content = "Conte comigo! Eu sabia que você era um bom sujeito, Barton!",
  ui_story_5083_50830400_77_dialog_content = "Também já comi bastante da comida do laboratório, então obrigado... E se for realmente boa, gostaria de recomendá-la à minha irmã.",
  ui_story_5083_50830400_78_dialog_content = "Ah sim! Ei Barton, você sabia que a irmã mais velha dela é nada menos que a grande Reinhardt?",
  ui_story_5083_50830400_79_dialog_content = "Não coloque dessa maneira, Gronru. Isso é embaraçoso.",
  ui_story_5083_50830400_80_dialog_content = "Sério? Eu não poderia dizer de jeito nenhum, já que sua irmã brilha mais do que qualquer outra pessoa.",
  ui_story_5083_50830400_81_dialog_content = "... Eu a alcançarei algum dia.",
  ui_story_5083_50830400_82_dialog_content = "É mesmo? Porque eu acho que você já está indo muito bem - Agora vamos comer!",
  ui_story_5083_50830400_83_dialog_content = "Isso não foi nada mal. Acho que posso recomendar para... Ela.",
  ui_story_5083_50830400_84_dialog_content = "Hmm... Vocês dois realmente são muito diferentes um do outro.",
  ui_story_5083_50830400_85_dialog_content = "Eu sei que você já viu Reinhardt em ação, mas ainda não teve a chance de ver o negador brilhar, Barton.",
  ui_story_5083_50830400_86_dialog_content = "Você gosta de simulações militares, certo? Talvez vocês dois possam jogar uma partida.",
  ui_story_5083_50830400_87_dialog_content = "Eu estaria bem com qualquer outra competição, mas um teste de estratégias de combate contra um pesquisador? Claro, pode vir!",
  ui_story_5083_50830400_88_dialog_content = "Eu não pedi para você me causar problemas, Gronru... Mas tudo bem. Eu aceito seu desafio, Tenente Barton. Mas já aviso: eu não me subestimaria se fosse você.",
  ui_story_5083_50830400_89_dialog_content = "<color=#e8d9bb>O grupo retorna à loja escondida de Gronru, onde Barton e Negador participam de uma batalha simulada em uma mesa de areia.</color>",
  ui_story_5083_50830400_90_dialog_content = "<color=#e8d9bb>Para surpresa de Barton, as táticas do Negador são muito mais cruéis e implacáveis do que ele esperava de um Pesquisador.</color>",
  ui_story_5083_50830400_91_dialog_content = "<color=#e8d9bb>Ao sacrificar peão após peão, ela avança mais fundo no território de Barton, o que o pega de surpresa. Quando ele percebe a precariedade de sua situação, já está a momentos da derrota.</color>",
  ui_story_5083_50830400_92_dialog_content = "(Isso não é bom! Eu já perdi para Gronru; não posso me dar ao luxo de perder para o amigo dela também!)",
  ui_story_5083_50830400_93_dialog_content = "<color=#e8d9bb>Corando de vergonha, Barton de repente bate sua próxima peça na posição, danificando o lado do tabuleiro do negador.</color>",
  ui_story_5083_50830400_94_dialog_content = "<color=#e8d9bb>Enquanto ela se apressa para reposicionar suas peças, Barton pressiona sua vantagem e lança uma série de ataques.</color>",
  ui_story_5083_50830400_95_dialog_content = "Foi um movimento sujo, Barton... Vê? O negador está prestes a chorar...",
  ui_story_5083_50830400_96_dialog_content = "A moral não significa nada no campo de batalha; tudo o que importa é vencer ou perder! Meu comandante me ensinou a vencer a todo custo, e é exatamente isso que vou fazer!",
  ui_story_5083_50830400_97_dialog_content = "<color=#e8d9bb>Apesar de suas palavras duras, a lacuna já era muito difícil de ser preenchida. Depois de colocar suas peças de volta no tabuleiro de areia, Denier recupera sua compostura de forma trêmula.</color>",
  ui_story_5083_50830400_98_dialog_content = "<color=#e8d9bb>Isca, flanqueamento e esmagamento de seu oponente ao sacrificar constantemente suas peças... Foi assim que a negadora saiu vitoriosa em sua batalha.</color>",
  ui_story_5083_50830400_99_dialog_content = "Hahahaha! Parece que ela te superou tanto em estratégia quanto em modos, Barton!",
  ui_story_5083_50830400_100_dialog_content = "Você se chama tenente com essas táticas desonestas? Só espere até eu contar...",
  ui_story_5083_50830400_101_dialog_content = "Er... E-Espera aí, vocês dois! Vocês não podem contar a ninguém sobre o que aconteceu aqui hoje! Por favor!",
  ui_story_5083_50830400_102_dialog_content = "Se a notícia se espalhar, nunca vou superar isso! <size=45>Por favor! Eu farei qualquer coisa!!!</size>",
  ui_story_5083_50830500_1_dialog_content = "<color=#e8d9bb>Um Barton de aparência sombria reaparece nos portões do acampamento carregando várias bolsas de diferentes tamanhos. Eu tenho que ir avisá-lo—</color>",
  ui_story_5083_50830500_2_dialog_content = "Onde você foi? Você desapareceu por meio dia, sabia...",
  ui_story_5083_50830500_3_dialog_content = "Bip—Perigo, Barton—",
  ui_story_5083_50830500_4_dialog_content = "Que perigo? Estamos no acampamento... Hã?",
  ui_story_5083_50830500_5_dialog_content = "<color=#e8d9bb>Reinhardt está no centro do campo de treinamento da 2ª Legião, com uma lança na mão. Parece que ela está esperando há muito tempo.</color>",
  ui_story_5083_50830500_6_dialog_content = "Ela parece pronta para matar alguém. Quem será que a irritou?",
  ui_story_5083_50830500_7_dialog_content = "...",
  ui_story_5083_50830500_8_dialog_content = "<size=45>Barton—!</size>",
  ui_story_5083_50830500_9_dialog_content = "Como você ousa usar truques baratos contra minha irmã! Eu vou te ensinar uma lição que você nunca vai esquecer!!",
  ui_story_5083_50830500_10_dialog_content = "O que ela é, uma criança? Como ela poderia contar para a irmã sobre mim?!",
  ui_story_5083_50830500_11_dialog_content = "Bip—Curso de ação sugerido: CORRA!",
  ui_story_5083_50830500_12_dialog_content = "Aqui estão suas coisas, todos! Desculpe, mas eu tenho que ir—",
  ui_story_5083_50830500_13_dialog_content = "Volte aqui, seu covarde!!!",
  ui_story_5083_50830500_14_dialog_content = "<color=#e8d9bb>Reinhardt persegue impiedosamente Barton, sua lança ardente cortando a escuridão da noite o tempo todo.</color>",
  ui_story_5083_50830500_15_dialog_content = "Ei, pare com isso já! Eu vou revidar se isso continuar.",
  ui_story_5083_50830500_16_dialog_content = "Acha que pode me intimidar da mesma maneira que intimidou minha irmã? Então venha!",
  ui_story_5083_50830500_17_dialog_content = "Pare de balançar essa coisa enquanto está falando! É perigoso!",
  ui_story_5083_50830500_18_dialog_content = "<color=#e8d9bb>Barton continua a fugir de Reinhardt, que se recusa a deixá-lo ir. Em pouco tempo, os dois percorrem o comprimento de três ruas inteiras—</color>",
  ui_story_5083_50830500_19_dialog_content = "Tudo bem, isso basta! Toma isso!",
  ui_story_5083_50830500_20_dialog_content = "Areia? Sério? Você é desprezível.",
  ui_story_5083_50830500_21_dialog_content = "Faça o que for necessário para vencer! Agora toma essa!",
  ui_story_5083_50830500_22_dialog_content = "<color=#FFB400>Lança Perfuradora de Estrelas</color>!",
  ui_story_5083_50830500_23_dialog_content = "<color=#e8d9bb>Os dois lutam de um lado para o outro na rua, causando uma quantidade considerável de pânico. Soldados correm para a cena, mas não têm certeza de como acabar com a briga selvagem.</color>",
  ui_story_5083_50830500_24_dialog_content = "Espero que você esteja pronto para o meu estilo de cachimbo de água!",
  ui_story_5083_50830500_25_dialog_content = "Toma essa!",
  ui_story_5083_50830500_26_dialog_content = "Haha, nada mal! Mantem!",
  ui_story_5083_50830500_27_dialog_content = "<size=45>Parem com isso, seus palhaços!</size>",
  ui_story_5083_50830500_28_dialog_content = "Brigando entre si como um bando de crianças... Se estão se sentindo tão inquietos, então voltem para o campo de treinamento e me deem cem voltas cada um!!!",
  ui_story_5083_50830500_29_dialog_content = "Ah, isso é tudo culpa sua. Agora eu também tenho que correr cem voltas.",
  ui_story_5083_50830500_30_dialog_content = "Você acha que não merece isso depois de intimidar seus juniores?",
  ui_story_5083_50830500_31_dialog_content = "Você fala como se sua irmã não tivesse usado as táticas mais desumanas para me vencer... Não tenho certeza se ela precisa que você a defenda assim.",
  ui_story_5083_50830500_32_dialog_content = "Parem com essa briga e apressem o passo, seus idiotas!",
  ui_story_5083_50830500_33_dialog_content = "Sinta-se à vontade para lutar novamente depois de terminar suas cem voltas, supondo que você ainda consiga ficar de pé depois!",
  ui_story_5083_50830500_34_dialog_content = "Arf, arf...",
  ui_story_5083_50830500_35_dialog_content = "Uau, você não está levando isso a sério, está? Heh... Agora estou realmente empolgado! Vamos lá!",
  ui_story_5083_50830500_36_dialog_content = "Apenas tente me acompanhar! Ainda vou te bater mesmo que você não consiga ficar de pé!",
  ui_story_5083_50830500_37_dialog_content = "<color=#e8d9bb>Os dois jovens soldados correram ao redor da pista com toda a sua força. À medida que o número de voltas aumentava, seus passos também se tornavam cada vez mais fatigados.</color>",
  ui_story_5083_50830500_38_dialog_content = "Estou surpreso que você conseguiu acompanhar... Mas eu ainda não acabei!",
  ui_story_5083_50830500_39_dialog_content = "<color=#e8d9bb>Sessenta voltas, setenta voltas... Seus passos se tornaram lentos e erráticos, como se suas pernas estivessem cheias de chumbo.</color>",
  ui_story_5083_50830500_40_dialog_content = "Esse castigo pode ser um pouco demais, Comandante Pango...",
  ui_story_5083_50830500_41_dialog_content = "Eu pedi a sua opinião? As pessoas ainda estão limpando a bagunça que eles deixaram, sabia!",
  ui_story_5083_50830500_42_dialog_content = "Já que esses arruaceiros arrogantes adoram tanto lutar, achei que deveria fazê-los sofrer um pouco mais hoje.",
  ui_story_5083_50830500_43_dialog_content = "<color=#e8d9bb>Oitenta voltas, noventa voltas... Os dois começam a cambalear de um lado para o outro, mas continuam se incentivando até o fim.</color>",
  ui_story_5083_50830500_44_dialog_content = "Ei... Ainda tem alguma luta em você?",
  ui_story_5083_50830500_45_dialog_content = "Você... realmente precisa perguntar? Tudo o que consigo pensar... é em como vou lidar com essa sua lança.",
  ui_story_5083_50830500_46_dialog_content = "<color=#e8d9bb>Noventa e nove, cem—O apito do comandante sinaliza o fim do seu castigo exaustivo, e os dois imediatamente desabam no chão.</color>",
  ui_story_5083_50830500_47_dialog_content = "Você... ainda está vivo... lá?",
  ui_story_5083_50830500_48_dialog_content = "Sim... ainda respirando...!",
  ui_story_5083_50830500_49_dialog_content = "Ainda quer... lutar? Estou pronto... quando você estiver...",
  ui_story_5083_50830500_50_dialog_content = "Heh... Eu não vou lutar contra você... Se você nem consegue se levantar, mas não se preocupe, eu aceito qualquer desafio seu a qualquer dia.",
  ui_story_5083_50830500_51_dialog_content = "Ah é...? Que nobre da sua parte... Hahaha—tosse, tosse—",
  ui_story_5083_50830500_52_dialog_content = "<color=#e8d9bb>Reinhardt ri alto, mas uma crise de tosse rapidamente põe fim a isso. No entanto, ela consegue se levantar e estende a mão.</color>",
  ui_story_5083_50830500_53_dialog_content = "Tosses, considere-se meu rival. Você mereceu isso.",
  ui_story_5083_50830500_54_dialog_content = "Seu comandante tem um bom argumento. Somos todos soldados de Illumina - uma pequena competição é saudável, mas não devemos lutar entre nós.",
  ui_story_5083_50830500_55_dialog_content = "De acordo com a etiqueta da Illumina, devemos apertar as mãos e fazer as pazes.",
  ui_story_5083_50830500_56_dialog_content = "Você possui todas as qualidades que procuro em uma pessoa, e tenho certeza de que precisarei da sua ajuda no futuro.",
  ui_story_5083_50830500_57_dialog_content = "Inacreditável... Você é ainda mais convencido do que eu pensava, e ainda é apenas um novo recruta.",
  ui_story_5083_50830500_58_dialog_content = "Não vai doer te contar, mas eu tenho esse pequeno sonho de me tornar Grande Marechal algum dia.",
  ui_story_5083_50830500_59_dialog_content = "Você chama isso de \"pequeno sonho\"? Interessante...",
  ui_story_5083_50830500_60_dialog_content = "Tudo bem, eu acredito em você! Não há como fingir o tipo de presença que você emana, isso é certo.",
  ui_story_5083_50830500_61_dialog_content = "Estamos quites por enquanto, mas não fique arrogante! Teremos muitas chances de competir no futuro.",
  ui_story_5083_50830500_62_dialog_content = "Ansioso por isso.",
  ui_story_5083_50830500_63_dialog_content = "Aquele olhar em seus olhos me disse que ela estava falando sério. Sua luz brilha ainda mais do que a do comandante.",
  ui_story_5083_50830500_64_dialog_content = "Hmph, Illumina estará muito melhor com alguém assim no comando... Mal posso esperar para ver onde ela vai!",
  ui_story_5083_50830500_65_dialog_content = "O que você está murmurando, Barton? Venha aqui!",
  ui_story_5083_50830500_66_dialog_content = "Nossa Legião finalmente está totalmente composta novamente, então é hora da nossa tradicional foto em grupo.",
  ui_story_5083_50830500_67_dialog_content = "O Comandante Pango ficou por perto porque queria esperar por você. Não é de admirar que ele ficou tão bravo quando te viu lutando com Reinhardt! Agora apresse-se e venha para cá!",
  ui_story_5083_50830500_68_dialog_content = "Uma foto de grupo... Claro!",
  ui_story_5083_50830500_69_dialog_content = "Aqui, nós guardamos um lugar para você bem ao lado do Comandante Pango.",
  ui_story_5083_50830500_70_dialog_content = "Obrigada!",
  ui_story_5083_50830500_71_dialog_content = "Hmph, ainda andando, hein? Acho que meu treinamento não foi totalmente desperdiçado em você, afinal.",
  ui_story_5083_50830500_72_dialog_content = "Ainda sou jovem e cheio de vida, ao contrário de um certo comandante—",
  ui_story_5083_50830500_73_dialog_content = "Já chega, vocês dois... É hora do seu discurso, Comandante.",
  ui_story_5083_50830500_74_dialog_content = "Hunf...",
  ui_story_5083_50830500_75_dialog_content = "Hunf...",
  ui_story_5083_50830500_76_dialog_content = "... Soldados da 2ª Legião! Estamos reunidos aqui hoje para celebrar a sua formatura do campo de treinamento! Parabéns por sobreviverem ao programa de treinamento deste velhote!",
  ui_story_5083_50830500_77_dialog_content = "Tenho orgulho de dizer que moldei cada um de vocês nos melhores guerreiros da Illumina. Mas não se enganem: os Eclipsitas que vocês enfrentarão no futuro são cem vezes mais brutais!",
  ui_story_5083_50830500_78_dialog_content = "Mas como soldados da 2ª Legião, nunca recuaremos ou nos renderemos! Agora, vamos acabar com isso, para que você possa ir para casa e aproveitar seus três dias de folga bem merecidos!",
  ui_story_5083_50830500_79_dialog_content = "Três vivas para o Comandante Pango!",
  ui_story_5083_50830500_80_dialog_content = "Não me agradeça ainda! O futuro não será fácil para nenhum de vocês; quando voltarem das linhas de frente, esperem mais treinamento do seu querido velho comandante! É tudo!",
  ui_story_5083_50830500_81_dialog_content = "Tudo bem, agora todos sorriem bastante — Splendor Illumina!",
  ui_story_5083_50830500_82_dialog_content = "<size=45>Splendor Illumina!</size>",
  ui_story_5083_50830600_1_dialog_content = "O tempo de férias está quase acabando, então não me deixe te pegar relaxando!",
  ui_story_5083_50830600_2_dialog_content = "Com certeza vou trabalhar duro na minha pontaria, Comandante!",
  ui_story_5083_50830600_3_dialog_content = "Se você atirar em um Eclipsite e ele cair em cima de você, os que estão atrás dele pularão em você imediatamente. Como você espera manter um tiro limpo nessas circunstâncias?",
  ui_story_5083_50830600_4_dialog_content = "Além disso, existem Eclipsitas lá fora que são imunes a armas de fogo. O que você precisa fazer é treinar sua esgrima, Barton!",
  ui_story_5083_50830600_5_dialog_content = "Uma boa arma de combate corpo a corpo nunca te decepcionará! Contanto que você se lembre disso ao desembainhar sua lâmina, nunca se encontrará preso pelo inimigo!",
  ui_story_5083_50830600_6_dialog_content = "...",
  ui_story_5083_50830600_7_dialog_content = "Um soldado da Illumina não teme a morte! Todos os dias, lutamos com nossas vidas para libertar Astra da praga Eclipsita! O que tememos, no entanto, é morrer uma morte sem sentido!",
  ui_story_5083_50830600_8_dialog_content = "É por isso que permanecer vivo deve ser sua primeira prioridade na batalha! Eu fui claro?!",
  ui_story_5083_50830600_9_dialog_content = "Sim, senhor!",
  ui_story_5083_50830600_10_dialog_content = "Então mãos à obra, soldado! Não desperdice seu tempo como fez nos últimos dois dias!",
  ui_story_5083_50830600_11_dialog_content = "... Como soldados veteranos, não há como continuarmos perdendo para os novos recrutas da 1ª Legião.",
  ui_story_5083_50830600_12_dialog_content = "Entendido, Comandante!",
  ui_story_5083_50830600_13_dialog_content = "Assim como Dogg, o Comandante Pango tem dificuldade em dizer o que está em sua mente.",
  ui_story_5083_50830600_14_dialog_content = "Você pensaria que uma pessoa mais velha seria mais direta sobre as coisas... Ele realmente deve querer que eu coloque Reinhardt em seu lugar, hein?",
  ui_story_5083_50830600_15_dialog_content = "Bip—Não tenho certeza se isso está totalmente correto, Barton.",
  ui_story_5083_50830600_16_dialog_content = "Hahaha! Você é bem tímido para um drone, sabia? Você sempre parece desaparecer quando outras pessoas aparecem. De qualquer forma, você é suposto ser meu Navegador, certo?",
  ui_story_5083_50830600_17_dialog_content = "... Precisa de direções?",
  ui_story_5083_50830600_18_dialog_content = "Não, mas tem um lugar que eu quero ver hoje. Vamos lá.",
  ui_story_5083_50830600_19_dialog_content = "Beep—Você quer passar seu último dia de folga em um museu, Barton?",
  ui_story_5083_50830600_20_dialog_content = "É assim que é conosco, soldados; se não estamos lutando, estamos treinando para uma luta. Além disso, todo lugar é basicamente o mesmo quando você vive no subsolo.",
  ui_story_5083_50830600_21_dialog_content = "... Ainda assim, seria bom ter uma das máquinas de jogos de Gronru em casa para passar o tempo.",
  ui_story_5083_50830600_22_dialog_content = "Se não estivéssemos em guerra, sinto que poderia jogar jogos pelo resto da minha vida.",
  ui_story_5083_50830600_23_dialog_content = "Isso ou montar uma equipe de exploração para navegar pelos mares.",
  ui_story_5083_50830600_24_dialog_content = "<color=#FFB400>Paz</color>... Haha! Só de pensar nisso já é suficiente para mim.",
  ui_story_5083_50830600_25_dialog_content = "Beep—Ativando o modo de orientação do Museu Illumina.",
  ui_story_5083_50830600_26_dialog_content = "<color=#FFB400>Cidade Baixa 80</color>, originalmente o setor mais próximo da Zona Escura.",
  ui_story_5083_50830600_27_dialog_content = "Durante a Guerra da Zona Cega, esta Subcidade contribuiu com serviços de transporte essenciais para o esforço de guerra da Illumina.",
  ui_story_5083_50830600_28_dialog_content = "O Comandante Pango também mencionou isso antes... Segundo ele, a batalha que ocorreu lá foi especialmente brutal, e a 2ª Legião foi quase totalmente dizimada.",
  ui_story_5083_50830600_29_dialog_content = "Como crianças, passávamos muito tempo aprendendo sobre o passado nesses museus. Costumávamos ter tanta inveja dessas lendas... Eles eram os mais legais.",
  ui_story_5083_50830600_30_dialog_content = "Mas agora eu sei os tipos de sacrifícios que foram feitos para criar essas lendas... E isso não é algo que eu quero ver mais.",
  ui_story_5083_50830600_31_dialog_content = "Seguindo em frente... Acredita-se que a Crise Darkover, que continua até hoje, tenha começado com o ataque a Eraveil dois anos atrás... Até onde sabemos, os Celestitas foram completamente...",
  ui_story_5083_50830600_32_dialog_content = "Huh? Por que você parou de repente...?",
  ui_story_5083_50830600_33_dialog_content = "Ei, Barton.",
  ui_story_5083_50830600_34_dialog_content = "O que está fazendo aqui?",
  ui_story_5083_50830600_35_dialog_content = "Aprimorando meu conhecimento em história, é claro. A história da Illumina, a história da guerra, esse tipo de coisa.",
  ui_story_5083_50830600_36_dialog_content = "... O que você acha que a Illumina será no futuro, Barton?",
  ui_story_5083_50830600_37_dialog_content = "Por que pergunta?",
  ui_story_5083_50830600_38_dialog_content = "Os misteriosos Celestitas foram exterminados por um único ataque surpresa. Por causa disso, nós, aurorianos, nunca mais receberemos sua orientação.",
  ui_story_5083_50830600_39_dialog_content = "A <color=#FFB400>Crise Darkover</color> ainda não acabou, e continuamos perdendo cada vez mais soldados. Olhe pela janela—Você consegue ver o memorial aos caídos daqui, não consegue?",
  ui_story_5083_50830600_40_dialog_content = "Os nomes de cada irmão e irmã que perdemos na guerra estão gravados lá... Mas eu ainda posso ouvir suas vozes ecoando na minha cabeça.",
  ui_story_5083_50830600_41_dialog_content = "Todos nós começamos a aprender história desde jovens... E quanto mais velho fico, mais próximo me sinto das coisas que são preservadas aqui.",
  ui_story_5083_50830600_42_dialog_content = "Depois de ver meus amigos darem suas vidas na batalha, apenas para que seus sacrifícios se tornassem lições de história para as gerações futuras... Comecei a me sentir confuso, Barton.",
  ui_story_5083_50830600_43_dialog_content = "Confuso?",
  ui_story_5083_50830600_44_dialog_content = "Astra está em perigo mortal, e embora eu esteja disposto a dar minha vida por ela, simplesmente não consigo ver o seu futuro...",
  ui_story_5083_50830600_45_dialog_content = "Você sabe que o povo de Lumópolis está lutando entre si agora, certo? A promessa deles de nos ajudar nunca se concretizou, e já paramos de trocar recursos com eles.",
  ui_story_5083_50830600_46_dialog_content = "Todo o Astra está em ruínas agora. Não tenho certeza pelo que estou lutando mais, ou se podemos até mesmo vencer.",
  ui_story_5083_50830600_47_dialog_content = "... Você está com medo?",
  ui_story_5083_50830600_48_dialog_content = "Claro que estou com medo... A sorte foi a única razão pela qual sobrevivemos quando o resto dos nossos camaradas não sobreviveu.",
  ui_story_5083_50830600_49_dialog_content = "Você me disse que isso era algo que tínhamos que suportar pelo resto de nossas vidas. Estou fazendo o meu melhor para viver com isso...",
  ui_story_5083_50830600_50_dialog_content = "Você sabia que o Comitê tem interferido nos planos do Grande Marechal? Eles ainda não conseguem decidir a melhor maneira de prosseguir com a guerra. Bem tranquilizador, hein?",
  ui_story_5083_50830600_51_dialog_content = "Ainda assim, aposto que meu medo não é nada comparado ao dos soldados que voltaram da Guerra da Zona Cega.",
  ui_story_5083_50830600_52_dialog_content = "Como está, a Illumina não tem um capitão claro no comando. Isso não te assusta, Barton?",
  ui_story_5083_50830600_53_dialog_content = "Se for esse o caso, então faremos isso.",
  ui_story_5083_50830600_54_dialog_content = "Você, eu e aquela Reinhardt garota da 1ª Legião!",
  ui_story_5083_50830600_55_dialog_content = "Temos permissão para opinar sobre as coisas, certo?",
  ui_story_5083_50830600_56_dialog_content = "Afinal, estamos falando do futuro! Quem melhor para enfrentar os desafios do que a próxima geração de líderes?",
  ui_story_5083_50830600_57_dialog_content = "Não importa o que alguém pense, eu nunca vou recuar. Não vou deixar a Illumina naufragar só porque ninguém consegue descobrir como conduzi-la!",
  ui_story_5083_50830600_58_dialog_content = "Então, se você não tem certeza do que fazer, apenas coloque sua vida em minhas mãos e eu mostrarei o caminho!",
  ui_story_5083_50830600_59_dialog_content = "Heh... Pra um cara que não tem pernas de mar, até que é durão.",
  ui_story_5083_50830600_60_dialog_content = "*Suspira* Eu apenas... Não sei como você pode ser tão confiante enquanto eu ainda estou preso dentro da minha própria cabeça.",
  ui_story_5083_50830600_61_dialog_content = "Também sou uma criança de Illumina, Barton. Não há como dizer quem estará no comando deste navio no futuro.",
  ui_story_5083_50830600_62_dialog_content = "Mas uma coisa é certa: vou provar ao Comandante Pango que sou o soldado de elite que ele esperava todo esse tempo!",
  ui_story_5083_50830600_63_dialog_content = "Faça o que quiser, Dogg. Não é como se eu estivesse tentando impressionar aquele velhote ou algo assim.",
  ui_story_5083_50830600_64_dialog_content = "Na verdade, fiz um pedido antes de vir aqui hoje - quero montar uma unidade de comando para a 2ª Legião.",
  ui_story_5083_50830600_65_dialog_content = "Depois do que aconteceu da última vez, percebi que nossas defesas caem rapidamente quando nos deparamos com Eclipsitas.",
  ui_story_5083_50830600_66_dialog_content = "É por isso que quero estabelecer um <color=#FFB400>ramo de assalto</color> e treinar soldados para levar a luta aos Eclipsitas. Tenho certeza de que precisaremos de lutadores assim no futuro.",
  ui_story_5083_50830600_67_dialog_content = "Se ao menos Lumópolis decidisse trabalhar conosco... Eles poderiam ter nos ajudado a treinar soldados montados.",
  ui_story_5083_50830600_68_dialog_content = "Sei que a tecnologia vai decidir muitas batalhas para nós no futuro... Mas não há como negar a importância das unidades terrestres também.",
  ui_story_5083_50830600_69_dialog_content = "E, dado que nossos níveis de produção ainda estão atrasados, só podemos contar com o aço frio para abrir um caminho e manter o inimigo à distância.",
  ui_story_5083_50830600_70_dialog_content = "Essa é uma percepção impressionante, Dogg... Para ser honesto, não pensei tanto nas coisas.",
  ui_story_5083_50830600_71_dialog_content = "Mas se esse é o seu plano, então por que você quer tanto a aprovação do comandante? Por que você sente que precisa provar a si mesmo?",
  ui_story_5083_50830600_72_dialog_content = "Ele é o nosso comandante e nos treinou ao máximo de suas habilidades. Não é motivo suficiente?",
  ui_story_5083_50830600_73_dialog_content = "É, mas tenho certeza de que não é a única razão.",
  ui_story_5083_50830600_74_dialog_content = "Heh... Apesar de ser um idiota musculoso, você pode ser bastante perspicaz às vezes.",
  ui_story_5083_50830600_75_dialog_content = "... Meu velhote era bons amigos com o Comandante Pango naquela época. Foi assim que ele acabou cuidando de mim.",
  ui_story_5083_50830600_76_dialog_content = "Ele me criou e cuidou de mim como se eu fosse seu próprio filho. Para mim, o Comandante Pango não é diferente do meu pai.",
  ui_story_5083_50830600_77_dialog_content = "Seu filho era meu irmão mais velho, e sua esposa era minha mãe.",
  ui_story_5083_50830600_78_dialog_content = "Eu não sabia que o comandante tinha uma família... Aconteceu algo com eles...?",
  ui_story_5083_50830600_79_dialog_content = "Seis anos atrás, a Subcidade onde vivíamos sofreu um ataque.",
  ui_story_5083_50830600_80_dialog_content = "Mas sendo o soldado que ele é, o Comandante Pango estava lutando na linha de frente naquela época.",
  ui_story_5083_50830600_81_dialog_content = "Ele sacrificou sua esposa para me evacuar e os outros não combatentes.",
  ui_story_5083_50830600_82_dialog_content = "O comandante nunca falou sobre isso, mas imediatamente pediu para ser transferido para longe das linhas de frente. Desde então, ele se recusou a liderar qualquer operação defensiva nas Subcidades.",
  ui_story_5083_50830600_83_dialog_content = "... Tenho certeza de que ele ainda se culpa pelo que aconteceu.",
  ui_story_5083_50830600_84_dialog_content = "É por isso que o velho... Nunca fica no acampamento por muito tempo?",
  ui_story_5083_50830600_85_dialog_content = "Nada disso foi culpa dele - eu só queria que eu pudesse fazer ele ver isso.",
  ui_story_5083_50830600_86_dialog_content = "Estou quase na mesma idade que meu irmão estava naquela época... Quero que o Comandante Pango saiba que um de seus filhos ainda está vivo.",
  ui_story_5083_50830600_87_dialog_content = "Mas não importa o quanto eu tente, os olhos dele... Estão sempre em você.",
  ui_story_5083_50830600_88_dialog_content = "Às vezes, sinto ciúmes de você, Barton. Será porque não sou forte o suficiente?",
  ui_story_5083_50830600_89_dialog_content = "No final do dia... Eu só quero tomar o lugar do meu irmão e preencher o vazio no coração do comandante.",
  ui_story_5083_50830600_90_dialog_content = "Cara... Na minha opinião, você já é mais do que suficiente. Não há razão para você se tornar outra pessoa.",
  ui_story_5083_50830600_91_dialog_content = "Por mais que você possa ser um incômodo, não há mais ninguém em todo o Astra como você! Você não precisa viver na sombra de ninguém!",
  ui_story_5083_50830600_92_dialog_content = "Tenho certeza de que o velhote concorda comigo também. Por que mais ele seria tão duro com você?",
  ui_story_5083_50830600_93_dialog_content = "E graças a você, finalmente entendo o quão indireto esse cara pode ser. Ele provavelmente nunca vai se abrir com você sobre essas coisas.",
  ui_story_5083_50830600_94_dialog_content = "Além disso, você disse que também é <color=#FFB400>criança</color> dele, certo? Não consigo pensar em alguém que queira ver um de seus filhos tentando substituir o outro.",
  ui_story_5083_50830600_95_dialog_content = "Barton... You...",
  ui_story_5083_50830600_96_dialog_content = "Heh—Hahahaha! Cara, eu não fazia ideia que você tinha algo além de músculos no seu cérebro!",
  ui_story_5083_50830600_97_dialog_content = "Essas palavras realmente não combinam com você, Barton. Depois do escândalo que você causou ontem, você é a última pessoa que deveria estar me dando conselhos, hahaha!",
  ui_story_5083_50830600_98_dialog_content = "Eu não estou brincando, Dogg.",
  ui_story_5083_50830600_99_dialog_content = "Eu sei. Obrigado, Barton; você me deu muito para pensar.",
  ui_story_5083_50830600_100_dialog_content = "Não mencione isso. Apenas tente ser um pouco mais direto de agora em diante... Dogg.",
  ui_story_5083_50830700_1_dialog_content = "<color=#e8d9bb>Não muito tempo depois, a Divisão de Comandos da 2ª Legião foi oficialmente estabelecida, e Dogg foi escolhido como seu comandante após sua promoção a Major. Barton, por outro lado, foi promovido a Capitão e feito vice-comandante do Batalhão de Infantaria Mecanizada.</color>",
  ui_story_5083_50830700_2_dialog_content = "<color=#e8d9bb>Mas as preocupações de Dogg se mostraram corretas, e logo, a severidade da Crise Darkover atingiu terríveis novos patamares.</color>",
  ui_story_5083_50830700_3_dialog_content = "<color=#e8d9bb>Os Eclipsitas romperam a linha defensiva de Illumina e começaram a cercar as Subcidades 13 e 19, as principais instalações defensivas da Federação.</color>",
  ui_story_5083_50830700_4_dialog_content = "<color=#e8d9bb>As comunicações foram desativadas logo no início da luta. Quando um mensageiro conseguiu sair e chegar à cidade de Gannon, as duas Subcidades já estavam sob cerco há vários dias.</color>",
  ui_story_5083_50830700_5_dialog_content = "<color=#e8d9bb>Uma emergência entre os líderes da cidade de Gannon foi convocada, mas mesmo após horas de deliberação, uma decisão não pôde ser tomada—</color>",
  ui_story_5083_50830700_6_dialog_content = "Não podemos esperar mais! Com cada minuto que perdemos falando aqui, quem sabe quantas vidas estão sendo perdidas?!",
  ui_story_5083_50830700_7_dialog_content = "A 2ª Legião está pronta para ser atribuída, Grande Marechal. Basta dar a ordem e estaremos a caminho.",
  ui_story_5083_50830700_8_dialog_content = "De acordo com o mensageiro, a Subcidade 13 estava apenas equipada para sobreviver mais um dia de cerco. Neste ponto, não há esperança para eles.",
  ui_story_5083_50830700_9_dialog_content = "E enquanto a situação da Subcidade 19 parecia menos grave, é altamente possível que nossas forças só encontrem uma cidade morta cheia de Eclipsitas quando chegarem.",
  ui_story_5083_50830700_10_dialog_content = "O comandante de defesa da Subcidade 13 é um velho amigo seu de tempos de guerra, Pango. Você deveria saber melhor do que ninguém—",
  ui_story_5083_50830700_11_dialog_content = "Soldados honrados como ele e seus subordinados prefeririam explodir toda a Subcidade a deixá-la cair nas mãos do inimigo!",
  ui_story_5083_50830700_12_dialog_content = "Dessa forma, eles poderiam impedir que os Eclipsitas aproveitassem nossos recursos e manter a cidade de Gannon segura!",
  ui_story_5083_50830700_13_dialog_content = "Você está absolutamente certo! Eu conheço esses tolos teimosos melhor do que a maioria, e é exatamente isso que eles fariam—",
  ui_story_5083_50830700_14_dialog_content = "Mas eu também sei o quão poderosos e tenazes eles são!",
  ui_story_5083_50830700_15_dialog_content = "Ainda há muitos civis e recursos presos nessas cidades, e esses soldados estão dispostos a arriscar suas vidas por eles!",
  ui_story_5083_50830700_16_dialog_content = "Eles não deixarão suas cidades morrerem até o amargo fim! É por isso que sei que estão esperando que nós os salvemos!",
  ui_story_5083_50830700_17_dialog_content = "Metade da minha legião ainda está lutando na Zona Cega, e você acabou de reabastecer sua legião com novos recrutas.",
  ui_story_5083_50830700_18_dialog_content = "E com a 1ª Legião ocupada demais fortalecendo nossas defesas... Quem nos resta para enviar?",
  ui_story_5083_50830700_19_dialog_content = "Mesmo com todas as nossas forças presentes, defender Gannon City dos Eclipsitas não seria fácil. Você realmente acha que podemos nos dar ao luxo de poupar algum soldado?",
  ui_story_5083_50830700_20_dialog_content = "E considerando o quão distantes essas duas Subcidades estão de nós, não seríamos capazes de usar trens para enviar reforços. Teríamos que enviá-los a pé.",
  ui_story_5083_50830700_21_dialog_content = "Com as comunicações interrompidas, não sabemos o que nos espera lá fora. E se nossas tropas forem emboscadas ao longo do caminho? Elas estariam em sério perigo!",
  ui_story_5083_50830700_22_dialog_content = "Você não acha que essas duas Subcidades estão em sério perigo agora?!?",
  ui_story_5083_50830700_23_dialog_content = "Como você pode ser tão insensível, Motor?!",
  ui_story_5083_50830700_24_dialog_content = "Retire o que disse, Pango! Você faz ideia de quantos soldados eu perdi para a Zona Cega?! Você não é o único que precisa se preocupar com a vida das pessoas!",
  ui_story_5083_50830700_25_dialog_content = "Estou cansado de ouvir essa bobagem...",
  ui_story_5083_50830700_26_dialog_content = "Barton!",
  ui_story_5083_50830700_27_dialog_content = "Essas pessoas nos tratam como seus escudos, e ainda assim nos jogam ao chão assim que as coisas ficam difíceis.",
  ui_story_5083_50830700_28_dialog_content = "Você não tem liberdade para falar o que pensa aqui, soldado.",
  ui_story_5083_50830700_29_dialog_content = "Ah, me desculpe, vou me retirar então—Além disso, ficar perto de vocês me deixa doente.",
  ui_story_5083_50830700_30_dialog_content = "Quem você pensa que é, falando assim?!",
  ui_story_5083_50830700_31_dialog_content = "Desculpe por isso, senhor. Tenho certeza que a boca dele não está totalmente conectada ao cérebro dele.",
  ui_story_5083_50830700_32_dialog_content = "O que você pensa que está fazendo, Dogg?! Não fale assim sobre o seu companheiro soldado!",
  ui_story_5083_50830700_33_dialog_content = "Vocês homens já terminaram?",
  ui_story_5083_50830700_34_dialog_content = "Tenho certeza que suas brigas são muito importantes, mas a 1ª Legião ainda está lutando por suas vidas lá fora.",
  ui_story_5083_50830700_35_dialog_content = "Diga-me, jovens oficiais: vocês apoiam a decisão do seu comandante?",
  ui_story_5083_50830700_36_dialog_content = "Claro, Grande Marechal.",
  ui_story_5083_50830700_37_dialog_content = "... Na verdade, acredito que o comandante da 3ª Legião tem um ponto.",
  ui_story_5083_50830700_38_dialog_content = "O quê? Você perdeu a cabeça, Dogg?!",
  ui_story_5083_50830700_39_dialog_content = "Eu te disse, ainda consigo ouvir as vozes dos meus camaradas caídos na minha cabeça... Não podemos nos dar ao luxo de sermos descuidados, ou então seus sacrifícios terão sido em vão.",
  ui_story_5083_50830700_40_dialog_content = "... Você está dispensado por agora.",
  ui_story_5083_50830700_41_dialog_content = "Entendido, Comandante Pango! Eu apenas peço que você e o Capitão Barton avaliem cuidadosamente os riscos antes de tomar qualquer decisão.",
  ui_story_5083_50830700_42_dialog_content = "As crianças de Illumina crescem sob o esplendor da Torre Central! Elas conhecem muito bem a justiça da nossa causa!",
  ui_story_5083_50830700_43_dialog_content = "Antes de nossos soldados serem enviados para as diferentes Subcidades, eles são bem informados sobre essa possibilidade com antecedência.",
  ui_story_5083_50830700_44_dialog_content = "O tempo para discussão acabou, Pango. Precisamos trabalhar juntos para defender Gannon City.",
  ui_story_5083_50830700_45_dialog_content = "Se eles estão dispostos a dar suas vidas pela Illumina, então cabe a nós garantir que seus sacrifícios não sejam em vão.",
  ui_story_5083_50830700_46_dialog_content = "Se você não for, então meus soldados e eu iremos!",
  ui_story_5083_50830700_47_dialog_content = "Não, Pango.",
  ui_story_5083_50830700_48_dialog_content = "Motor está certo: temos quase nenhum conhecimento da situação lá fora, e não podemos nos dar ao luxo de mais perdas. Em qualquer caso, a 1ª Legião não vai disponibilizar nenhum soldado para isso.",
  ui_story_5083_50830700_49_dialog_content = "Supostamente deveríamos estar ajudando uns aos outros através deste calvário. Agora não é hora para brigas internas.",
  ui_story_5083_50830700_50_dialog_content = "Se os nossos soldados virem isso, o moral deles vai despencar.",
  ui_story_5083_50830700_51_dialog_content = "Grr... Estamos saindo, Barton!",
  ui_story_5083_50830700_52_dialog_content = "Mantenha sua posição e não tome nenhuma ação não autorizada, Comandante! Essa é uma ordem!",
  ui_story_5083_50830700_53_dialog_content = "Ei, vocês dois. Acho que as coisas não foram muito bem lá dentro, certo?",
  ui_story_5083_50830700_54_dialog_content = "Com aquele covarde no comando da 1ª Legião? Claro que não!",
  ui_story_5083_50830700_55_dialog_content = "Não saia ainda! Estou aqui para entregar novas <color=#FFB400>ordens</color>.",
  ui_story_5083_50830700_56_dialog_content = "\"Com efeito imediato, a 2ª Legião deve ser enviada para as Subcidades 13 e 19 para fornecer reforços, com o Tenente Reinhardt e uma parte da 1ª Legião também prestando apoio...\"",
  ui_story_5083_50830700_57_dialog_content = "É mais ou menos essa a essência. Como soa?",
  ui_story_5083_50830700_58_dialog_content = "Você está seriamente pensando em falsificar ordens militares?",
  ui_story_5083_50830700_59_dialog_content = "Se você não está disposto a ajudar, então nós vamos lidar com isso por conta própria.",
  ui_story_5083_50830700_60_dialog_content = "Posso despachar alguns esquadrões da 1ª Legião; o resto deles é mais do que capaz de defender Gannon City junto com a 3ª Legião.",
  ui_story_5083_50830700_61_dialog_content = "Podemos não ter muito impacto aqui, mas nossa presença nessas Cidades Baixas pode significar a diferença entre a vida e a morte.",
  ui_story_5083_50830700_62_dialog_content = "Infelizmente, não tenho soldados suficientes para esta missão. É por isso que eu queria pedir ajuda à 2ª Legião.",
  ui_story_5083_50830700_63_dialog_content = "Você sabe o que acontecerá com você se concordarmos com isso, não sabe?",
  ui_story_5083_50830700_64_dialog_content = "Agradeço sua preocupação, Comandante... Mas salvar vidas ainda é mais importante para mim.",
  ui_story_5083_50830700_65_dialog_content = "... Você é apenas uma tenente insignificante. O que lhe deu a confiança para nos abordar com uma façanha dessas?",
  ui_story_5083_50830700_66_dialog_content = "Minha crença é que nenhum de vocês jamais abandonaria seus companheiros.",
  ui_story_5083_50830700_67_dialog_content = "Ainda está indeciso, Comandante Pango? Porque de qualquer forma, eu vou com ela.",
  ui_story_5083_50830700_68_dialog_content = "Primeiro você desobedeceu ordens, e agora está falsificando-as? Você tem uma audácia séria, Reinhardt.",
  ui_story_5083_50830700_69_dialog_content = "É só isso que você tem a dizer depois de me seguir todo esse caminho?",
  ui_story_5083_50830700_70_dialog_content = "Ha! Acha que vou ficar parado e deixar você fazer o que quiser?",
  ui_story_5083_50830700_71_dialog_content = "Interessante... Parece que não somos os únicos insatisfeitos com os superiores, certo? Bom! Já era hora de nós darmos as ordens por aqui!",
  ui_story_5083_50830700_72_dialog_content = "Hmph. A Subcidade 13 é a mais perigosa, então deixe essa para mim.",
  ui_story_5083_50830700_73_dialog_content = "Seja meu convidado, Wrath. Quantos soldados você precisa?",
  ui_story_5083_50830700_74_dialog_content = "Como as tropas estão em falta por aqui, vou levar apenas um pelotão.",
  ui_story_5083_50830700_75_dialog_content = "Como espera realizar isso com apenas um pelotão? Esqueça, eu vou junto, e estou levando mais soldados comigo!",
  ui_story_5083_50830700_76_dialog_content = "Espere!",
  ui_story_5083_50830700_77_dialog_content = "Por mais irritante que Motor possa ser, seu Departamento de Inteligência quase nunca erra.",
  ui_story_5083_50830700_78_dialog_content = "A situação da Subcidade 13 está longe de ser otimista... De uma perspectiva puramente temporal, é verdade que a cidade está além da salvação.",
  ui_story_5083_50830700_79_dialog_content = "Se enviarmos muitas de nossas forças, há uma boa chance de ficarem presas em batalha sem saída.",
  ui_story_5083_50830700_80_dialog_content = "Entendido... Então será apenas você e uma pequena equipe, Wrath.",
  ui_story_5083_50830700_81_dialog_content = "Não perca a cabeça na batalha. Priorize a evacuação e o resgate acima de qualquer coisa, entendeu?",
  ui_story_5083_50830700_82_dialog_content = "Como se eu precisasse que você me desse ordens—Apenas espere, Reinhardt. Eu vou trazer todos de volta!",
  ui_story_5083_50830700_83_dialog_content = "Espere, eu vou com você! Como vice-comandante, tenho muitos soldados que me seguirão na batalha.",
  ui_story_5083_50830700_84_dialog_content = "Deixe ela lidar com isso, Barton. Eu já vi a força dela por mim mesmo, e ela é a melhor pessoa para esse tipo de luta.",
  ui_story_5083_50830700_85_dialog_content = "A Subcidade 19 é muito maior, o que significa que eles têm uma melhor chance de sobreviver por mais tempo.",
  ui_story_5083_50830700_86_dialog_content = "Mas se a Subcidade 13 já caiu, é quase certo que o inimigo concentrará seus ataques na Subcidade 19 a seguir.",
  ui_story_5083_50830700_87_dialog_content = "Barton! Você pode ser um idiota, mas eu te transformei em uma das armas mais poderosas de Illumina.",
  ui_story_5083_50830700_88_dialog_content = "Uma batalha em grande escala como essa combina perfeitamente com você e nossa Divisão de Infantaria Mecanizada.",
  ui_story_5083_50830700_89_dialog_content = "Infelizmente, os guardas responsáveis pelo depósito de equipamentos só aceitam ordens do comando mais alto, o que significa que ordens falsificadas são completamente inúteis. Você terá que aproveitar a troca de turno deles e fazer com que seus soldados roubem o máximo que puderem.",
  ui_story_5083_50830700_90_dialog_content = "Espere, você está dizendo que quer que a gente vá primeiro e garanta a segurança da Subcidade 19 como fizemos da última vez?",
  ui_story_5083_50830700_91_dialog_content = "Apenas ouça o plano do Comandante Pango, Barton. Liderar toda a 2ª Legião para fora da Cidade de Gannon não é algo que podemos fazer sozinhos.",
  ui_story_5083_50830700_92_dialog_content = "Agora rápido, antes que eles tenham a chance de notar! Economize algum tempo usando o elevador principal para subir!",
  ui_story_5083_50830700_93_dialog_content = "... Apenas não deixe que o Comitê te pegue antes de vir ao nosso resgate, velhote.",
  ui_story_5083_50830700_94_dialog_content = "Espere! Todos vocês estão falando sério sobre fazer isso?",
  ui_story_5083_50830700_95_dialog_content = "Comandante, você e Barton serão marcados como traidores se saírem assim—Você realmente está disposto a fazer isso com a Illumina? Com as pessoas que você se importa?!",
  ui_story_5083_50830700_96_dialog_content = "Insubordinação, falsificação de ordens e traição descarada... O Grande Marechal não vai ignorar esses crimes tão facilmente.",
  ui_story_5083_50830700_97_dialog_content = "...",
  ui_story_5083_50830700_98_dialog_content = "Eu não me importo com nada disso, Dogg. Só tenho uma pergunta para você: Você vem ou não?",
  ui_story_5083_50830700_99_dialog_content = "Depois de tudo que você me contou no museu, você está realmente me dizendo que não quer salvá-los?",
  ui_story_5083_50830700_100_dialog_content = "Claro que eu quero salvá-los! Mas...",
  ui_story_5083_50830700_101_dialog_content = "Talvez ainda possamos convencer o Grande Marechal a nos ajudar? Se eu apenas contar tudo a ele...",
  ui_story_5083_50830700_102_dialog_content = "Pare bem aí, Dogg! Quem é você para discutir com a Grande Marechal.",
  ui_story_5083_50830700_103_dialog_content = "Mas sem a aprovação dele, não podemos agir sobre isso...",
  ui_story_5083_50830700_104_dialog_content = "Permita-me repetir a pergunta de Barton: Você vem ou não?",
  ui_story_5083_50830700_105_dialog_content = "Estaríamos desobedecendo ordens sem o seu consentimento... Eu me recuso a cometer um crime tão hediondo contra a Illumina... E me deixar à mercê do Comitê...",
  ui_story_5083_50830700_106_dialog_content = "Os verdadeiros traidores aqui são o Grande Marechal e os outros! Como eles poderiam simplesmente fechar os olhos enquanto nossos aliados—",
  ui_story_5083_50830700_107_dialog_content = "Chega, Tenente Reinhardt! Sou perfeitamente capaz de educar meus próprios subordinados, muito obrigado!",
  ui_story_5083_50830700_108_dialog_content = "Cãozinho... Eu entendo seu dilema, então apenas volte para o acampamento.",
  ui_story_5083_50830700_109_dialog_content = "Uma bala mal direcionada não tem poder de parada, então não há necessidade de você vir junto. Se ainda se sente culpado por isso, sinta-se à vontade para nos denunciar.",
  ui_story_5083_50830700_110_dialog_content = "N-Não, Comandante Pango... Você tem que ser o único a me dar a ordem! Eu irei a qualquer lugar, desde que você me diga para—",
  ui_story_5083_50830700_111_dialog_content = "Eu não vou te forçar!",
  ui_story_5083_50830700_112_dialog_content = "Você não precisa ter tanto medo, Dogg; você não fez nada de errado. Mas as coisas nem sempre são tão preto e branco quanto as leis de Illumina.",
  ui_story_5083_50830700_113_dialog_content = "Barton. Tenente Reinhardt. É hora de se mover.",
  ui_story_5083_50830700_114_dialog_content = "Venha conosco se é isso que você quer, mas se não puder fazer essa escolha, apenas fique aqui e cubra nossa rota de retorno.",
  ui_story_5083_50830700_115_dialog_content = "De qualquer maneira, estaremos contando com você.",
  ui_story_5083_50830700_116_dialog_content = "Barton, seu idiota... Tente não morrer antes de darem a ordem...",
  ui_story_5083_50830700_117_dialog_content = "<color=#e8d9bb>Reinhardt e Barton aproveitam a troca de guarda e lideram seu grupo até o depósito de equipamentos, pegando o máximo que podem antes que alguém perceba.</color>",
  ui_story_5083_50830700_118_dialog_content = "<color=#e8d9bb>Quando os guardas finalmente descobrem as ações dos rebeldes, Barton é forçado a cobrir a retaguarda e escoltar o último carro blindado através de uma tempestade de tiros.</color>",
  ui_story_5083_50830700_119_dialog_content = "Rápido! Nós interrompemos as comunicações deles. Agora carregue tudo no elevador principal antes que eles cortem a energia!",
  ui_story_5083_50830700_120_dialog_content = "Ufa—Essa foi por pouco. Eles definitivamente estavam atirando para matar agora mesmo...",
  ui_story_5083_50830700_121_dialog_content = "*Bipando* Bem, você cometeu o ato mais alto de traição, Barton...",
  ui_story_5083_50830700_122_dialog_content = "Eh? Quando você chegou aqui?",
  ui_story_5083_50830700_123_dialog_content = "Desculpe, pequeno, mas você acabou de embarcar em um navio cheio de piratas. Ainda há tempo para descer antes que o elevador suba mais, sabe?",
  ui_story_5083_50830700_124_dialog_content = "Bip—Barton...",
  ui_story_5083_50830700_125_dialog_content = "Seu Navegador nunca te abandonaria—",
  ui_story_5083_50830801_1_dialog_content = "<color=#e8d9bb>Na noite sem lua, um mar de Eclipsitas converge ameaçadoramente na entrada da Subcidade 19.</color>",
  ui_story_5083_50830801_2_dialog_content = "<color=#e8d9bb>Após dias de cerco, todos os canhões de curto alcance da cidade estão sem munição ou completamente destruídos. As pessoas dentro não podem fazer nada além de esperar pelo fim em silêncio impotente.</color>",
  ui_story_5083_50830801_3_dialog_content = "<color=#e8d9bb>Na única entrada para a Subcidade, os soldados de Illumina lutam com unhas e dentes para manter os Eclipsitas à distância. Sem munição, eles recorrem às suas lâminas; sem lâminas, eles recorrem aos seus punhos.</color>",
  ui_story_5083_50830801_4_dialog_content = "<color=#e8d9bb>Mantendo firme a crença de que são os escudos da Federação, eles lutam sem outro pensamento em suas mentes, exceto pelo mais tênue vislumbre de esperança.</color>",
  ui_story_5083_50830801_5_dialog_content = "<color=#e8d9bb>\"O mensageiro conseguiu sair. A cidade de Gannon enviará reforços em breve.\"</color>",
  ui_story_5083_50830801_6_dialog_content = "<color=#e8d9bb>Depois de dez dias, aquele brilho tênue começou a vacilar. Mas, justo antes que pudesse ser extinto, os soldados resolutos veem a resposta às suas orações além de um mar de sangue e ossos—</color>",
  ui_story_5083_50830801_7_dialog_content = "<size=45>Mande-os voar!</size>",
  ui_story_5083_50830801_8_dialog_content = "Lá está a nossa brecha! Envie nossos lutadores para fortificar aquela posição!",
  ui_story_5083_50830801_9_dialog_content = "Reabasteça a munição de todos antes de inspecionar as defesas da cidade! Use quaisquer canhões de curto alcance que ainda estejam operacionais e reutilize o resto em canhões de uso único!",
  ui_story_5083_50830801_10_dialog_content = "Reinhardt! Vá verificar o status da cidade enquanto nós seguramos a entrada!",
  ui_story_5083_50830801_11_dialog_content = "Colônia! Traga aquele carro de transporte blindado aqui!",
  ui_story_5083_50830801_12_dialog_content = "Estou com os reforços enviados de Gannon City! Quem está no comando desta cidade agora?",
  ui_story_5083_50830801_13_dialog_content = "Nosso oficial comandante morreu em batalha - Você pode transmitir qualquer informação para mim!",
  ui_story_5083_50830801_14_dialog_content = "A Divisão de Infantaria Mecanizada estabilizará a situação na superfície. Pegue o resto de seus soldados e comece a fortificar suas defesas!",
  ui_story_5083_50830801_15_dialog_content = "Quanto aos civis ainda presos aqui, carregue quaisquer recursos valiosos em nosso veículo blindado e use-o para evacuar imediatamente—",
  ui_story_5083_50830801_16_dialog_content = "Mas e você e suas tropas?",
  ui_story_5083_50830801_17_dialog_content = "Vamos ficar e defender este lugar até que a paz seja restaurada!",
  ui_story_5083_50830801_18_dialog_content = "Somos apenas a equipe avançada, mas não se preocupe; o resto de nossas forças estará aqui em breve.",
  ui_story_5083_50830801_19_dialog_content = "Fiquem juntos e não desistam! Vamos proteger esta cidade!",
  ui_story_5083_50830801_20_dialog_content = "<color=#e8d9bb>Enquanto a onda de escuridão continua seu ataque implacável, Barton lidera seu batalhão de uma dúzia de tanques diretamente para as forças inimigas, determinado imprudentemente a mudar os rumos da batalha.</color>",
  ui_story_5083_50830801_21_dialog_content = "<color=#e8d9bb>Mas diante de números tão avassaladores, a força deles está longe de ser suficiente—</color>",
  ui_story_5083_50830801_22_dialog_content = "Droga, as esteiras do nosso tanque foram atingidas e há um gigantesco Eclipsita se aproximando de nós! Desculpe, Vice-comandante Barton—Foi uma honra lutar ao seu lado, senhor!",
  ui_story_5083_50830801_23_dialog_content = "Não espera, já tô indo aí—",
  ui_story_5083_50830801_24_dialog_content = "Splendor Illumina!",
  ui_story_5083_50830801_25_dialog_content = "<color=#e8d9bb>O tanque imobilizado acende o resto de sua munição, resultando em uma explosão ardente que engolfa todos os Eclipsitas nas proximidades.</color>",
  ui_story_5083_50830801_26_dialog_content = "<size=45>Coma chumbo, seus monstros imundos!!!</size>",
  ui_story_5083_50830801_27_dialog_content = "Coloque essas armas de curto alcance para funcionar e não economize nos tiros! Elimine o máximo que puder!",
  ui_story_5083_50830801_28_dialog_content = "Precisamos empurrá-los de volta antes que eles possam fazer o mesmo conosco!",
  ui_story_5083_50830801_29_dialog_content = "<size=45>Sim, senhor!!!</size>",
  ui_story_5083_50830801_30_dialog_content = "Relatório! Os sistemas de defesa da Subcidade 13 foram completamente desativados. Dada a situação atual, estimamos que os Eclipsitas irão invadir o abrigo em aproximadamente vinte minutos.",
  ui_story_5083_50830801_31_dialog_content = "As comunicações ainda estão fora do ar, e nossa equipe de guerrilha não conseguiu chegar aos andares superiores para reparar as linhas. O <color=#FFB400>enorme Eclipsita</color> que nos atacou antes se foi, mas a cidade está infestada de Eclipsitas menores.",
  ui_story_5083_50830801_32_dialog_content = "Com nossa estação de energia completamente destruída, a única coisa ainda operacional é o sistema de autodestruição oculto da cidade...",
  ui_story_5083_50830801_33_dialog_content = "Como soldados, estamos preparados para cair com a cidade, mas ainda há tantos civis e recursos dentro do abrigo...",
  ui_story_5083_50830801_34_dialog_content = "<color=#e8d9bb>O coronel olha em silêncio para as partes mais altas da Cidade Baixa. A escuridão acima é pontuada apenas pelas chamas cintilantes da destruição.</color>",
  ui_story_5083_50830801_35_dialog_content = "Os garotos que estão realizando nossas operações de guerrilha não têm mais de dezessete anos... Eles não merecem morrer aqui embaixo com o resto de nós, velhos cães.",
  ui_story_5083_50830801_36_dialog_content = "Este lugar logo será um ninho de Eclipsites... A cidade de Gannon não virá nos salvar, mas isso não significa que podemos criar mais problemas para eles. Tenho certeza que você entende, senhor.",
  ui_story_5083_50830801_37_dialog_content = "... Vamos esperar mais dezoito minutos. Se eles realmente conseguirem invadir o abrigo, detonaremos a cidade inteira. Pelo menos, nosso povo não morrerá nas mãos dos Eclipsitas.",
  ui_story_5083_50830801_38_dialog_content = "As pessoas lá dentro devem estar aterrorizadas com os sons vindos do outro lado daquela porta... Você realmente está disposto a fazê-las passar por mais dezoito minutos desse sofrimento?",
  ui_story_5083_50830801_39_dialog_content = "Não, estou dando a eles mais dezoito minutos de esperança! Tenho certeza que alguns deles... Ainda pensam que seremos nós a abrir aquela porta.",
  ui_story_5083_50830801_40_dialog_content = "Que cruel... Me desculpe, senhor, mas eu simplesmente não posso aceitar isso. Como defensores de primeira linha da Cidade Gannon, estamos destinados a nos sacrificar pelo bem de todos os Illumina—",
  ui_story_5083_50830801_41_dialog_content = "Eu não quero que ninguém venha e nos salve se isso significar se colocar em perigo... Mas... É tão errado acreditar...",
  ui_story_5083_50830801_42_dialog_content = "Que a luz da esperança possa permanecer acesa em nossa cidade?",
  ui_story_5083_50830801_43_dialog_content = "Alguém está ouvindo? Repito, alguém está ouvindo?",
  ui_story_5083_50830801_44_dialog_content = "Meu nome é 2º Tenente Wrath, e estou aqui com uma equipe de reforços da Cidade de Gannon. Conseguimos infiltrar nos níveis superiores da Subcidade 13 e restaurar as comunicações. Há algum sobrevivente lá embaixo?",
  ui_story_5083_50830801_45_dialog_content = "...!",
  ui_story_5083_50830801_46_dialog_content = "Não, não responda a ela! A cidade está infestada de Eclipsitas; eles nunca conseguirão sair se descerem aqui!",
  ui_story_5083_50830801_47_dialog_content = "Eu sei melhor do que ninguém que esta cidade está além de ser salva! Em pouco tempo, a Torre Central iria desabar, começando pela estação de energia; nenhum de nós tinha alguma esperança de escapar!",
  ui_story_5083_50830801_48_dialog_content = "Não deixe eles descerem aqui! Ative a sequência de autodestruição antes que este lugar caia na escuridão! É a única maneira de termos alguma esperança de reconstrução—",
  ui_story_5083_50830801_49_dialog_content = "Posso ouvir tiros; você ainda está lutando lá embaixo, o que significa que deve haver sobreviventes em algum lugar. Eles estão no abrigo? Por que você não está respondendo?",
  ui_story_5083_50830801_50_dialog_content = "Será que... Você está preocupado conosco indo lá embaixo?",
  ui_story_5083_50830801_51_dialog_content = "Ainda sem resposta, hein? Bando de velhos teimosos... Parece que teremos que dar a eles um sinal.",
  ui_story_5083_50830801_52_dialog_content = "Reinhardt me pediu para vir junto para impedir que você faça algo imprudente - Você percebe que um movimento em falso trará uma cidade inteira de Eclipsitas sobre nossas cabeças, certo?",
  ui_story_5083_50830801_53_dialog_content = "Se a justiça permanecer em silêncio, a escuridão nunca poderá ser expulsa.",
  ui_story_5083_50830801_54_dialog_content = "Você não consegue sentir o desespero deles? Isso é exatamente o que Reinhardt faria se estivesse aqui!",
  ui_story_5083_50830801_55_dialog_content = "<color=#e8d9bb>Subcidade 13 está condenada—Ninguém duvida que esta é uma missão sem esperança.</color>",
  ui_story_5083_50830801_56_dialog_content = "<color=#e8d9bb>Mas na escuridão e desespero, um farol de repente aparece: um raio da cidade de Gannon que rasga todos os medos e dúvidas.</color>",
  ui_story_5083_50830801_57_dialog_content = "<color=#e8d9bb>Wrath esfrega suas luvas vigorosamente para produzir uma poderosa explosão de luz e som, atraindo a atenção de todos os Eclipsitas para ela.</color>",
  ui_story_5083_50830801_58_dialog_content = "Quem diz que esta cidade está além da salvação?! Somos o último raio de esperança deles! Sua salvação final!",
  ui_story_5083_50830801_59_dialog_content = "Agora escute bem! Minha equipe e eu estamos indo direto para o andar de baixo, e vamos eliminar tudo em nosso caminho! Prepare todos os civis para evacuar antes disso!",
  ui_story_5083_50830801_60_dialog_content = "... Quem diabos é você? Por que iria tão longe por nós? Não há como a Grande Marechal ter aprovado isso!",
  ui_story_5083_50830801_61_dialog_content = "Já te disse, meu nome é Wrath—O futuro Grande Marechal de Illumina! Não vou deixar ninguém me impedir de exercer minha marca de justiça!",
  ui_story_5083_50830801_62_dialog_content = "<color=#e8d9bb>Wrath lidera o ataque contra os Eclipsitas que avançam pela escadaria, sua lâmina dançante cortando um caminho sangrento através de suas fileiras. Eventualmente, ela chega ao andar térreo da Subcidade.</color>",
  ui_story_5083_50830801_63_dialog_content = "Vocês todos viram isso? Aquele soldado é o futuro da Illumina... O fruto da nossa dedicação e treinamento...",
  ui_story_5083_50830801_64_dialog_content = "Ela é o \"Phospherus\" que todos nós sonhamos... Sua luz... É absolutamente deslumbrante...",
  ui_story_5083_50830801_65_dialog_content = "Nosso sonho agora brilha diante de nós... Como podemos nos dar ao luxo de deixá-lo apagar?",
  ui_story_5083_50830801_66_dialog_content = "... Vou garantir que a rota de evacuação do abrigo esteja desobstruída nos próximos dez minutos, mesmo que custe minha vida.",
  ui_story_5083_50830801_67_dialog_content = "E eu liderarei uma equipe para encontrar com ela. O resto fica por sua conta.",
  ui_story_5083_50830801_68_dialog_content = "<color=#FFB400>A luz de Phospherus</color>... Não importa o que aconteça, eu tenho que deixar todos verem isso—",
  ui_story_5083_50830801_69_dialog_content = "<color=#e8d9bb>Nos arredores da Cidade Baixa, as chamas da guerra arderam por três dias seguidos sem sinal de reforços à vista.</color>",
  ui_story_5083_50830801_70_dialog_content = "<color=#e8d9bb>Com os suprimentos de munição esgotados novamente, os soldados recorreram ao combate corpo a corpo mais uma vez.</color>",
  ui_story_5083_50830801_71_dialog_content = "Segure a linha! Temos que manter essa posição, senão eles vão bloquear a entrada!",
  ui_story_5083_50830801_72_dialog_content = "Rugido-!",
  ui_story_5083_50830801_73_dialog_content = "Não no meu turno!",
  ui_story_5083_50830801_74_dialog_content = "Heh, o velhote... Quer dizer, Comandante Pango estava certo! Ser capaz de trocar instintivamente para uma arma de combate corpo a corpo contra vários Eclipsitas é o melhor caminho a seguir.",
  ui_story_5083_50830801_75_dialog_content = "Você está tendo um momento de realização aí, Barton?",
  ui_story_5083_50830801_76_dialog_content = "Na verdade não; o antigo comandante me ensinou um certo reflexo, e estou apenas vendo isso em ação pela primeira vez. Heh, estou começando a me sentir em casa nesses tipos de batalhas.",
  ui_story_5083_50830801_77_dialog_content = "Não conseguiremos manter essa posição por muito mais tempo. Sugiro que você forme uma equipe e tente abrir uma rota de fuga através do inimigo. É a nossa melhor chance de levar essas pessoas de volta para Gannon City.",
  ui_story_5083_50830801_78_dialog_content = "E você? Não me diga que vai ficar aqui?",
  ui_story_5083_50830801_79_dialog_content = "Eu disse a eles que lutaria com eles até o fim... Se não conseguirmos defender a Subcidade, a explodiremos e garantiremos que os Eclipsitas não possam usá-la de forma alguma.",
  ui_story_5083_50830801_80_dialog_content = "Isso não vai acontecer, Reinhardt! O Comandante Pango deu sua palavra de que viria, e ele nunca volta atrás em sua palavra!",
  ui_story_5083_50830801_81_dialog_content = "... Não temos como nos comunicar com ninguém fora da cidade, e nenhum dos nossos mensageiros retornou. Você realmente confia tanto nele, Barton?",
  ui_story_5083_50830801_82_dialog_content = "Ele pode ser um idiota, mas o velhote nunca mentiu para mim antes... Então, claro que sim! Eu confio nele assim como confio em você para cobrir minhas costas!",
  ui_story_5083_50830801_83_dialog_content = "Então eu também não tenho motivo para duvidar dele!",
  ui_story_5083_50830801_84_dialog_content = "Hmph. Pelo bem de Illumina e todos os nossos camaradas caídos... Eu me recuso a me render a esses Eclipsitas ou fugir em desgraça.",
  ui_story_5083_50830801_85_dialog_content = "Então ficaremos costas com costas e lutaremos até o momento em que toda esperança estiver perdida!",
  ui_story_5083_50830801_86_dialog_content = "Um grande Eclipsita está se aproximando, Reinhardt! Eu-Eu acho que pode ser o líder deles!",
  ui_story_5083_50830801_87_dialog_content = "Soldados insignificantes da Illumina - Ajoelhem-se diante de mim, o imparável Duskcaller!",
  ui_story_5083_50830801_88_dialog_content = "Um Eclipsite capaz de falar? Você não vê isso todos os dias... Desculpe, amigo, mas minhas pernas realmente não se ajoelham. Se isso for um problema, você pode resolver com minha lâmina.",
  ui_story_5083_50830801_89_dialog_content = "Não somos do tipo que se rende, então apenas poupe-nos. Deixarei minha Lança Perfurante de Estrelas mostrar-lhe a verdadeira luz de Illumina!",
  ui_story_5083_50830801_90_dialog_content = "Vi a Mãe caçando as estrelas do céu noturno, atraída por sua vontade irresistível.",
  ui_story_5083_50830801_91_dialog_content = "Vocês, patéticos Aurorianos, apenas sobrevivem na escuridão do abismo, e ainda assim ousam agir com tanta impunidade.",
  ui_story_5083_50830801_92_dialog_content = "A luz logo se apagará deste lugar... E a cidade de Gannon terá um destino semelhante. A \"verdadeira luz de Illumina\" não passa de uma farsa...",
  ui_story_5083_50830801_93_dialog_content = "Ei Reinhardt, parece que temos um poeta entre nós.",
  ui_story_5083_50830801_94_dialog_content = "Não importa o quão culto você pense que é... Você nunca entenderá, monstro.",
  ui_story_5083_50830801_95_dialog_content = "Um dia, sairemos dessas trincheiras e retornaremos a uma Astra pacífica - Esse será o nosso novo começo, e nossa chance de seguir a luz novamente.",
  ui_story_5083_50830801_96_dialog_content = "Illumina é o amanhecer que perfura a noite e anuncia a luz do dia! Nossa fé nos une, e pela nossa fé você será parado!",
  ui_story_5083_50830801_97_dialog_content = "Somos todos brasas... As faíscas do esplendor de Illumina! Você nunca poderia esperar extinguir nossa luz!",
  ui_story_5083_50830801_98_dialog_content = "Não poderia ter dito melhor! Não importa quantos Eclipsitas você jogue em nós, você nunca quebrará nosso espírito!",
  ui_story_5083_50830801_99_dialog_content = "Farei você pagar caro por sua arrogância, fracotes—Atacar!",
  ui_story_5083_50830801_100_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5083_50830801_101_dialog_content = "<color=#e8d9bb>Um projétil de artilharia de repente atinge o Eclipsite e explode, fazendo-o cambalear.</color>",
  ui_story_5083_50830801_102_dialog_content = "<color=#e8d9bb>Um clarim soa enquanto o sistema de transmissão de emergência da Subcidade 19 começa a tocar, sinalizando a chegada tão esperada dos reforços.</color>",
  ui_story_5083_50830801_103_dialog_content = "<color=#e8d9bb>Os soldados voltam seus rostos ensanguentados para o horizonte. Banhada em luz, uma legião inteira aparece e começa a marchar contra o inimigo.</color>",
  ui_story_5083_50830801_104_dialog_content = "<color=#e8d9bb>O estandarte da 2ª Legião voa acima de suas cabeças—Um símbolo do poder da alvorada.</color>",
  ui_story_5083_50830801_105_dialog_content = "Tamanha impudência... Como ousam me atacar, Aurorians tolos! Vocês pagarão com seu sangue—",
  ui_story_5083_50830801_106_dialog_content = "Agora é a nossa chance, Reinhardt! Ataque!",
  ui_story_5083_50830802_1_dialog_content = "Fósforo... Não! Todos vocês devem morrer aqui! Astra está destinada ao sofrimento eterno... A noite eterna não será interrompida!",
  ui_story_5083_50830802_2_dialog_content = "Desculpe, mas superar o mal também é o destino de todo herói em histórias como esta.",
  ui_story_5083_50830802_3_dialog_content = "Eu falhei? Não! Isso não pode ser—",
  ui_story_5083_50830802_4_dialog_content = "Não há como escapar da sua destruição... O sino começou a tocar... A hora da sua <color=#FFB400>morte</color> está próxima...",
  ui_story_5083_50830802_5_dialog_content = "Meu irmão... Deve continuar meu glorioso trabalho... Ack! <color=#FFB400>Mãe</color>...",
  ui_story_5083_50830802_6_dialog_content = "Sobre o que ele estava falando? Parece que ainda há outro inimigo difícil nos esperando lá fora...",
  ui_story_5083_50830802_7_dialog_content = "Não tenho certeza absoluta... Mas sobrevivemos, e isso é o que importa.",
  ui_story_5083_50830802_8_dialog_content = "Terceira Divisão, comece a trabalhar na recuperação da estação de energia! Restabeleça as comunicações e envie uma mensagem de volta para a cidade de Gannon... Não, para todas as Subcidades da Federação!",
  ui_story_5083_50830802_9_dialog_content = "Diga a eles que esta cidade ainda pode ser salva e para não desistir dela!",
  ui_story_5083_50830802_10_dialog_content = "Senhor, acabamos de receber um despacho de emergência da Subcidade 13! Por favor, ouça!",
  ui_story_5083_50830802_11_dialog_content = "... Meu Oficial de Comunicação diz que a Subcidade 19 está segura agora. Foi obra sua, Pango?",
  ui_story_5083_50830802_12_dialog_content = "Desculpe, velho amigo... Eu não consegui te salvar sozinho.",
  ui_story_5083_50830802_13_dialog_content = "Heh, guarde suas desculpas. Esta foi a melhor escolha possível, não foi? Cuide bem desse lugar e certifique-se de que não o perderemos novamente.",
  ui_story_5083_50830802_14_dialog_content = "Esse incrível jovem oficial... Wrath, se não me engano? Ela está liderando todos para fora do abrigo neste exato momento.",
  ui_story_5083_50830802_15_dialog_content = "O quê?! Comandante Pango, deixe-me levar uma equipe até lá para ajudá-la!",
  ui_story_5083_50830802_16_dialog_content = "Ele está certo! Acho que ainda há esperança para salvar a Subcidade 13—",
  ui_story_5083_50830802_17_dialog_content = "Calem a boca, vocês dois! Deixe o cara terminar de falar!",
  ui_story_5083_50830802_18_dialog_content = "Estamos lutando sem descanso pelos últimos quinze dias... Além de mim, o resto dos nossos oficiais já caíram.",
  ui_story_5083_50830802_19_dialog_content = "Mas ouvir que a Subcidade 19 está segura me deixa em paz.",
  ui_story_5083_50830802_20_dialog_content = "Você não está evacuando, está?",
  ui_story_5083_50830802_21_dialog_content = "A Subcidade 13 está à beira do colapso, e alguém precisa acionar a sequência de autodestruição... Se o caminho para Gannon City estiver bloqueado, o colapso também será evitado.",
  ui_story_5083_50830802_22_dialog_content = "Há uma chance de que esta cidade seja reconstruída algum dia... Então eu vou ficar aqui e esperar até que esse dia chegue... No entanto...",
  ui_story_5083_50830802_23_dialog_content = "... Alguns dos seus soldados se recusam a sair, certo?",
  ui_story_5083_50830802_24_dialog_content = "Heh, isso mesmo. Afinal, eu treinei cada um deles para serem os excelentes soldados que são hoje.",
  ui_story_5083_50830802_25_dialog_content = "Eu entendo... Ainda tenho muita luta para fazer do meu lado, então estou solicitando que seus soldados se juntem a mim aqui.",
  ui_story_5083_50830802_26_dialog_content = "Isso é uma ordem.",
  ui_story_5083_50830802_27_dialog_content = "Entendido... Eles estão em suas mãos agora, Pango. Prometa que cuidará bem deles.",
  ui_story_5083_50830802_28_dialog_content = "Eu prometo... Velho amigo.",
  ui_story_5083_50830802_29_dialog_content = "Este é o adeus, Pango... Lembre-se de ficar bem longe desta cidade.",
  ui_story_5083_50830802_30_dialog_content = "Eu darei a eles a ordem para evacuar em breve... Esplendor Illumina!",
  ui_story_5083_50830802_31_dialog_content = "Eu saúdo você, camarada... Splendor Illumina!",
  ui_story_5083_50830802_32_dialog_content = "O que você está fazendo, Comandante Pango?! Ainda há pessoas na Subcidade 13, o que significa que ainda há esperança para eles! Por que você tiraria os soldados dele—",
  ui_story_5083_50830802_33_dialog_content = "Poupe seu fôlego e vá descansar um pouco! Pela expressão no seu rosto, parece que você não está pensando direito.",
  ui_story_5083_50830802_34_dialog_content = "Mas...",
  ui_story_5083_50830802_35_dialog_content = "Eu dei uma ordem a você, Barton! Lembre-se do seu lugar, soldado!",
  ui_story_5083_50830802_36_dialog_content = "... Tch!",
  ui_story_5083_50830802_37_dialog_content = "Você quer salvar o máximo deles que puder, não quer?",
  ui_story_5083_50830802_38_dialog_content = "... Tudo que sempre quisemos foi construir a Illumina. Mas depois de todos esses anos de luta, nossos olhos velhos finalmente estão começando a ficar um pouco embaçados.",
  ui_story_5083_50830802_39_dialog_content = "Jovens soldados como você são os únicos que podem romper até a luz da alvorada. Seus olhos são mais aguçados, e suas mentes também...",
  ui_story_5083_50830802_40_dialog_content = "Heh, o Grande Marechal e eu não éramos muito mais velhos do que você quando lutamos na Guerra da Zona Escura.",
  ui_story_5083_50830802_41_dialog_content = "Não tenho certeza de quando começou... Mas de alguma forma, acabamos exatamente como as pessoas que ressentíamos naquela época.",
  ui_story_5083_50830802_42_dialog_content = "... Esplendor Illumina! Eu saúdo você, senhor.",
  ui_story_5083_50830802_43_dialog_content = "Ah, apenas vá descansar. Preciso de um momento sozinho... Para me despedir do meu velho amigo.",
  ui_story_5083_50830802_44_dialog_content = "Bip—Barton... Meus sensores indicam que seu ânimo está baixo. Por favor, venha comigo...",
  ui_story_5083_50830802_45_dialog_content = "?!",
  ui_story_5083_50830802_46_dialog_content = "Ainda vivo, hein? Mas você não parece muito com isso.",
  ui_story_5083_50830802_47_dialog_content = "Não fique tão surpreso! Seu mensageiro conseguiu chegar à Cidade Gannon, e o Grande Marechal imediatamente enviou reforços assim que soube que a Subcidade 19 estava segura.",
  ui_story_5083_50830802_48_dialog_content = "Estamos aqui apenas por nossas ordens.",
  ui_story_5083_50830802_49_dialog_content = "... Você está bem?",
  ui_story_5083_50830802_50_dialog_content = "Você... Seu idiota! Você poderia ter chegado aqui mais tarde?!",
  ui_story_5083_50830802_51_dialog_content = "Você tem alguma ideia de quantas pessoas perdemos?! Droga!",
  ui_story_5083_50830802_52_dialog_content = "É tudo o que você tem a dizer para mim?! Se eu não tivesse atirado naquele enorme Eclipsite mais cedo, você teria sido acabado - Idiota!",
  ui_story_5083_50830802_53_dialog_content = "Argh—!!!",
  ui_story_5083_50830802_54_dialog_content = "... Então por que você está tão triste, Barton? É porque... o Comandante Barton estava disposto a deixar seu amigo ir assim?",
  ui_story_5083_50830802_55_dialog_content = "A Subcidade 13 ainda poderia ser salva... Eles poderiam estar aqui agora, nos ajudando a defender este lugar... Mas em vez disso, eles vão explodi-la.",
  ui_story_5083_50830802_56_dialog_content = "O velhote até teve a audácia de tirar os soldados mais leais do seu amigo... E deixá-lo lá para morrer sozinho...",
  ui_story_5083_50830802_57_dialog_content = "Você prefere que eles morram ao lado dele?",
  ui_story_5083_50830802_58_dialog_content = "Tenho certeza de que você sabe exatamente como eles se sentem... Se estivéssemos na mesma posição, nada nos impediria de estar com o Comandante Pango.",
  ui_story_5083_50830802_59_dialog_content = "Eles teriam que quebrar nossas pernas e nos trancar no carro de fuga para nos fazer sair.",
  ui_story_5083_50830802_60_dialog_content = "...",
  ui_story_5083_50830802_61_dialog_content = "Mas se o Comandante Pango concordar com seu amigo, então isso significa que realmente não há salvação para a Subcidade 13.",
  ui_story_5083_50830802_62_dialog_content = "Não há razão para tantas pessoas perderem suas vidas na explosão... Ao dar-lhes uma nova missão, ele também está dando-lhes um novo motivo para sobreviver.",
  ui_story_5083_50830802_63_dialog_content = "Esse sempre foi um dos princípios orientadores da Illumina.",
  ui_story_5083_50830802_64_dialog_content = "Ninguém está mentindo ou virando as costas um para o outro, Barton; A Subcidade 19 vai continuar lutando. Pense nisso como... Um acordo não dito entre dois antigos oficiais.",
  ui_story_5083_50830802_65_dialog_content = "Então, quando eles inventam algo tão ridículo quanto uma \"nova missão\", é apenas a maneira deles de proteger os soldados que treinaram com todo o coração.",
  ui_story_5083_50830802_66_dialog_content = "Então, por que não perguntar a eles o que pensam?! Tenho certeza de que nenhum deles quer ouvir seu próprio comandante falar sobre se sacrificar...",
  ui_story_5083_50830802_67_dialog_content = "É porque eles são seus filhos, Barton. Todos eles são crianças de Illumina.",
  ui_story_5083_50830802_68_dialog_content = "É por isso que ele está disposto a ir tão longe por eles...",
  ui_story_5083_50830900_1_dialog_content = "<color=#e8d9bb>Após vários dias de luta constante, os Eclipsitas finalmente começam a recuar das planícies, revelando as incontáveis cicatrizes deixadas no campo de batalha.</color>",
  ui_story_5083_50830900_2_dialog_content = "<color=#e8d9bb>A Subcidade 19 está salva, mas a 2ª Legião perdeu mais da metade de suas tropas.</color>",
  ui_story_5083_50830900_3_dialog_content = "<color=#e8d9bb>Barton se deita no chão ao lado de seus camaradas caídos, olhando fixamente para o sol aparentemente sem calor.</color>",
  ui_story_5083_50830900_4_dialog_content = "Levante-se. É hora de irmos.",
  ui_story_5083_50830900_5_dialog_content = "Comandante Pango?",
  ui_story_5083_50830900_6_dialog_content = "Gostaria de fazer isso... Mas os soldados com quem tiramos aquela foto em grupo ainda estão aqui deitados, e eles nunca vão se levantar.",
  ui_story_5083_50830900_7_dialog_content = "Vim aqui para salvar pessoas. Não esperava que tantos dos meus camaradas perecessem sob o meu comando...",
  ui_story_5083_50830900_8_dialog_content = "... Aqui.",
  ui_story_5083_50830900_9_dialog_content = "Pesado, não é? Lembre-se deles, Barton; lembre-se de seus nomes e de seus passados.",
  ui_story_5083_50830900_10_dialog_content = "Como os sobreviventes desta batalha, é nosso dever continuar.",
  ui_story_5083_50830900_11_dialog_content = "Maldito punk, parece que essa luta realmente te deixou sem juízo. Mas você ainda tem que continuar, mesmo que seja apenas para garantir que os nomes deles sejam inscritos naquele monumento!",
  ui_story_5083_50830900_12_dialog_content = "Você acha que eu não sei disso?! É apenas...",
  ui_story_5083_50830900_13_dialog_content = "Sem desculpas, Barton! Temos a obrigação de garantir que os sacrifícios deles não foram em vão! Ou as ações deles realmente significam tão pouco para você?!",
  ui_story_5083_50830900_14_dialog_content = "... Bom. Agora que a Subcidade 19 está salva, esta batalha servirá como uma mensagem.",
  ui_story_5083_50830900_15_dialog_content = "Esta é uma mensagem para todas as Subcidades, incluindo aquelas que ainda estão lutando na linha de frente.",
  ui_story_5083_50830900_16_dialog_content = "Ouvir sobre nossa vitória aqui hoje fortalecerá a fé de todos... Se a Subcidade 19 pôde ser salva, então todas as outras Subcidades de Illumina também podem.",
  ui_story_5083_50830900_17_dialog_content = "Algum dia, Astra estará livre dos estragos desta guerra.",
  ui_story_5083_50830900_18_dialog_content = "Mas essa é uma conversa para outra hora. Pelo menos, conseguimos manter a chama da esperança viva, e isso tem que significar algo.",
  ui_story_5083_50830900_19_dialog_content = "Mesmo que isso signifique sacrificar constantemente nossas almas para alimentar suas chamas, tudo valerá a pena no final—",
  ui_story_5083_50830900_20_dialog_content = "Hmph—Não pretendo fazer tantos sacrifícios uma vez que estou no comando deste navio.",
  ui_story_5083_50830900_21_dialog_content = "Se alguém tem que queimar pela esperança, então serei eu. Se esse dia chegar, as chamas vão queimar mais quentes do que nunca antes...",
  ui_story_5083_50830900_22_dialog_content = "<color=#e8d9bb>A mensagem da salvação da Subcidade 19 se espalha por Illumina como um incêndio. Antes mesmo de os soldados retornarem para casa, a cidade de Gannon já está agitada com as notícias de sua vitória.</color>",
  ui_story_5083_50830900_23_dialog_content = "<color=#e8d9bb>De acordo com o relatório oficial, Barton e os outros são aclamados como heróis de elite enviados pelo próprio Grande Marechal.</color>",
  ui_story_5083_50830900_24_dialog_content = "<color=#e8d9bb>Em vista de suas realizações excepcionais, todas as acusações criminais previamente feitas contra eles são sumariamente retiradas—</color>",
  ui_story_5083_50830900_25_dialog_content = "Qual é o credo de Illumina, Pango? Diga-me agora mesmo!",
  ui_story_5083_50830900_26_dialog_content = "\"Um por todos, e todos por um.\"",
  ui_story_5083_50830900_27_dialog_content = "Não se esqueça do resto! \"Pelo bem de Illumina, todas as ordens devem ser seguidas!\"",
  ui_story_5083_50830900_28_dialog_content = "Você opera com total desrespeito às ordens e ensina seus subordinados a fazer o mesmo!",
  ui_story_5083_50830900_29_dialog_content = "Se não fosse pela salvação da Subcidade 19, as coisas não teriam terminado tão bem para você ou seus soldados!",
  ui_story_5083_50830900_30_dialog_content = "Seus subordinados perderam suas vidas por causa de sua arrogância!",
  ui_story_5083_50830900_31_dialog_content = "Não nos consideramos sortudos de forma alguma, Grande Marechal! Nós sacrificamos tanto para—",
  ui_story_5083_50830900_32_dialog_content = "Silêncio!",
  ui_story_5083_50830900_33_dialog_content = "S-Seu nome é Barton, certo? Você acha que só porque é um herói que pode falar fora de hora?!",
  ui_story_5083_50830900_34_dialog_content = "Ele não quis dizer nada com isso, Grande Marechal! Meu colega aqui é simplesmente um idiota!",
  ui_story_5083_50830900_35_dialog_content = "... E você! Você tem alguma ideia de quantos problemas causou ao seguir o exemplo deles—",
  ui_story_5083_50830900_36_dialog_content = "Desculpe a interrupção, Grande Marechal.",
  ui_story_5083_50830900_37_dialog_content = "Um secretário do Comitê? Quem deixou você entrar aqui?!",
  ui_story_5083_50830900_38_dialog_content = "Estou aqui apenas para entregar uma mensagem urgente do Comitê, senhor.",
  ui_story_5083_50830900_39_dialog_content = "Com o sucesso da operação de resgate e a publicidade em torno de seus heróis, o moral dentro da Illumina está em alta como nunca antes. O Comitê está muito satisfeito com as ações tomadas por esses bravos soldados.",
  ui_story_5083_50830900_40_dialog_content = "Satisfeito? Com eles?! Hah!",
  ui_story_5083_50830900_41_dialog_content = "Particularmente merecedores de elogios são o Tenente Reinhardt... Assim como o Capitão Barton. O Comitê acredita que esses dois soldados devem ser retratados como modelos para toda a Federação.",
  ui_story_5083_50830900_42_dialog_content = "Ainda estamos em guerra aqui. Não é hora de brincar de jogos!",
  ui_story_5083_50830900_43_dialog_content = "É precisamente porque estamos em guerra que o Comitê vê a necessidade de soldados exemplares para fortalecer o sentimento público.",
  ui_story_5083_50830900_44_dialog_content = "... O que exatamente vocês têm em mente?",
  ui_story_5083_50830900_45_dialog_content = "Por que não promover meu subcomandante, então? Ele pode ser um idiota, mas é habilidoso o suficiente para assumir o comando de toda a Divisão de Infantaria Mecanizada.",
  ui_story_5083_50830900_46_dialog_content = "Isso deve ser fácil de organizar, senhor. Quanto a você, Tenente Reinhardt, ainda estamos discutindo uma possível recompensa para você. Você seria tão gentil a ponto de vir comigo? Agora mesmo, por favor.",
  ui_story_5083_50830900_47_dialog_content = "Lidere o caminho.",
  ui_story_5083_50830900_48_dialog_content = "Se não houver mais nada, Grande Marechal, então também vamos nos despedir.",
  ui_story_5083_50830900_49_dialog_content = "... Você está dispensado.",
  ui_story_5083_50830900_50_dialog_content = "Espere um segundo! Dogg, Comandante Pango... Não parecia que tinha algo estranho naquela reunião agora há pouco?",
  ui_story_5083_50830900_51_dialog_content = "Esse membro do Comitê mal prestou atenção no Grande Marechal. Ele foi ainda mais rude com ele do que eu...",
  ui_story_5083_50830900_52_dialog_content = "Diga algo, você? Não posso ser o único que acha isso estranho! Eles nem se deram ao trabalho de consultar o Grande Marechal sobre minha promoção!",
  ui_story_5083_50830900_53_dialog_content = "...",
  ui_story_5083_50830900_54_dialog_content = "Isso não é da sua conta, garoto.",
  ui_story_5083_50830900_55_dialog_content = "Eu sei que o Comitê tem muito poder sobre nós, mas—",
  ui_story_5083_50830900_56_dialog_content = "Eu te disse que isso não é da sua conta! Não adianta tentar entender essas pessoas, Barton... Ou falar sobre elas, aliás.",
  ui_story_5083_50830900_57_dialog_content = "Apenas aceite sua promoção e trabalhe duro para treinar novos recrutas para a 2ª Legião—",
  ui_story_5083_50830900_58_dialog_content = "E não me deixe nunca te pegar relaxando.",
  ui_story_5083_50831000_1_dialog_content = "Ei, Reinhardt! Tem um segundo para conversar?",
  ui_story_5083_50831000_2_dialog_content = "Você é da 2ª Legião, certo? O que te traz aqui em um momento como este? Se você está aqui para provocar uma luta, eu sou um oponente melhor do que Reinhardt.",
  ui_story_5083_50831000_3_dialog_content = "Acalme-se Wrath, ele não está aqui para começar nada. O Comandante Barton é um amigo meu.",
  ui_story_5083_50831000_4_dialog_content = "... Eu tenho pensado nisso por dias agora, mas ainda não consigo entender. Por que eles estão fazendo isso com você, Reinhardt? Além de não promovê-lo, seu próprio Comandante da Legião o puniu por salvar Undercity 19!",
  ui_story_5083_50831000_5_dialog_content = "Vamos conversar em algum lugar em particular.",
  ui_story_5083_50831000_6_dialog_content = "Vou apenas seguir em frente e perguntar, Reinhardt: qual é a sua conexão com o Comitê?",
  ui_story_5083_50831000_7_dialog_content = "Não sou estúpido; qualquer um pode ver que você está de alguma forma conectado a eles, especialmente porque eles nunca parecem te deixar em paz.",
  ui_story_5083_50831000_8_dialog_content = "Quando aquele secretário invadiu a sala de reuniões do Grande Marechal da última vez, ele estava realmente lá por você, não estava?",
  ui_story_5083_50831000_9_dialog_content = "O que ele queria de você? E por que... Por que eles não estão te protegendo?",
  ui_story_5083_50831000_10_dialog_content = "Como meu amigo, estive procurando a oportunidade certa para te contar sobre essas coisas, Barton.",
  ui_story_5083_50831000_11_dialog_content = "Para começar, você está absolutamente certo: o Comitê realmente presta atenção especial em mim. Quanto ao motivo... Talvez seja porque eles me escolheram para algo.",
  ui_story_5083_50831000_12_dialog_content = "Não tenho certeza do que é... Mas parece que eles têm um plano de treinamento especial em mente para mim, um que irá desbloquear todo o meu potencial de combate.",
  ui_story_5083_50831000_13_dialog_content = "Essa pode ser a razão pela qual eles decidiram aparecer durante aquela reunião.",
  ui_story_5083_50831000_14_dialog_content = "Quanto ao motivo de eles não terem impedido meu comandante de me punir... Acho que provavelmente é algum tipo de aviso.",
  ui_story_5083_50831000_15_dialog_content = "Um aviso, hein... Isso significa que Dogg estava certo sobre você? Você está aqui apenas porque alguém do comitê está te apoiando?",
  ui_story_5083_50831000_16_dialog_content = "Você é seriamente esse tipo de pessoa, Reinhardt?",
  ui_story_5083_50831000_17_dialog_content = "Nem um pouco! Se for o caso, eu sou apenas um peão no grande esquema das coisas.",
  ui_story_5083_50831000_18_dialog_content = "Mesmo que o Comitê esteja me treinando para me tornar ainda mais forte... Eles estão igualmente preocupados em me manter sob o controle deles.",
  ui_story_5083_50831000_19_dialog_content = "Barton... Se eu te contar mais da minha história, você acabará no meu \"navio pirata\" como da última vez.",
  ui_story_5083_50831000_20_dialog_content = "Você está bem com isso?",
  ui_story_5083_50831000_21_dialog_content = "Eu confiei em você com minha vida antes, não confiei? Por que eu diria não desta vez?",
  ui_story_5083_50831000_22_dialog_content = "À medida que a luta se intensifica, cada soldado tem o potencial de se tornar combustível para as chamas da vitória... Isso é especialmente verdadeiro para as pessoas no Comitê.",
  ui_story_5083_50831000_23_dialog_content = "Minha irmã e eu, assim como um dos meus amigos, fazemos todos parte do plano deles... E embora digam que estão apenas nos testando, algo nisso não parece certo.",
  ui_story_5083_50831000_24_dialog_content = "Não é qualquer um que pode resistir ao seu treinamento especial, especialmente não crianças... Depois de passar por isso eu mesmo, sei o quão brutal pode ser.",
  ui_story_5083_50831000_25_dialog_content = "Depois de ver tudo o que vi, não acredito que o Grande Marechal ignore as ações do Comitê... Na verdade, acho que ele as aprova.",
  ui_story_5083_50831000_26_dialog_content = "Não duvido da convicção do Grande Marechal em relação à guerra, mas consigo ver o medo e o esgotamento em seus olhos. A vontade de continuar lutando não é suficiente para garantir o futuro, pelo menos não por si só.",
  ui_story_5083_50831000_27_dialog_content = "... Você uma vez me contou sobre seu <color=#FFB400>pequeno sonho</color> de se tornar o Grande Marechal algum dia.",
  ui_story_5083_50831000_28_dialog_content = "Ainda é verdade. Um dia, vou ser o mais forte e decisivo Grande Marechal da Illumina!",
  ui_story_5083_50831000_29_dialog_content = "Tenho certeza de que alguém lhe disse para não fazer perguntas sobre o Comitê, certo Barton? Mas a verdade é que a Illumina nunca conseguirá zarpar até que nos libertemos deles.",
  ui_story_5083_50831000_30_dialog_content = "Heh, você acha que este navio pirata seu é grande o suficiente para carregar todos em Illumina?",
  ui_story_5083_50831000_31_dialog_content = "Você não sabia? Até um passarinho precisa se libertar do seu ovo para encontrar seu lugar no mundo. Para darmos passos maiores, precisamos nos libertar de nossas correntes.",
  ui_story_5083_50831000_32_dialog_content = "Se realmente queremos libertar toda a Astra e começar de novo... Temos que começar libertando a Illumina das pessoas que a controlam por trás dos bastidores.",
  ui_story_5083_50831000_33_dialog_content = "Você precisa ser sério se quiser se rebelar contra as forças no poder.",
  ui_story_5083_50831000_34_dialog_content = "Você não vai conseguir nada disso apenas com palavras, Reinhardt. Então me diga, como posso te ajudar?",
  ui_story_5083_50831000_35_dialog_content = "Ao unir forças comigo e me ajudar a erradicar a corrupção na Illumina.",
  ui_story_5083_50831000_36_dialog_content = "Neste momento, os soldados de Illumina estão presos por todos os tipos de grilhões. Inseguros do significado por trás de seus sacrifícios, eles simplesmente vivem e lutam, sabendo que podem ter que morrer por nós algum dia.",
  ui_story_5083_50831000_37_dialog_content = "E aqueles que se recusam a lutar são caçados pelos <color=#FFB400>Executores</color>. Isso é realmente o melhor que a Illumina pode esperar?",
  ui_story_5083_50831000_38_dialog_content = "Não nos foi dada uma escolha quando viemos a este mundo, mas nosso povo deve saber pelo que estão lutando e morrendo!",
  ui_story_5083_50831000_39_dialog_content = "E começa com você, comigo e com cada pessoa que acredita em um futuro melhor! Uma vez que começamos por este caminho, é apenas uma questão de tempo até que a Illumina encontre a verdadeira iluminação.",
  ui_story_5083_50831000_40_dialog_content = "Só então podemos esperar salvar todo o Astra, e uma vez que começamos de novo... Podemos perseguir sonhos ainda maiores.",
  ui_story_5083_50831000_41_dialog_content = "Se você quer se livrar da corrupção da Illumina, precisa estar preparado para o pior resultado possível: outra guerra.",
  ui_story_5083_50831000_42_dialog_content = "Eu nunca tive a intenção de obedecer àqueles velhos indecisos.",
  ui_story_5083_50831000_43_dialog_content = "Deixarei minha alma se inflamar se for o que for necessário para me livrar de sua terrível decepção. Contanto que ilumine o caminho para todos em Illumina, não terei arrependimentos.",
  ui_story_5083_50831000_44_dialog_content = "É quase garantido que terei que enfrentá-los como um <color=#FFB400>traidor</color>, o que significa que precisarei de todos os aliados que conseguir!",
  ui_story_5083_50831000_45_dialog_content = "Esse é o espírito, Reinhardt! Enquanto você nunca perder de vista essa luz, minha vida sempre estará em suas mãos!",
  ui_story_5083_50831000_46_dialog_content = "Seja eu ou meus soldados, tenha certeza de que seguiremos qualquer ordem que você nos der.",
  ui_story_5083_50831000_47_dialog_content = "É apenas...",
  ui_story_5083_50831000_48_dialog_content = "Bem o quê?",
  ui_story_5083_50831000_49_dialog_content = "Heh... Hahahaha! É só que depois de ser rebaixado tanto, você tem uma longa escalada à sua frente se quiser se tornar Grande Marechal!",
  ui_story_5083_50831000_50_dialog_content = "Então é melhor você tomar cuidado, ou eu posso te superar!",
  ui_story_5083_50831000_51_dialog_content = "Com certeza vou te parabenizar de todo o meu coração se você se tornar o Grande Marechal primeiro.",
  ui_story_5083_50831000_52_dialog_content = "Embora eu acho que a posição em si não é o que é importante.",
  ui_story_5083_50831000_53_dialog_content = "Sim, você tem razão.",
  ui_story_5083_50831000_54_dialog_content = "Há mais uma coisa - eu realmente não quero esconder nada disso do Comandante Pango, considerando que ele praticamente me criou.",
  ui_story_5083_50831000_55_dialog_content = "Precisamos de todos os amigos que conseguirmos, certo? Além disso... A última coisa que quero é fazer dele um inimigo.",
  ui_story_5083_50831000_56_dialog_content = "Não se preocupe, você pode contar tudo o que conversamos aqui para ele.",
  ui_story_5083_50831000_57_dialog_content = "Você está confiando em mim com sua vida; só é justo que eu faça o mesmo por você.",
  ui_story_5083_50831000_58_dialog_content = "Eu acredito no seu julgamento, assim como nas pessoas em quem você mais confia.",
  ui_story_5083_50831000_59_dialog_content = "Então, o que estamos esperando? Por que não juntamos todos e conversamos?",
  ui_story_5083_50831000_60_dialog_content = "Ouvi dizer que o refeitório está oferecendo uma nova comida saborosa. Vamos chamar todos para a Área de Alocação e conversar.",
  ui_story_5083_50831000_61_dialog_content = "<size=45>Parece bom para mim!</size>",
  ui_story_5083_50831100_1_dialog_content = "Pedi aos meus amigos para chamar algumas pessoas que possam ser simpáticas à nossa causa. Seria útil se pudéssemos fazer o Negador se juntar a nós também... Mas vamos apenas para lá por enquanto.",
  ui_story_5083_50831100_2_dialog_content = "Talvez eu deva voltar primeiro para o acampamento? Assim, eu posso levar Dogg e o velhote também.",
  ui_story_5083_50831100_3_dialog_content = "Não se preocupe, meus amigos passarão a mensagem para Dogg se o virem. Quanto ao Comandante Pango, ele pode se sentir um pouco desconfortável em uma sala cheia de soldados jovens e potencialmente rebeldes.",
  ui_story_5083_50831100_4_dialog_content = "E depois de desagradá-lo tantas vezes, acho que deveria estar mais preparado antes de abordá-lo sobre isso.",
  ui_story_5083_50831100_5_dialog_content = "Ha! Então você também tem medo do velhote, hein?",
  ui_story_5083_50831100_6_dialog_content = "A-Apenas fale baixo e me siga!",
  ui_story_5083_50831100_7_dialog_content = "Aliás, tem algo que você gostaria de comer? Ou talvez um hobby ou interesse?",
  ui_story_5083_50831100_8_dialog_content = "Você pode ficar até que todos se encontrem. Vou pegar uma mesa para nós no refeitório.",
  ui_story_5083_50831100_9_dialog_content = "Não. Por que eu correria por aí se não há guerra?",
  ui_story_5083_50831100_10_dialog_content = "Então, o que você faz no seu tempo livre na base?",
  ui_story_5083_50831100_11_dialog_content = "Ficar no quartel ou fazer meus próprios exercícios.",
  ui_story_5083_50831100_12_dialog_content = "Quê? Isso é bastante chato.",
  ui_story_5083_50831100_13_dialog_content = "Não, não é! Não temos nada melhor para fazer enquanto isso, de qualquer maneira.",
  ui_story_5083_50831100_14_dialog_content = "Sem mencionar que é uma bagunça em todos os lugares que você vai com a guerra acontecendo.",
  ui_story_5083_50831100_15_dialog_content = "Eu pelo menos sairia com as garotas nas minhas folgas, mas você parece ser caseiro como Gronru.",
  ui_story_5083_50831100_16_dialog_content = "Isso não é 100% verdade. Eu também acompanho a última tendência.",
  ui_story_5083_50831100_17_dialog_content = "Até sei onde fica o playground secreto por perto.",
  ui_story_5083_50831100_18_dialog_content = "Tudo bem, você vai se divertir enquanto eu vou pegar uma mesa e buscar Helios e os outros no caminho.",
  ui_story_5083_50831100_19_dialog_content = "Ah, a propósito, Helios é meu amigo de infância. Ele é muito legal, e vocês dois com certeza vão se dar bem.",
  ui_story_5083_50831100_20_dialog_content = "Não faço ideia para onde ir, muito menos sair...",
  ui_story_5083_50831100_21_dialog_content = "Eu teria voltado para a base e dado um aviso ao Dogg se eu soubesse.",
  ui_story_5083_50831100_22_dialog_content = "Beep—Por favor, tente aproveitar seu tempo livre, Barton.",
  ui_story_5083_50831100_23_dialog_content = "Eu nem mesmo sei para onde estou indo, então eu acho que o \"parquinho secreto\" de Gronru é minha única opção.",
  ui_story_5083_50831100_24_dialog_content = "Alguém como Gronru estaria interessado em algo assim, no entanto?",
  ui_story_5083_50831100_25_dialog_content = "Ela é do tipo que diria: \"Uau, o futuro da Illumina! Que chato. Vou para casa jogar jogos.\"",
  ui_story_5083_50831100_26_dialog_content = "O que você está fazendo vagando fora do meu fliperama secreto? Querendo lutar contra o Rei Naval de novo?",
  ui_story_5083_50831100_27_dialog_content = "Isso veio do nada... Ei, onde foi parar o meu drone? Ele fugiu de novo? Quão tímido ele pode ser?",
  ui_story_5083_50831100_28_dialog_content = "Tenho uma festa para te convidar. Reinhardt não te contou? Vamos nos encontrar na cafeteria para discutir algumas coisas.",
  ui_story_5083_50831100_29_dialog_content = "Festa? Eu não ouvi falar sobre isso... Parece divertido e eu quero ir!",
  ui_story_5083_50831100_30_dialog_content = "Tenha cuidado para não ser enganado novamente. Você pode não conseguir sair disso.",
  ui_story_5083_50831100_31_dialog_content = "Estamos quase lá. Tem algo que você gostaria de comer?",
  ui_story_5083_50831100_32_dialog_content = "É óbvio que você não tem ideia do que é gostoso ou não, Barton.",
  ui_story_5083_50831100_33_dialog_content = "Eu não tenho tempo para ser exigente. Illumina estaria em grandes apuros se nós, soldados, começássemos a odiar as rações militares.",
  ui_story_5083_50831100_34_dialog_content = "Nos esforçamos para melhorar a comida por aqui, apenas para agradar as papilas gustativas na linha de frente.",
  ui_story_5083_50831100_35_dialog_content = "Como o Peixe Grelhado Desidratado de Umbraton e as barras de energia de chocolate. Você saberá quando experimentar!",
  ui_story_5083_50831100_36_dialog_content = "Está saboroso, mas você simplesmente devorou, Barton. Vai ter espaço para mais tarde?",
  ui_story_5083_50831100_37_dialog_content = "*Mastigue, mastigue* Meu apetite está maior que o normal. Isso é um requisito para ser um bom soldado.",
  ui_story_5083_50831100_38_dialog_content = "Acho que se você ganhar na próxima vez, vou te enviar para experimentar os novos produtos para mim e economizar uma viagem.",
  ui_story_5083_50831100_39_dialog_content = "Ei, o que você está fazendo aí, Barton?",
  ui_story_5083_50831100_40_dialog_content = "Fui enviado para vir buscar você... O que está acontecendo? Você está se empanturrando!",
  ui_story_5083_50831100_41_dialog_content = "Não se importe com isso e experimente este biscoito de cereja desidratado!",
  ui_story_5083_50831100_42_dialog_content = "O quê? Não, obrigado. Acho que posso ficar cheio com apenas uma mordida.",
  ui_story_5083_50831100_43_dialog_content = "Ah, vamos lá, experimente. É realmente bom.",
  ui_story_5083_50831100_44_dialog_content = "Estou aqui a negócios, então tire isso daqui... Não acredito que você não está levando isso a sério!",
  ui_story_5083_50831100_45_dialog_content = "Na verdade, não é ruim.",
  ui_story_5083_50831100_46_dialog_content = "Dê-me outro.",
  ui_story_5083_50831100_47_dialog_content = "Vá com calma ou você ficará muito cheio para mais tarde! Vamos, vamos ver Reinhardt.",
  ui_story_5083_50831100_48_dialog_content = "O que vocês estão fazendo...?",
  ui_story_5083_50831100_49_dialog_content = "Algo divertido! E você está nele. Não tente escapar depois de comer.",
  ui_story_5083_50831100_50_dialog_content = "Aqui! Encontrei um lugar no canto. Venha rápido!",
  ui_story_5083_50831100_51_dialog_content = "Oh, aprendi muitas coisas novas então estaremos treinando em breve.",
  ui_story_5083_50831100_52_dialog_content = "Seriamente?",
  ui_story_5083_50831100_53_dialog_content = "Olá, meu nome é Helios. Obrigado por levar Reinhardt para casa em segurança.",
  ui_story_5083_50831100_54_dialog_content = "Sou Barton. Este aqui é Dogg. Você pode cortar as formalidades. Afinal, somos da Illumina.",
  ui_story_5083_50831100_55_dialog_content = "Sem mencionar que Reinhardt também me ajudou bastante.",
  ui_story_5083_50831100_56_dialog_content = "Temos um problema! O Negador está preso na multidão lutando por comida e não consegue sair. Preciso que duas pessoas venham comigo!",
  ui_story_5083_50831100_57_dialog_content = "O que há com o alvoroço?",
  ui_story_5083_50831100_58_dialog_content = "Você não estava brincando sobre não prestar atenção à comida, eu vejo. As novas ofertas são uma prioridade para a linha de frente, então Gannon só recebe o excesso.",
  ui_story_5083_50831100_59_dialog_content = "Dizem que são extremamente deliciosos, então não é incomum haver brigas.",
  ui_story_5083_50831100_60_dialog_content = "Eu tenho que ir ajudá-la!",
  ui_story_5083_50831100_61_dialog_content = "Realmente, Reinhardt, você reuniu todos apenas para lutar por comida na cafeteria?",
  ui_story_5083_50831100_62_dialog_content = "É uma grande mancha na honra da Legião se nem conseguirmos garantir uma refeição! Todos, sigam-me para a batalha! Exceto por Reinhardt.",
  ui_story_5083_50831100_63_dialog_content = "Ah, jovem e entusiasmado, eu vejo!",
  ui_story_5083_50831100_64_dialog_content = "Então, nós apenas esperamos aqui?",
  ui_story_5083_50831100_65_dialog_content = "Acho que não devemos nos envolver.",
  ui_story_5083_50831100_66_dialog_content = "Negador conseguiu para você seu pudim favorito, Gronru!",
  ui_story_5083_50831100_67_dialog_content = "Sério? Certo, deixe-me me preparar para uma invasão!",
  ui_story_5083_50831100_68_dialog_content = "Quente, quente... Havia tantas pessoas, eu nem conseguia pegar uma bandeja.",
  ui_story_5083_50831100_69_dialog_content = "Deixe-me ajudar você... Ai!",
  ui_story_5083_50831100_70_dialog_content = "Te disse que está quente.",
  ui_story_5083_50831100_71_dialog_content = "Saia do meu caminho! Veja, Barton, eu consegui o dobro do que você conseguiu.",
  ui_story_5083_50831100_72_dialog_content = "Onde você conseguiu essa bandeja?",
  ui_story_5083_50831100_73_dialog_content = "Isso é o que significa ser a elite da elite e o comandante dos comandos.",
  ui_story_5083_50831100_74_dialog_content = "Ainda não consegui tirar o Negador de lá, mas consegui o suficiente para todos nós.",
  ui_story_5083_50831100_75_dialog_content = "Aqui vêm as bebidas! Um must para esta ocasião!",
  ui_story_5083_50831100_76_dialog_content = "Que tal um concurso?",
  ui_story_5083_50831100_77_dialog_content = "Eu desci!",
  ui_story_5083_50831100_78_dialog_content = "Esqueceu algo, Reinhardt?",
  ui_story_5083_50831100_79_dialog_content = "Ah, negador, Gronru e Vaughn ainda estão se empurrando pelos doces.",
  ui_story_5083_50831100_80_dialog_content = "Há uma enorme multidão para aqueles, então vamos fazer uma rodada enquanto esperamos.",
  ui_story_5083_50831100_81_dialog_content = "Eu deveria ver como eles estão.",
  ui_story_5083_50831100_82_dialog_content = "Não tenha tanta pressa. Reinhardt disse que temos tempo para uma rodada.",
  ui_story_5083_50831100_83_dialog_content = "Acho que está tudo bem. Nós temos o tempo.",
  ui_story_5083_50831100_84_dialog_content = "Bem, então saúde?",
  ui_story_5083_50831100_85_dialog_content = "Saúde!",
  ui_story_5083_50831100_86_dialog_content = "<color=#e8d9bb>A Geração Mais Brilhante de Illumina realiza sua primeira reunião em um canto com risadas.</color>",
  ui_story_5083_50831100_87_dialog_content = "<color=#e8d9bb>Eu simplesmente não consigo tirar os olhos da festa. Quero capturar este momento, mesmo que seja fugaz.</color>",
  ui_story_5083_50831100_88_dialog_content = "Que tal uma música? Mostre a canção de luta que você escreveu, Cachorro.",
  ui_story_5083_50831100_89_dialog_content = "Solte-me, seu tolo, e cante você mesmo!",
  ui_story_5083_50831100_90_dialog_content = "Eles certamente estão demorando...",
  ui_story_5083_50831100_91_dialog_content = "Não se preocupe com sua irmã. Ela é velha o suficiente para não se perder.",
  ui_story_5083_50831100_92_dialog_content = "Então, vamos fazer um brinde à nossa incrível parceria!",
  ui_story_5083_50831100_93_dialog_content = "Sobre qual incrível parceria você está falando?",
  ui_story_5083_50831100_94_dialog_content = "Não adianta desviar, porque aqui vem!",
  ui_story_5083_50831100_95_dialog_content = "<size=45>Saúde!</size>",
  ui_story_5083_50831200_1_dialog_content = "...",
  ui_story_5083_50831200_2_dialog_content = "Para ser honesto, eu não achei que você poderia nos encurralar.",
  ui_story_5083_50831200_3_dialog_content = "Você é um tolo, Barton. Você sequer percebe o que está dizendo?",
  ui_story_5083_50831200_4_dialog_content = "Acho que me fiz muito claro... E tenho fé em Reinhardt!",
  ui_story_5083_50831200_5_dialog_content = "Ela enlouqueceu.",
  ui_story_5083_50831200_6_dialog_content = "Acalme-se, Barton. Ela foi rebaixada para a posição mais baixa.",
  ui_story_5083_50831200_7_dialog_content = "Então talvez ela esteja usando você, ou até mesmo nós da 2ª Legião.",
  ui_story_5083_50831200_8_dialog_content = "Defendi a Subcidade 19 por dias com ela.",
  ui_story_5083_50831200_9_dialog_content = "Ela morreria por eles, então como ela poderia ser má?",
  ui_story_5083_50831200_10_dialog_content = "Ela iria, iria ela?",
  ui_story_5083_50831200_11_dialog_content = "Talvez a atual Illumina não seja algo tão impressionante, e muitos dos problemas não podem ser resolvidos facilmente, mas...",
  ui_story_5083_50831200_12_dialog_content = "Cumprir seus objetivos significa que você deve se opor ao Grande Marechal e aos seus amigos.",
  ui_story_5083_50831200_13_dialog_content = "Não concordo, não enquanto ainda estamos lutando contra os Eclipsitas.",
  ui_story_5083_50831200_14_dialog_content = "Eu nunca vou consentir com isso!",
  ui_story_5083_50831200_15_dialog_content = "Lutei por Illumina minha vida inteira. Vejo todos como meu próprio sangue.",
  ui_story_5083_50831200_16_dialog_content = "Eu não vou tolerar nenhuma traição e nunca vou te ajudar!",
  ui_story_5083_50831200_17_dialog_content = "Entendi. Eu pensei que você não veria dessa forma.",
  ui_story_5083_50831200_18_dialog_content = "Mas acho que você pode entender de onde eu venho.",
  ui_story_5083_50831200_19_dialog_content = "Não estamos visando ser outra Lumopolis. Só queremos ser o pilar que sustenta Illumina.",
  ui_story_5083_50831200_20_dialog_content = "As mudanças só vêm depois disso...",
  ui_story_5083_50831200_21_dialog_content = "Basta! Eu não quero ouvir mais nada!",
  ui_story_5083_50831200_22_dialog_content = "...",
  ui_story_5083_50831200_23_dialog_content = "Eu treinei você e acredito no meu julgamento.",
  ui_story_5083_50831200_24_dialog_content = "Acredito que você pode confiar Reinhardt com sua vida.",
  ui_story_5083_50831200_25_dialog_content = "Mas mesmo que o pior aconteça, eu não quero lutar contra velhos camaradas... e eu não quero ter que te matar, Barton.",
  ui_story_5083_50831200_26_dialog_content = "Eu não treinei você para lutar contra Illumina, ou qualquer Aurorian, nesse caso.",
  ui_story_5083_50831200_27_dialog_content = "Isso também não é o que queremos! Nós apenas acreditamos na justiça e lutamos pelo futuro...",
  ui_story_5083_50831200_28_dialog_content = "Continue falando e eu mesmo vou trancá-lo numa cela.",
  ui_story_5083_50831200_29_dialog_content = "Fique tranquilo, Barton. Você ainda não tem certeza do que fazer.",
  ui_story_5083_50831200_30_dialog_content = "Leve o seu tempo e pense bem.",
  ui_story_5083_50831200_31_dialog_content = "Leve o seu tempo e pense bem? Você realmente quer dizer continuar aguentando essa bobagem, certo?",
  ui_story_5083_50831200_32_dialog_content = "Fui promovido a tenente coronel e sou comandante de um batalhão. Não pensei que ainda teria que treinar novatos.",
  ui_story_5083_50831200_33_dialog_content = "Qualquer sargento instrutor poderia fazer isso. Onde eu deveria estar é na linha de frente!",
  ui_story_5083_50831200_34_dialog_content = "E as sessões de fotos para o Comitê... Eu não sou nenhuma supermodelo.",
  ui_story_5083_50831200_35_dialog_content = "Por que eles não prestam atenção nos verdadeiros heróis lá na frente? Estou perdendo meu tempo falando sobre como é seguro aqui atrás!",
  ui_story_5083_50831200_36_dialog_content = "Ainda é muito cedo para você.",
  ui_story_5083_50831200_37_dialog_content = "Como assim?",
  ui_story_5083_50831200_38_dialog_content = "Apenas quando os aliados te ajudarem no futuro, você pode se tornar...",
  ui_story_5083_50831200_39_dialog_content = "Beep—Pelo menos Barton não foi punido.",
  ui_story_5083_50831200_40_dialog_content = "Ah, como isso escapou da minha mente.",
  ui_story_5083_50831200_41_dialog_content = "Eu deveria conversar com meus amigos em vez de tagarelar sozinho.",
  ui_story_5083_50831200_42_dialog_content = "É uma pena que Dogg não tenha visto olho no olho comigo.",
  ui_story_5083_50831200_43_dialog_content = "Não importa, eu consegui ver Reinhardt. Você sabe onde ela está?",
  ui_story_5083_50831200_44_dialog_content = "Bip—Siga-me, Barton.",
  ui_story_5083_50831200_45_dialog_content = "Esta é a loja de Gronru... Mas ela é próxima daqueles dois, então ela deve saber onde Reinhardt está.",
  ui_story_5083_50831200_46_dialog_content = "Com quem você está falando? Ela não está. Eu estou no comando enquanto ela está fora, então me diga o seu negócio.",
  ui_story_5083_50831200_47_dialog_content = "Diga, você não deveria estar na base, Propaganda para Illumina?",
  ui_story_5083_50831200_48_dialog_content = "Eu saí de mansinho.",
  ui_story_5083_50831200_49_dialog_content = "Mas não importa isso. Onde está Reinhardt? Para onde ela foi?",
  ui_story_5083_50831200_50_dialog_content = "Fazendo seus exercícios especiais e sonhando em ser a Grande Marechal.",
  ui_story_5083_50831200_51_dialog_content = "Você não se dá bem com ela? Por que você desaprova tanto ela?",
  ui_story_5083_50831200_52_dialog_content = "Quem sabe?",
  ui_story_5083_50831200_53_dialog_content = "Talvez minha irmã mais velha não consiga mais se relacionar comigo...",
  ui_story_5083_50831200_54_dialog_content = "Mesmo que você tenha me derrotado em uma simulação, tenho um conselho para você.",
  ui_story_5083_50831200_55_dialog_content = "Você nunca pode ser Reinhardt. Você não é o mesmo.",
  ui_story_5083_50831200_56_dialog_content = "Qualquer coisa que você não se sinta confortável, deve deixar claro para sua querida irmã.",
  ui_story_5083_50831200_57_dialog_content = "Ela sempre cuidou de você... Não guarde as coisas ou ninguém saberá.",
  ui_story_5083_50831200_58_dialog_content = "Então, o que você quer com ela?",
  ui_story_5083_50831200_59_dialog_content = "Não se preocupe com isso. Não posso falar com ela se ela não estiver por perto. Apenas diga a ela que passei por aqui.",
  ui_story_5083_50831200_60_dialog_content = "Claro.",
  ui_story_5083_50831200_61_dialog_content = "<color=#e8d9bb>As palavras do negador colocaram Barton à vontade. Ele retornou à base e retomou suas tarefas para o Comitê após ação disciplinar.</color>",
  ui_story_5083_50831200_62_dialog_content = "<color=#e8d9bb>Mas ele nunca recebeu uma resposta...</color>",
  ui_story_5083_50831200_63_dialog_content = "<color=#e8d9bb>A cidade de Gannon anunciou uma séria explosão de laboratório com Reinhardt, sua equipe, e Gronru desaparecidos em ação.</color>",
  ui_story_5083_50831301_1_dialog_content = "<color=#e8d9bb>É primavera novamente, mas a Crise Darkover continua. Ninguém sabe de onde os Eclipsitas vêm e por que eles continuam aumentando em números.</color>",
  ui_story_5083_50831301_2_dialog_content = "<color=#e8d9bb>Eles ainda correm desenfreados em Astra e massacram vidas, o que é suficiente para fazer todos lutarem até o fim.</color>",
  ui_story_5083_50831301_3_dialog_content = "<color=#e8d9bb>Na guerra em escalada, uma mensagem urgente chega a Gannon, indicando avistamentos de Eclipsitas perto da defesa da cidade.</color>",
  ui_story_5083_50831301_4_dialog_content = "O que está acontecendo? A Subcidade 13 se autodestruiu, e nós selamos todo o acesso à superfície a partir de lá.",
  ui_story_5083_50831301_5_dialog_content = "A Subcidade 19 ainda está operacional. Sem pedidos de assistência, então provavelmente eles mantiveram o passo.",
  ui_story_5083_50831301_6_dialog_content = "Todas as subcidades ao longo da linha permanecem operacionais. Nenhuma violação foi relatada.",
  ui_story_5083_50831301_7_dialog_content = "Talvez sejam apenas Eclipsitas soltos vindo pelas montanhas ou surgindo de ruínas subterrâneas como antes.",
  ui_story_5083_50831301_8_dialog_content = "Sim, mas certifique-se de que todos eles sejam exterminados com extremo preconceito, mesmo assim.",
  ui_story_5083_50831301_9_dialog_content = "Envie mais uma equipe para rastrear a fonte.",
  ui_story_5083_50831301_10_dialog_content = "A guerra está intensa agora. A 1ª Legião na defesa do perímetro provavelmente não tem nenhum soldado para poupar.",
  ui_story_5083_50831301_11_dialog_content = "Os Eclipsitas não aparecem do nada. A complacência só nos matará!",
  ui_story_5083_50831301_12_dialog_content = "Se a Legião não puder poupar ninguém, nós cuidaremos disso nós mesmos.",
  ui_story_5083_50831301_13_dialog_content = "Ainda tenho dois batalhões inteiros sob meu comando. Esta será a oportunidade deles para mostrar sua força.",
  ui_story_5083_50831301_14_dialog_content = "Você está certo. Não podemos nos dar ao luxo de perder nada na guerra.",
  ui_story_5083_50831301_15_dialog_content = "Desculpe, mas parece que você esqueceu que eu estou aqui. O Comandante Barton e seus homens devem seguir as atribuições do comitê. Isso é uma prioridade.",
  ui_story_5083_50831301_16_dialog_content = "Estou fazendo um pedido ao Grande Marechal. Isso não tem nada a ver com você.",
  ui_story_5083_50831301_17_dialog_content = "Desculpe-me, mas é meu trabalho entregar a mensagem e relatar tudo de volta ao Comitê - incluindo suas reuniões.",
  ui_story_5083_50831301_18_dialog_content = "Ouça você, somos nós que estamos defendendo Gannon aqui, então acalme-se!",
  ui_story_5083_50831301_19_dialog_content = "Desde que Barton e Dogg ainda têm que fazer propaganda para o Comitê, talvez eles não devam deixar a cidade.",
  ui_story_5083_50831301_20_dialog_content = "Talvez você possa levar este, Pango, com sua equipe e um dos batalhões.",
  ui_story_5083_50831301_21_dialog_content = "Claro, mas não faz sentido que meu segundo em comando morreu em combate enquanto esses dois soldados jovens e perfeitamente bons estão aqui fazendo trabalho braçal!",
  ui_story_5083_50831301_22_dialog_content = "Eu já te dei uma palestra sobre as consequências, Pango.",
  ui_story_5083_50831301_23_dialog_content = "Leve Dogg com você. Eu mesmo aprovei seu pedido de alistamento, então assumirei total responsabilidade.",
  ui_story_5083_50831301_24_dialog_content = "É a minha ordem e você pode me citar, Secretário do Comitê.",
  ui_story_5083_50831301_25_dialog_content = "É o que é. Eu simplesmente não suporto não descobrir de onde os Eclipsitas vêm.",
  ui_story_5083_50831301_26_dialog_content = "Fique atrás e treine os soldados desta vez, Barton.",
  ui_story_5083_50831301_27_dialog_content = "De jeito nenhum, eu tenho um mau pressentimento sobre isso.",
  ui_story_5083_50831301_28_dialog_content = "Como os Escudos Gêmeos, as duas subcidades cumpriram seu propósito, então por que os Eclipsitas estão aparecendo ao redor de Gannon agora?",
  ui_story_5083_50831301_29_dialog_content = "Isso era comum antes, e eles estão mais próximos agora apenas porque a 1ª Legião está muito estendida devido à intensa campanha.",
  ui_story_5083_50831301_30_dialog_content = "Tem certeza de que não é um problema?",
  ui_story_5083_50831301_31_dialog_content = "Eles não me deixam sair de Gannon ou participar de qualquer operação há muito tempo, mas você é enviado para a batalha feroz.",
  ui_story_5083_50831301_32_dialog_content = "Até começo a duvidar do Grande Marechal...",
  ui_story_5083_50831301_33_dialog_content = "Cale a boca! Seu cérebro parou de funcionar por estar enclausurado, e você até esqueceu nosso princípio?",
  ui_story_5083_50831301_34_dialog_content = "Seus olhos estão cheios de raiva e desafio! Eles apagaram todo último fio de honra em você?!",
  ui_story_5083_50831301_35_dialog_content = "Venha aqui, seu punk!",
  ui_story_5083_50831301_36_dialog_content = "Olhe para aquela luz! A Torre Central nunca se apagou. Você cresceu sob essa luz, então você a protege com sua vida!",
  ui_story_5083_50831301_37_dialog_content = "Eu não me importo com quais problemas você tem com os superiores, mas lembre-se disso - você é sempre Illumina.",
  ui_story_5083_50831301_38_dialog_content = "Eu só estava preocupado com você...",
  ui_story_5083_50831301_39_dialog_content = "Então dedique-se à causa e não projete seus problemas pessoais na Illumina.",
  ui_story_5083_50831301_40_dialog_content = "O Grande Marechal pode parecer abalado ou até mesmo fraco, mas ele não é do tipo que trai aliados.",
  ui_story_5083_50831301_41_dialog_content = "Não vou tolerar outro insulto aos nossos soldados vindo de você novamente!",
  ui_story_5083_50831301_42_dialog_content = "Mas pelo menos me leve junto! Eu simplesmente não consigo deixar ir, então me deixe...",
  ui_story_5083_50831301_43_dialog_content = "Esqueça isso, Barton. Tenho certeza de que isso já foi tentado.",
  ui_story_5083_50831301_44_dialog_content = "Não se preocupe, estou com você. Se uma luta acontecer, chamarei reforços imediatamente e pedirei por você pelo nome.",
  ui_story_5083_50831301_45_dialog_content = "Dessa forma, você não pode ser mais contido.",
  ui_story_5083_50831301_46_dialog_content = "...",
  ui_story_5083_50831301_47_dialog_content = "Sou tão bom quanto, então não há razão para não confiar em mim, certo?",
  ui_story_5083_50831301_48_dialog_content = "Espere só, Barton. Eu nunca serei um segundo violino. É melhor você mudar suas maneiras arrogantes.",
  ui_story_5083_50831301_49_dialog_content = "Maldições! Isso está realmente me incomodando, como se algo terrível estivesse prestes a acontecer.",
  ui_story_5083_50831301_50_dialog_content = "Por que estou ficando tão inquieto...",
  ui_story_5083_50831301_51_dialog_content = "Bip—Você recebeu uma nova mensagem, Barton.",
  ui_story_5083_50831301_52_dialog_content = "Remetente desconhecido: \"Reinhardt foi nocauteado tentando salvar pessoas no acidente de laboratório.\"",
  ui_story_5083_50831301_53_dialog_content = "...?",
  ui_story_5083_50831301_54_dialog_content = "\"Desculpe, fiquei confiante demais... não suspeitei de falhas nos dados... □□... Perigo...\"",
  ui_story_5083_50831301_55_dialog_content = "\"Eu assumirei a responsabilidade por isso... enquanto me recupero... □□... Não se preocupe, o negador está com Reinhardt...\"",
  ui_story_5083_50831301_56_dialog_content = "Erro: Escuta detectada. Sinal interrompido.",
  ui_story_5083_50831301_57_dialog_content = "Isso soou como Gronru. Mas por quê, e o que aconteceu?",
  ui_story_5083_50831301_58_dialog_content = "A mensagem tem muitas criptografias para rastrear a origem.",
  ui_story_5083_50831301_59_dialog_content = "Isso é ruim. Está ficando cada vez mais emaranhado para mim.",
  ui_story_5083_50831301_60_dialog_content = "Por que Reinhardt estava envolvido? O que aconteceu com Gronru? E por que a mensagem foi monitorada?",
  ui_story_5083_50831301_61_dialog_content = "O que aconteceu sem eu saber? Droga, isso está me matando...",
  ui_story_5083_50831301_62_dialog_content = "Bip—É recomendado descanso imediato e alívio do estresse, Barton.",
  ui_story_5083_50831301_63_dialog_content = "Não, eu não posso fazer pausas agora!",
  ui_story_5083_50831301_64_dialog_content = "Eu não posso simplesmente ficar parado e não fazer nada.",
  ui_story_5083_50831301_65_dialog_content = "Barton...",
  ui_story_5083_50831301_66_dialog_content = "Eu devo ir e alcançar Dogg e os outros.",
  ui_story_5083_50831301_67_dialog_content = "Mas você não recebeu nenhuma ordem, Barton.",
  ui_story_5083_50831301_68_dialog_content = "Eu não me importo!",
  ui_story_5083_50831301_69_dialog_content = "Até mesmo cometer erros é melhor do que não fazer nada!",
  ui_story_5083_50831301_70_dialog_content = "É tudo por causa dessa luz, velhote! É por causa dela que devemos continuar avançando!",
  ui_story_5083_50831301_71_dialog_content = "Eu não me importo com o que vai acontecer mais! Eu não posso deixar nada de ruim acontecer com nenhum deles!",
  ui_story_5083_50831301_72_dialog_content = "2ª Legião, reúnam-se!",
  ui_story_5083_50831301_73_dialog_content = "Encontramos vestígios de batalha, Comandante Barton. O Comandante provavelmente lutou contra Eclipsitas aqui antes da legião desaparecer.",
  ui_story_5083_50831301_74_dialog_content = "Dada a escala da batalha, provavelmente não são Eclipsitas soltos. Acredito que o Comandante recuou.",
  ui_story_5083_50831301_75_dialog_content = "Rápido, siga os rastros, explore os terrenos e abra caminho para o comboio!",
  ui_story_5083_50831301_76_dialog_content = "Não é tão tarde. Tenho certeza que vamos conseguir...",
  ui_story_5083_50831302_1_dialog_content = "Como é?",
  ui_story_5083_50831302_2_dialog_content = "A comunicação ainda está bloqueada. Isso é estranho porque os Eclipsitas não têm a tecnologia.",
  ui_story_5083_50831302_3_dialog_content = "Acredito que estamos cercados.",
  ui_story_5083_50831302_4_dialog_content = "Qual é o nosso status?",
  ui_story_5083_50831302_5_dialog_content = "Apenas vinte dos duzentos que cobriam a retaguarda sobreviveram. Também perdemos um terço dos nossos comandos.",
  ui_story_5083_50831302_6_dialog_content = "Os Eclipsitas nos superaram em número mais do que esperávamos. Perdemos o controle da situação.",
  ui_story_5083_50831302_7_dialog_content = "Talvez uma subcidade ao longo da linha de defesa tenha sido violada para que isso acontecesse.",
  ui_story_5083_50831302_8_dialog_content = "Ou poderia haver um traidor. De qualquer forma, liderarei uma equipe para romper o cerco e permitir que você saia.",
  ui_story_5083_50831302_9_dialog_content = "Você deve levar as notícias de volta para Gannon para evitar maiores perdas.",
  ui_story_5083_50831302_10_dialog_content = "Não, muitas instalações ainda não foram devidamente recuperadas e o Posto Avançado da 1ª Legião ainda está intacto. Eu não posso simplesmente ir embora.",
  ui_story_5083_50831302_11_dialog_content = "Mas...",
  ui_story_5083_50831302_12_dialog_content = "<color=#e8d9bb>BUM!</color>",
  ui_story_5083_50831302_13_dialog_content = "O que está acontecendo? Estamos sob ataque Eclipsite?",
  ui_story_5083_50831302_14_dialog_content = "Você está bem? Onde está o Comandante Pango?",
  ui_story_5083_50831302_15_dialog_content = "O que você está fazendo aqui, seu pirralho?",
  ui_story_5083_50831302_16_dialog_content = "Fico feliz em ver que você está bem, mas não acho que este seja o momento para me perguntar isso!",
  ui_story_5083_50831302_17_dialog_content = "Você chegou bem na hora. Você viu algum Eclipsita?",
  ui_story_5083_50831302_18_dialog_content = "Minha equipe de mechas rompeu a linha deles. Encontrei batedores da 1ª Legião no caminho e já os informei.",
  ui_story_5083_50831302_19_dialog_content = "Temos instalações que precisamos recuperar. Quantos transportes você pode poupar, Barton? Temos que fazer isso o mais rápido possível!",
  ui_story_5083_50831302_20_dialog_content = "Isso não será um problema. Mas o que está acontecendo aqui? Não consigo receber nenhum sinal.",
  ui_story_5083_50831302_21_dialog_content = "Já tentamos enviar sinais de SOS.",
  ui_story_5083_50831302_22_dialog_content = "Apenas a torre de vigia podia ver os sinais luminosos, e não tenho certeza se eles têm o sinal para retransmiti-lo para Gannon.",
  ui_story_5083_50831302_23_dialog_content = "Está tudo bem. Se você já avisou os batedores, a ajuda deve chegar em breve.",
  ui_story_5083_50831302_24_dialog_content = "Má notícia, os Eclipsitas estão tentando superar nossa barreira com puro número!",
  ui_story_5083_50831302_25_dialog_content = "Também avistamos um <color=#FFB400>Eclipsita gigantesco</color> se aproximando que deve ser dissuadido!",
  ui_story_5083_50831302_26_dialog_content = "<color=#FFB400>Eclipse Gargantuano</color>? O lendário <color=#FFB400>Assédio Eclipsita</color>?",
  ui_story_5083_50831302_27_dialog_content = "Seria difícil matar aquele bastardo sem um poder de fogo sério...",
  ui_story_5083_50831302_28_dialog_content = "Divida a divisão de tanques em duas, uma para cobrir nossa retirada e outra para defender a frente!",
  ui_story_5083_50831302_29_dialog_content = "Obtenha dez transportes com quatro comandos cada para recuperar as instalações de superfície ao redor de Gannon.",
  ui_story_5083_50831302_30_dialog_content = "Entendido!",
  ui_story_5083_50831302_31_dialog_content = "<color=#e8d9bb>O bombardeio sinaliza o início da guerra. No entanto, os ecos de um toque incomum abafam todos os ruídos.</color>",
  ui_story_5083_50831302_32_dialog_content = "Venha cavalgar comigo, Dogg! Vamos nos livrar daquele Eclipsita superdimensionado!",
  ui_story_5083_50831302_33_dialog_content = "Minha unidade ainda tem as torretas resgatadas da Subcidade 19, e essas coisas causam um dano enorme!",
  ui_story_5083_50831302_34_dialog_content = "Não!",
  ui_story_5083_50831302_35_dialog_content = "Vocês dois vão e deixem eu e minha equipe para trás.",
  ui_story_5083_50831302_36_dialog_content = "Este é um ataque planejado, mas nós não somos o alvo... Gannon é.",
  ui_story_5083_50831302_37_dialog_content = "Não é uma operação que apenas vocês dois idiotas podem lidar.",
  ui_story_5083_50831302_38_dialog_content = "Saia agora e notifique Gannon! Quanto antes, melhor!",
  ui_story_5083_50831302_39_dialog_content = "O que você está dizendo? Não podemos te abandonar em um momento como este!",
  ui_story_5083_50831302_40_dialog_content = "Eles eram mais numerosos que nós, mas isso é mais um motivo para ficarmos juntos.",
  ui_story_5083_50831302_41_dialog_content = "Você ouve o <color=#FFB400>tocar</color>? Essa é a Abominação da Zona Escura que obliterou a Subcidade 13.",
  ui_story_5083_50831302_42_dialog_content = "Na Batalha da Zona Cega, aquele sino anunciou nossa derrota.",
  ui_story_5083_50831302_43_dialog_content = "Se você não for agora, nenhum de nós vai sair vivo!",
  ui_story_5083_50831302_44_dialog_content = "Mas...",
  ui_story_5083_50831302_45_dialog_content = "Agora!",
  ui_story_5083_50831302_46_dialog_content = "Não posso te deixar para trás, porque você é mais do que um superior para mim... Pelo menos me deixe ficar com você.",
  ui_story_5083_50831302_47_dialog_content = "Sim, eu sei.",
  ui_story_5083_50831302_48_dialog_content = "Mas nenhuma criança deve partir antes de seus pais.",
  ui_story_5083_50831302_49_dialog_content = "Eu já perdi uma criança, Dogg. Eu não posso me dar ao luxo de perder você também.",
  ui_story_5083_50831302_50_dialog_content = "Ah...",
  ui_story_5083_50831302_51_dialog_content = "Você, velho...",
  ui_story_5083_50831302_52_dialog_content = "Eu... entendo.",
  ui_story_5083_50831302_53_dialog_content = "Saia daqui se você entendeu. Fora da minha vista para que você saia da minha mente!",
  ui_story_5083_50831302_54_dialog_content = "Eu tenho uma batalha para lutar!",
  ui_story_5083_50831302_55_dialog_content = "O que você está fazendo, Dogg?!",
  ui_story_5083_50831302_56_dialog_content = "Leve o Comandante Pango... uh, Pops. Os comandos vão abrir um caminho para você.",
  ui_story_5083_50831302_57_dialog_content = "Este não é o momento para você bancar o herói!",
  ui_story_5083_50831302_58_dialog_content = "Sempre tive inveja de você, Barton...",
  ui_story_5083_50831302_59_dialog_content = "Como uma elite como você, estou sempre um passo atrás, sempre em segundo plano.",
  ui_story_5083_50831302_60_dialog_content = "Não é a hora pra isso, tolo!",
  ui_story_5083_50831302_61_dialog_content = "Deixe-me terminar. Estou sempre com ciúmes porque você é melhor do que eu, pode ir mais longe do que eu e é melhor tratado do que eu...",
  ui_story_5083_50831302_62_dialog_content = "Você sempre avançou, com todos seguindo você voluntariamente...",
  ui_story_5083_50831302_63_dialog_content = "Em você, vejo o poder de conquistar a escuridão digno de uma elite.",
  ui_story_5083_50831302_64_dialog_content = "Você é mais decisivo do que eu, então eu sempre serei o segundo para você.",
  ui_story_5083_50831302_65_dialog_content = "Estou feliz em saber, no entanto, que trabalhei duro o suficiente para estar apenas um degrau abaixo de você.",
  ui_story_5083_50831302_66_dialog_content = "Então, quero adiar os Eclipsitas assim como você, para que você possa chegar em casa.",
  ui_story_5083_50831302_67_dialog_content = "<color=#e8d9bb>Os toques estão se aproximando à medida que os blasters se tornam cada vez mais silenciosos. A linha de defesa recua para dar lugar a uma retirada.</color>",
  ui_story_5083_50831302_68_dialog_content = "Isso apenas significa que mais pessoas serão sacrificadas! Eu tenho que ficar e ajudar!",
  ui_story_5083_50831302_69_dialog_content = "Todo mundo morre às vezes. Não estávamos todos preparados para isso na primeira vez que pegamos uma arma?",
  ui_story_5083_50831302_70_dialog_content = "Mas para o futuro da legião e de Illumina, este não é o lugar para isso, para alguém como você.",
  ui_story_5083_50831302_71_dialog_content = "Deixe-me lhe dar a melhor assistência que você já teve. Faça sua coisa depois que eu abrir uma brecha.",
  ui_story_5083_50831302_72_dialog_content = "O futuro da Illumina depende de você.",
  ui_story_5083_50831302_73_dialog_content = "Pare com esse absurdo. Ainda temos tanques...",
  ui_story_5083_50831302_74_dialog_content = "Lembra da história que eu te contei? Pango sacrificou sua esposa e criança por mim.",
  ui_story_5083_50831302_75_dialog_content = "Estive pensando, quem sou eu para merecer tal honra.",
  ui_story_5083_50831302_76_dialog_content = "Eu tenho vivido com culpa. Muitas vezes, eu estava morto em minha mente.",
  ui_story_5083_50831302_77_dialog_content = "Idiota! Se você não tivesse sobrevivido, quem estaria lá para me empurrar e me fazer ir além?",
  ui_story_5083_50831302_78_dialog_content = "É, eu pude sentir quando você falou comigo sobre o sonho. Isso me moveu até o núcleo.",
  ui_story_5083_50831302_79_dialog_content = "Mesmo querendo retrucar por instinto, eu não o fiz porque sabia que estava disposto a morrer por essa causa.",
  ui_story_5083_50831302_80_dialog_content = "Por favor, nos dê a oportunidade, Barton. Não estamos morrendo por nada, mas pela glória e esperanças de uma Illumina maior.",
  ui_story_5083_50831302_81_dialog_content = "A unidade de tanques conseguiu romper a oposição com sucesso!",
  ui_story_5083_50831302_82_dialog_content = "Mas o gigantesco Eclipsita está tornando impossível para nós recuarmos com segurança!",
  ui_story_5083_50831302_83_dialog_content = "Transmita minha ordem para todos os soldados ficarem para trás e cobrirem nossos companheiros soldados!",
  ui_story_5083_50831302_84_dialog_content = "Informe as unidades mecanizadas para dar-lhes o máximo de munição possível, depois pegamos o resto e recuamos para Gannon!",
  ui_story_5083_50831302_85_dialog_content = "Barton, você é meu irmão, meu inimigo, meu pesadelo, o motivo de eu ser um segundo violino.",
  ui_story_5083_50831302_86_dialog_content = "E eu sou o motivo pelo qual você é o melhor!",
  ui_story_5083_50831302_87_dialog_content = "Pegue isso e vá.",
  ui_story_5083_50831302_88_dialog_content = "Você fique vivo até eu trazer reforços!",
  ui_story_5083_50831302_89_dialog_content = "Saia do meu caminho, insignificantes insetos de Illumina!",
  ui_story_5083_50831302_90_dialog_content = "Camaradas, é para isso que os comandos foram feitos! Vamos lutar um pelo outro! <size=45>Ataque!</size>",
  ui_story_5083_50831302_91_dialog_content = "<color=#e8d9bb>Dogg bradou o canto de guerra no topo de seus pulmões e avançou. Todos os comandos seguiram e atacaram a horda.</color>",
  ui_story_5083_50831302_92_dialog_content = "<size=45>Vá para o inferno.</size>",
  ui_story_5083_50831302_93_dialog_content = "Voe forte e com determinação, não pare até que o sonho se torne realidade!",
  ui_story_5083_50831302_94_dialog_content = "Vá, Barton... Avance sempre em direção a um futuro brilhante...",
  ui_story_5083_50831400_1_dialog_content = "<color=#e8d9bb>Os batedores da 1ª Legião trouxeram notícias de que todos os comandos foram mortos em ação. Eles repeliram o exército Darkover ao custo de suas vidas.</color>",
  ui_story_5083_50831400_2_dialog_content = "<color=#e8d9bb>Os alarmes soaram por todo Gannon quando a mobilização total foi declarada. Todos estavam a postos contra os Eclipsitas iminentes.</color>",
  ui_story_5083_50831400_3_dialog_content = "É tarde demais para fazer as pazes. Um batalhão inteiro sacrificado por nada!",
  ui_story_5083_50831400_4_dialog_content = "Esta é uma reunião classificada, Coronel Barton. Por favor, não prossiga mais.",
  ui_story_5083_50831400_5_dialog_content = "A Grande Marechal ainda está formulando um plano. Pare de interferir ou enfrentará as consequências.",
  ui_story_5083_50831400_6_dialog_content = "Atire, eu te desafio.",
  ui_story_5083_50831400_7_dialog_content = "Por favor, recue, Coronel Barton!",
  ui_story_5083_50831400_8_dialog_content = "Se você não tem coragem de puxar o gatilho, não aponte essa coisa para mim.",
  ui_story_5083_50831400_9_dialog_content = "Por que você está gritando sobre isso desta vez, pirralho?!",
  ui_story_5083_50831400_10_dialog_content = "Volte aqui antes que você se envergonhe na frente do Grande Marechal!",
  ui_story_5083_50831400_11_dialog_content = "Você está consciente, senhor...",
  ui_story_5083_50831400_12_dialog_content = "Saudações, Grande Marechal!",
  ui_story_5083_50831400_13_dialog_content = "...",
  ui_story_5083_50831400_14_dialog_content = "Ei, pare de me segurar! Eu quero respostas dele!",
  ui_story_5083_50831400_15_dialog_content = "Por que você se recusou a enviar até mesmo apenas dois batalhões? Por que não implantou a unidade mecanizada em primeiro lugar?",
  ui_story_5083_50831400_16_dialog_content = "Eles não estariam presos se tivessem transporte...",
  ui_story_5083_50831400_17_dialog_content = "Acalmar!",
  ui_story_5083_50831400_18_dialog_content = "Dogg e todos os outros, eles estão mortos. Como posso ficar calmo!",
  ui_story_5083_50831400_19_dialog_content = "Você confiou nas pessoas erradas! Esses caras não têm estratégias além de subterfúgios para falar, é por isso que Dogg e outros morreram em vão!",
  ui_story_5083_50831400_20_dialog_content = "Eles estão nos visando... mas por que eles simplesmente não vêm até mim?",
  ui_story_5083_50831400_21_dialog_content = "Droga, por que eles não vêm até mim!",
  ui_story_5083_50831400_22_dialog_content = "Pare antes que você envergonhe a 2ª Legião também. Como Dogg se sentiria sobre isso?",
  ui_story_5083_50831400_23_dialog_content = "Esta é a segunda vez que você deixa Gannon com a unidade mecanizada! Você tem sorte que o Grande Marechal não caiu em cima de você!",
  ui_story_5083_50831400_24_dialog_content = "Ele é responsável pela morte do Dogg!",
  ui_story_5083_50831400_25_dialog_content = "É óbvio que ele é o culpado...",
  ui_story_5083_50831400_26_dialog_content = "Dogg é o único filho do Grande Marechal.",
  ui_story_5083_50831400_27_dialog_content = "Pare de me vender mentiras, velhote!",
  ui_story_5083_50831400_28_dialog_content = "Me siga.",
  ui_story_5083_50831400_29_dialog_content = "Roog e eu somos velhos companheiros de guerra. Pouco antes de ele ser nomeado Grande Marechal, sua esposa grávida ficou presa em uma cidade subterrânea.",
  ui_story_5083_50831400_30_dialog_content = "Liderei um exército de resgate, mas era tarde demais. A Cidade Baixa caiu. Nos registros, não havia sobreviventes.",
  ui_story_5083_50831400_31_dialog_content = "Mas quando encontrei o corpo de sua esposa, notei Dogg deitado nos braços de sua mãe. Ele estava quieto e nunca chorou.",
  ui_story_5083_50831400_32_dialog_content = "Não faço ideia de como ela conseguiu dar à luz a uma criança em um ambiente tão adverso e ajudou-o a sobreviver... É um milagre.",
  ui_story_5083_50831400_33_dialog_content = "Ainda me lembro de como Roog estava triste quando eu trouxe Dogg de volta. Ele amava muito sua esposa, mas tinha que cumprir seu dever como soldado.",
  ui_story_5083_50831400_34_dialog_content = "Ninguém sabia sobre aquela criança, então ele confiou o garoto a mim. Havia algo em sua mente naquele momento e ele queria se concentrar na guerra.",
  ui_story_5083_50831400_35_dialog_content = "Impossível...",
  ui_story_5083_50831400_36_dialog_content = "Esse é o fato. A Subcidade que eu estava defendendo foi invadida seis anos atrás. O Comitê descobriu a verdadeira história de Dogg quando passaram pelo procedimento usual.",
  ui_story_5083_50831400_37_dialog_content = "Não sei se isso teve algo a ver com isso, mas Roog se tornou indeciso e se afastou de mim depois disso.",
  ui_story_5083_50831400_38_dialog_content = "Como Grande Marechal, mesmo que ele se tornasse cada vez mais forte, ele agia de maneira cada vez mais conservadora.",
  ui_story_5083_50831400_39_dialog_content = "Não entendo, mas apostaria minha vida que ele tem o melhor interesse de Illumina no coração.",
  ui_story_5083_50831400_40_dialog_content = "Mesmo que sua mira possa estar um pouco desviada, ele nunca machucaria seu próprio filho.",
  ui_story_5083_50831400_41_dialog_content = "Você contou para aquele tolo quem é o pai dele?",
  ui_story_5083_50831400_42_dialog_content = "De nada.",
  ui_story_5083_50831400_43_dialog_content = "His sacrificed his wife to evacuate me and the other noncombatants.",
  ui_story_5083_50831400_44_dialog_content = "Estive pensando, quem sou eu para merecer tal honra.",
  ui_story_5083_50831400_45_dialog_content = "Esse tolo tem carregado a culpa de quem ele realmente é consigo todos esses anos...",
  ui_story_5083_50831400_46_dialog_content = "Então, me arrependo muito de ter contado a ele.",
  ui_story_5083_50831400_47_dialog_content = "...",
  ui_story_5083_50831400_48_dialog_content = "Rápido, pegue o máximo que puder e encha todos os sacos de areia... Pare, você aí. Este é o esquadrão da 1ª Legião indo para a frente!",
  ui_story_5083_50831400_49_dialog_content = "Reinhardt?",
  ui_story_5083_50831400_50_dialog_content = "Você recebeu alta do hospital, pelo que vejo.",
  ui_story_5083_50831400_51_dialog_content = "Isso foi há muito tempo. O que você está fazendo por aqui quando a Illumina está enfrentando uma crise?",
  ui_story_5083_50831400_52_dialog_content = "Os veículos estão carregados, Coronel Reinhardt. Vamos partir agora.",
  ui_story_5083_50831400_53_dialog_content = "Tenha uma viagem segura!",
  ui_story_5083_50831400_54_dialog_content = "Hmm, pessoas insuficientes. Isso só pode significar problemas para o comandante...",
  ui_story_5083_50831400_55_dialog_content = "Você parece um pouco diferente para mim...",
  ui_story_5083_50831400_56_dialog_content = "Eu faço? Estou ocupado com a mobilização, então não tenho tempo para bate-papo.",
  ui_story_5083_50831400_57_dialog_content = "Ei, espere um minuto, Reinhardt...",
  ui_story_5083_50831400_58_dialog_content = "Você ainda se lembra do que conversamos antes?",
  ui_story_5083_50831400_59_dialog_content = "O que o Comitê fez com você?",
  ui_story_5083_50831400_60_dialog_content = "Você quer dizer me promover a coronel?",
  ui_story_5083_50831400_61_dialog_content = "Não! Por que você...",
  ui_story_5083_50831400_62_dialog_content = "Eu sei o que você quer dizer. Quanto ao Comitê, tenho que aguentar por enquanto. A guerra é a verdadeira preocupação.",
  ui_story_5083_50831400_63_dialog_content = "Tenho que relatar ao comandante. Você provavelmente está um pouco confuso, mas espero que se anime. Afinal, você é um herói de Illumina.",
  ui_story_5083_50831400_64_dialog_content = "Heh, \"Herói de Illumina\"? Que título deveriam ser chamados Dogg e os outros que não voltarão, então?",
  ui_story_5083_50831400_65_dialog_content = "O Comitê não tem o direito de decidir quem é o herói e quem não é!",
  ui_story_5083_50831400_66_dialog_content = "Reinhardt...",
  ui_story_5083_50831400_67_dialog_content = "Bip—Por favor, siga-me, Barton.",
  ui_story_5083_50831400_68_dialog_content = "Bem, pelo menos você não mudou nem um pouco, meu... navegador.",
  ui_story_5083_50831400_69_dialog_content = "Vamos. Onde quer que você esteja me levando, não pode ser pior do que isso.",
  ui_story_5083_50831400_70_dialog_content = "O monumento... O nome do Dogg foi adicionado?",
  ui_story_5083_50831400_71_dialog_content = "Bip—Olhe, Barton.",
  ui_story_5083_50831400_72_dialog_content = "<color=#e8d9bb>Sob o imponente memorial, uma figura curvada olhava para os nomes sem qualquer expressão.</color>",
  ui_story_5083_50831400_73_dialog_content = "É a Grande Marechal.",
  ui_story_5083_50831400_74_dialog_content = "O verdadeiro <color=#FFB400>pai</color> do Dogg...",
  ui_story_5083_50831400_75_dialog_content = "<color=#e8d9bb>Barton pausou. Ele queria ir adiante, mas mudou de ideia e permaneceu onde estava.</color>",
  ui_story_5083_50831400_76_dialog_content = "Cachorrinho...",
  ui_story_5083_50831400_77_dialog_content = "<color=#e8d9bb>O homem esgotado na distância derramou uma lágrima silenciosa. Ele não era um Grande Marechal, mas um pai de coração partido.</color>",
  ui_story_5083_50831400_78_dialog_content = "<color=#e8d9bb>Ele finalmente partiu com passos pesados para ceder o caminho a Barton.</color>",
  ui_story_5083_50831400_79_dialog_content = "O nome de cada soldado foi adicionado. Este é o último lugar de descanso para todas as crianças da Illumina.",
  ui_story_5083_50831400_80_dialog_content = "Beep—Barton...",
  ui_story_5083_50831400_81_dialog_content = "Em quem posso confiar além de você agora? Todos têm um segredo, com camadas infinitas também...",
  ui_story_5083_50831400_82_dialog_content = "Mesmo que a Grande Marechal e os outros sejam inocentes, como posso confiar neles...?",
  ui_story_5083_50831400_83_dialog_content = "Dê uma olhada, Barton.",
  ui_story_5083_50831400_84_dialog_content = "É essa uma foto de todos nós juntos?",
  ui_story_5083_50831400_85_dialog_content = "Você tirou essa foto para nós? Obrigado.",
  ui_story_5083_50831400_86_dialog_content = "Dogg se foi, Reinhardt não é o mesmo, e quem sabe para onde o resto foi.",
  ui_story_5083_50831400_87_dialog_content = "Todos nesta foto se espalharam...",
  ui_story_5083_50831400_88_dialog_content = "Mas eu tenho que carregar o peso e seguir em frente, certo?",
  ui_story_5083_50831400_89_dialog_content = "Mesmo que eu seja o único restante, ainda assim assumirei o leme.",
  ui_story_5083_50831500_1_dialog_content = "<color=#e8d9bb>À medida que a batalha por Gannon se intensificava, o Comitê finalmente cedeu para Barton levar um exército reabastecido de volta à linha de frente.</color>",
  ui_story_5083_50831500_2_dialog_content = "<color=#e8d9bb>No entanto, a situação não melhorou com o Darkover ameaçando as fronteiras de Gannon. Para evitar um cerco, o Grande Marechal ordenou uma evacuação.</color>",
  ui_story_5083_50831500_3_dialog_content = "Comandante Barton, o Darkover recuou. Qual é a sua ordem?",
  ui_story_5083_50831500_4_dialog_content = "Empurre a linha de defesa, mas devagar. Não, esqueça isso. Sem movimentos arriscados. Estamos em uma posição melhor para transportes logísticos agora.",
  ui_story_5083_50831500_5_dialog_content = "As unidades de tanque estão solicitando um contra-ataque, Comandante Barton.",
  ui_story_5083_50831500_6_dialog_content = "Absolutamente não! Pare de pensar em matar o inimigo quando estamos lutando uma batalha defensiva! Só precisamos afastá-los.",
  ui_story_5083_50831500_7_dialog_content = "Mas a 1ª Legião ainda está envolvida em uma luta amarga... Não deveríamos ajudar?",
  ui_story_5083_50831500_8_dialog_content = "Não podemos fazer nada quanto a isso. Podemos correr qualquer risco. Não posso deixar você sair às cegas...",
  ui_story_5083_50831500_9_dialog_content = "O que você está fazendo preso aqui como uma tartaruga? Há muitos Eclipsitas lá fora para você perseguir!",
  ui_story_5083_50831500_10_dialog_content = "Mas alguém vai morrer...",
  ui_story_5083_50831500_11_dialog_content = "Como você pode lutar uma guerra sem que ninguém morra? O que é importante é pelo que você está lutando!",
  ui_story_5083_50831500_12_dialog_content = "Você não sabia melhor antes, pirralho? Não fique mole comigo agora!",
  ui_story_5083_50831500_13_dialog_content = "Eu não vejo mais a luz...",
  ui_story_5083_50831500_14_dialog_content = "?!",
  ui_story_5083_50831500_15_dialog_content = "Com a sempre crescente Torre Central à frente, tenho avançado em direção à Illumina.",
  ui_story_5083_50831500_16_dialog_content = "Cresci perseguindo-o, tentando alcançá-lo... Mas não o vejo agora.",
  ui_story_5083_50831500_17_dialog_content = "Não consigo encontrar uma razão para os meus soldados lutarem por mim. Não quero que eles morram por causa das minhas ordens.",
  ui_story_5083_50831500_18_dialog_content = "Eu sei que deveria estar liderando eles, mas eu nem consigo encontrar meu próprio equilíbrio agora...",
  ui_story_5083_50831500_19_dialog_content = "Quando você também ficou tão indeciso, pirralho?",
  ui_story_5083_50831500_20_dialog_content = "Você toma decisões e dá ordens com base no relatório que recebeu para cumprir objetivos. Isso não é suficiente?",
  ui_story_5083_50831500_21_dialog_content = "Os soldados Illumina não são burros. Eles sabem pelo que estão lutando!",
  ui_story_5083_50831500_22_dialog_content = "Mesmo que eles não consigam explicar bem, apenas pergunte, e cada um deles lhe dirá a causa pela qual eles morreriam!",
  ui_story_5083_50831500_23_dialog_content = "Saia do quartel-general agora e entre nas trincheiras! Você verá a direção que a determinação deles está indicando para você seguir!",
  ui_story_5083_50831500_24_dialog_content = "Cada um dos nossos soldados de Illumina cresceu sob a luz. Como você poderia esquecer disso?",
  ui_story_5083_50831500_25_dialog_content = "Eles cresceram sob a luz...",
  ui_story_5083_50831500_26_dialog_content = "Elabore um plano melhor se achar que as baixas serão altas! Mas nunca abandone seus homens!",
  ui_story_5083_50831500_27_dialog_content = "Reclamar sozinho não resolve nada! É assim que você retribui o sacrifício dos mortos?",
  ui_story_5083_50831500_28_dialog_content = "Os soldados ainda te seguiriam se te vissem assim?",
  ui_story_5083_50831500_29_dialog_content = "Você ainda não tem muitas pessoas que confiam em você? Por que está tão desanimado consigo mesmo?!",
  ui_story_5083_50831500_30_dialog_content = "O que te fez pensar que você tem o direito de falar por todos? Você não é o único herói por aqui! Dê a eles uma chance!",
  ui_story_5083_50831500_31_dialog_content = "Você está certo. Eu estava fraco e confuso.",
  ui_story_5083_50831500_32_dialog_content = "Não há futuro se você ficar parado, e não há recompensa sem risco!",
  ui_story_5083_50831500_33_dialog_content = "Todos querem servir à luz. Como eles ainda estão com você, você precisa garantir que o brilho não esteja embaçado.",
  ui_story_5083_50831500_34_dialog_content = "Você pode comandar os soldados, mas eles escolheram você para liderá-los.",
  ui_story_5083_50831500_35_dialog_content = "Lembre-se disso, Barton, você encontrará o que quer que esteja por trás do chamado ao dever no campo de batalha.",
  ui_story_5083_50831500_36_dialog_content = "Se você não sabe em quem confiar, confie em seus companheiros. Não importa que tipo de líder você se torne, eles seguirão.",
  ui_story_5083_50831500_37_dialog_content = "A 1ª Legião poderia segurar a linha! O gigantesco Eclipsita rasgou uma abertura para sua espécie invadir o Elevador Gannon!",
  ui_story_5083_50831500_38_dialog_content = "A Grande Marechal deu a ordem para <color=#FFB400>abandonar a cidade</color>!",
  ui_story_5083_50831500_39_dialog_content = "O quê? Abandonar nossa casa?",
  ui_story_5083_50831500_40_dialog_content = "Ele está louco? Este é o coração de Illumina e nosso lar! É suposto ser o farol que nunca se apaga!",
  ui_story_5083_50831500_41_dialog_content = "Peço desculpas, mas essa é a ordem. A Grande Marechal gostaria que algumas tropas ficassem e cobrissem a evacuação dos civis.",
  ui_story_5083_50831500_42_dialog_content = "Então, as outras tropas voltarão, reforçarão e cercarão o Darkover.",
  ui_story_5083_50831500_43_dialog_content = "Passe minha ordem. Todos os funcionários, recuem! A 2ª Legião cobrirá a retirada!",
  ui_story_5083_50831500_44_dialog_content = "Vamos escolher uma luta, senhor!",
  ui_story_5083_50831500_45_dialog_content = "<color=#e8d9bb>A 2ª Legião virou-se e correu em direção a Gannon contra a multidão em fuga.</color>",
  ui_story_5083_50831500_46_dialog_content = "<color=#e8d9bb>O que se seguiu foram dias de batalha sem parar. A legião sofreu grandes perdas, mas defendeu o elevador com valentia.</color>",
  ui_story_5083_50831500_47_dialog_content = "<color=#e8d9bb>No final, no entanto, inúmeros Eclipsitas conseguiram penetrar na instalação—</color><color=#FFB400>Gannon caiu, oficialmente.</color>",
  ui_story_5083_50831500_48_dialog_content = "O último grupo de pessoal partiu. Agora é a sua vez de ir, Barton.",
  ui_story_5083_50831500_49_dialog_content = "Nossos transportadores sofreram danos demais para evacuar todos.",
  ui_story_5083_50831500_50_dialog_content = "Lá vai você de novo, velhote.",
  ui_story_5083_50831500_51_dialog_content = "Estou levando pessoas para lá. Todos são veteranos, ao contrário dos novatos que você tem.",
  ui_story_5083_50831500_52_dialog_content = "Sobre o que você está falando? É uma causa perdida...",
  ui_story_5083_50831500_53_dialog_content = "Vou defender a Torre Central não importa o que aconteça! Preservar o centro de energia é preservar o coração de Gannon!",
  ui_story_5083_50831500_54_dialog_content = "Se for destruída como a Subcidade 13 foi, a luz se apagará em Gannon e nenhum habitante de Illumina poderá encontrar seu propósito.",
  ui_story_5083_50831500_55_dialog_content = "Não posso permitir que isso aconteça com aqueles que ainda estão lutando duro!",
  ui_story_5083_50831500_56_dialog_content = "Então me leve com você!",
  ui_story_5083_50831500_57_dialog_content = "Estou feliz que você não é melodramático como Dogg, Barton. Não vou repetir nada sentimental duas vezes.",
  ui_story_5083_50831500_58_dialog_content = "Sempre acreditei em você, minha elite pessoalmente aprimorada.",
  ui_story_5083_50831500_59_dialog_content = "Então esta é a aula final.",
  ui_story_5083_50831500_60_dialog_content = "Quando necessário, até mesmo um general deve abrir caminho para a geração futura!",
  ui_story_5083_50831500_61_dialog_content = "Eu sei que você será o melhor líder para a 2ª Legião, Barton. Está em suas mãos. Agora saia daqui!",
  ui_story_5083_50831500_62_dialog_content = "Você não pode me fazer ir embora, Comandante Pango. Não me faça nocautear você também.",
  ui_story_5083_50831500_63_dialog_content = "Guardas, levem-no para o transportador de evacuação... mesmo que isso signifique quebrar as pernas dele!",
  ui_story_5083_50831500_64_dialog_content = "O que? Me solta!",
  ui_story_5083_50831500_65_dialog_content = "Você não pode fazer isso comigo, velhote!",
  ui_story_5083_50831500_66_dialog_content = "Adeus, minha criança problemática...",
  ui_story_5083_50831601_1_dialog_content = "Desculpe, vocês vão ter que ficar por aqui, pessoal.",
  ui_story_5083_50831601_2_dialog_content = "Major, quero que seus homens abram um caminho até a fonte de energia para nós a todo custo. Você pode fazer isso?",
  ui_story_5083_50831601_3_dialog_content = "Sim, senhor!",
  ui_story_5083_50831601_4_dialog_content = "Quais são as perdas estimadas para você?",
  ui_story_5083_50831601_5_dialog_content = "Todos nós vamos perecer, senhor!",
  ui_story_5083_50831601_6_dialog_content = "...",
  ui_story_5083_50831601_7_dialog_content = "Mas faremos isso, senhor!",
  ui_story_5083_50831601_8_dialog_content = "Certo... Quando chegarmos lá, seguirei suas ordens!",
  ui_story_5083_50831601_9_dialog_content = "Olá, senhor!",
  ui_story_5083_50831601_10_dialog_content = "Primeiro Batalhão, prepare-se para contra-atacar!",
  ui_story_5083_50831601_11_dialog_content = "Não tenha medo. Só temos que aguentar até o amanhecer. O Grande Marechal voltará para nós assim que tiver lidado com seus Eclipsitas.",
  ui_story_5083_50831601_12_dialog_content = "Ainda tenho um Lumâmbar, bom o suficiente para enviar um SOS.",
  ui_story_5083_50831601_13_dialog_content = "O resto cabe a nós, só precisamos aguentar até o amanhecer.",
  ui_story_5083_50831601_14_dialog_content = "Então este é o fim? Nós fugindo enquanto Gannon queima?",
  ui_story_5083_50831601_15_dialog_content = "Beep—Barton...",
  ui_story_5083_50831601_16_dialog_content = "Emboscada! Emboscada!",
  ui_story_5083_50831601_17_dialog_content = "O quê? Deixe-me lutar...",
  ui_story_5083_50831601_18_dialog_content = "Acorda, Barton.",
  ui_story_5083_50831601_19_dialog_content = "O que está acontecendo...?",
  ui_story_5083_50831601_20_dialog_content = "O comboio está sob ataque. Levante e lute.",
  ui_story_5083_50831601_21_dialog_content = "<size=45>Droga!</size>",
  ui_story_5083_50831601_22_dialog_content = "Minhas mãos podem estar amarradas, mas estou de mau humor, então não me irrite!",
  ui_story_5083_50831601_23_dialog_content = "*Rugido*",
  ui_story_5083_50831601_24_dialog_content = "Socou minha mandíbula de novo.",
  ui_story_5083_50831601_25_dialog_content = "Maldições... Alguém tire essas algemas de mim!",
  ui_story_5083_50831601_26_dialog_content = "Espere um minuto... Fui atingido no maxilar e não doeu nada?",
  ui_story_5083_50831601_27_dialog_content = "Não fique aí parado, continue lutando!",
  ui_story_5083_50831601_28_dialog_content = "Só por cima do meu cadáver!",
  ui_story_5083_50831601_29_dialog_content = "Deve ser um sonho. Eu não tinha uma mandíbula de ferro quando era jovem.",
  ui_story_5083_50831601_30_dialog_content = "Entendi agora... Esse é o pesadelo no qual eu estava preso.",
  ui_story_5083_50831601_31_dialog_content = "Beep—Você finalmente se lembrou, Barton?",
  ui_story_5083_50831601_32_dialog_content = "O que é que está te prendendo?",
  ui_story_5083_50831601_33_dialog_content = "Perdi meu caminho... Mas sempre acreditei que, enquanto eu continuasse lutando, a luz brilharia diante de mim.",
  ui_story_5083_50831601_34_dialog_content = "Ainda assim, você está preso aqui.",
  ui_story_5083_50831601_35_dialog_content = "Eu não sei. Eu não me lembro de nada... Eu não acho que fugi, mas não me lembro do que fiz depois disso...",
  ui_story_5083_50831601_36_dialog_content = "Eu só me lembro do comandante naquela batalha...",
  ui_story_5083_50831601_37_dialog_content = "Então eu estava no confronto final, lutando com tudo que tinha, mas fui gravemente ferido, e foi assim que acabei com a \"mandíbula de ferro\".",
  ui_story_5083_50831601_38_dialog_content = "Muitos dos soldados não entenderam isso e me viram como um covarde que abandonou seu comandante. Eu era um estranho para eles.",
  ui_story_5083_50831601_39_dialog_content = "Eu queria lutar até a morte ao lado do Comandante Pango... Esqueça, não me importo se foi apenas um sonho.",
  ui_story_5083_50831601_40_dialog_content = "Pesadelos não me afetam. Sempre tem a próxima vez! Não importa quantas tentativas, eu vou mudar isso...",
  ui_story_5083_50831601_41_dialog_content = "Aceite o resultado e espere até a próxima vez.. É assim que você se perdoa, Barton?",
  ui_story_5083_50831601_42_dialog_content = "Se você pode deixar para trás, por que sempre volta aqui?",
  ui_story_5083_50831601_43_dialog_content = "Você sabe quantas vezes já passou por isso? E quantos \"próximas vezes\" você teve?",
  ui_story_5083_50831601_44_dialog_content = "Mas por que...",
  ui_story_5083_50831601_45_dialog_content = "Quando será a \"próxima vez\"?",
  ui_story_5083_50831601_46_dialog_content = "Quem é você?",
  ui_story_5083_50831601_47_dialog_content = "Ficou claro para você desde o início. Sempre serei seu navegador, Barton.",
  ui_story_5083_50831601_48_dialog_content = "Para mim, que posso ver a luz, mas não tocá-la, esse caminho esteve sob seus pés o tempo todo desde que eu te conheci.",
  ui_story_5083_50831601_49_dialog_content = "Espere, quer dizer que você é...",
  ui_story_5083_50831601_50_dialog_content = "Temos que ir, Coronel Barton.",
  ui_story_5083_50831601_51_dialog_content = "Para onde podemos ir? Cidade Baixa 19?",
  ui_story_5083_50831601_52_dialog_content = "Gannon caiu... Será que algum dia o recuperaremos?",
  ui_story_5083_50831601_53_dialog_content = "<size=45>Damn it!</size>",
  ui_story_5083_50831601_54_dialog_content = "<color=#e8d9bb>Com um grito, Barton quebra a algema.</color>",
  ui_story_5083_50831601_55_dialog_content = "Isso mesmo, eu sou a ovelha negra, um \"elite\" desafiador!",
  ui_story_5083_50831601_56_dialog_content = "Por que eu deveria tolerar isso?",
  ui_story_5083_50831601_57_dialog_content = "Estou iniciando uma revolução e a hora é agora!",
  ui_story_5083_50831601_58_dialog_content = "Todos vocês na 2ª Legião!",
  ui_story_5083_50831601_59_dialog_content = "Coronel Barton? Nossa missão é levá-lo em segurança. Por favor, não nos dificulte.",
  ui_story_5083_50831601_60_dialog_content = "Não, não temos segurança alguma para falar!",
  ui_story_5083_50831601_61_dialog_content = "Em um Astra devastado pelos Eclipsitas, só há um lar para o qual podemos voltar.",
  ui_story_5083_50831601_62_dialog_content = "Todos vocês treinaram lá, então você deve ainda se lembrar de como aquela luz é brilhante!",
  ui_story_5083_50831601_63_dialog_content = "Não nascemos para vagar! Para onde podemos voltar se não formos para Gannon?",
  ui_story_5083_50831601_64_dialog_content = "Nosso superior está lutando por sua vida e ele precisa de ajuda! Você ouviu o clarim? Gannon está nos chamando!",
  ui_story_5083_50831601_65_dialog_content = "Se estamos destinados a morrer em batalha, quero morrer com todos vocês sob meu comando, morrer na luta por Gannon!",
  ui_story_5083_50831601_66_dialog_content = "Eu vou te levar para casa. Mesmo que acabe com apenas seus nomes em uma placa...",
  ui_story_5083_50831601_67_dialog_content = "Enquanto a luz do farol permanecer, aqueles que nos seguem terão a vontade de seguir em frente!",
  ui_story_5083_50831601_68_dialog_content = "Estou disposto a seguir você, Coronel Barton. A ordem do Grande Marechal era para defendermos Gannon. Nunca iremos desobedecê-la.",
  ui_story_5083_50831601_69_dialog_content = "Eu também! Eu tenho seguido o Barton desde o início. Eu acredito naquele mesmo Barton que avançou conosco.",
  ui_story_5083_50831601_70_dialog_content = "Meus líderes de pelotão e recrutas companheiros morreram me protegendo. Não me importo de me sacrificar para proteger Gannon.",
  ui_story_5083_50831601_71_dialog_content = "Conte comigo. Qualquer um que queira chegar ao Coronel Barton terá que passar por nós primeiro.",
  ui_story_5083_50831601_72_dialog_content = "Vocês...",
  ui_story_5083_50831601_73_dialog_content = "É madrugada, Barton.",
  ui_story_5083_50831601_74_dialog_content = "Sim, eu vejo o caminho... Todas as suas luzes apontaram o caminho para mim.",
  ui_story_5083_50831601_75_dialog_content = "Companhia, meia volta! Vamos acabar com esta noite... Vamos retomar Gannon!",
  ui_story_5083_50831601_76_dialog_content = "<color=#e8d9bb>Então os soldados se viraram e marcharam em direção a Gannon.</color>",
  ui_story_5083_50831601_77_dialog_content = "<color=#e8d9bb>Todos perceberam que iriam morrer lá, mas ninguém diminuiu o ritmo.</color>",
  ui_story_5083_50831601_78_dialog_content = "<color=#e8d9bb>Sem o brilho deles, não haveria alvorecer em Astra.</color>",
  ui_story_5083_50831601_79_dialog_content = "<color=#e8d9bb>A Crise Darkover que atormentou a terra por oito anos pode ter acabado por causa dos resistentes que vieram antes. Como seus sucessores, é meu dever continuar até o fim.</color>",
  ui_story_5083_50831601_80_dialog_content = "Seus homens estão dizimados, insignificante Aurorian. Todas as vidas perecerão diante de mim, o <color=#FFB400>Sino do Juízo Final</color>.",
  ui_story_5083_50831601_81_dialog_content = "Cuspir!",
  ui_story_5083_50831601_82_dialog_content = "<color=#e8d9bb>O inimigo colossal se aproximou da Torre Central. Cobrindo sua pele de pedra pulsante com chamas estava uma colagem de pedaços de metal feios para armadura.</color>",
  ui_story_5083_50831601_83_dialog_content = "<color=#e8d9bb>Qualquer um examinando os selos nos fragmentos poderia reconhecer que eles vieram de diferentes subcidades. Eles representavam as vitórias do monstro como crachás de honra.</color>",
  ui_story_5083_50831601_84_dialog_content = "<color=#e8d9bb>Foi assustadoramente desconfortável e irritante ao mesmo tempo.</color>",
  ui_story_5083_50831601_85_dialog_content = "<color=#e8d9bb>Enquanto avançava pesadamente, os fragmentos se chocavam em estrondos abafados como se estivessem tocando um Requiem rancoroso.</color>",
  ui_story_5083_50831601_86_dialog_content = "Ah, você está tremendo, Tiny One. Sim, eu posso sentir o seu medo. Até a bandeira em sua mão está vacilando.",
  ui_story_5083_50831601_87_dialog_content = "Todos os parasitas são iguais. Todos temem o forte. Isso é instinto deles. Ajoelhem-se para que eu possa esmagá-los com prazer.",
  ui_story_5083_50831601_88_dialog_content = "Sim, estou tremendo... Não pensei que ficaria tão assustado na minha idade.",
  ui_story_5083_50831601_89_dialog_content = "Talvez seja instinto, como você disse.",
  ui_story_5083_50831601_90_dialog_content = "Então você admite? Então ajoelhe-se e peça por misericórdia! Este é o meu maior prazer.",
  ui_story_5083_50831601_91_dialog_content = "Você está brincando, seu bobo feio? Você acha que está enfrentando um bando de covardes?",
  ui_story_5083_50831601_92_dialog_content = "Você não faz ideia do quão diferente você é de nós!",
  ui_story_5083_50831601_93_dialog_content = "Não haverá alegria para você. Tudo o que você verá é o quão inquebrável é a espinha dorsal do povo Illumina!",
  ui_story_5083_50831601_94_dialog_content = "Os aurorianos têm medo, mas os eclipsitas também, e você nunca aprenderá a lidar com isso como nós fazemos.",
  ui_story_5083_50831601_95_dialog_content = "Eu digo não... Sem chance de você cruzar nossa linha!",
  ui_story_5083_50831601_96_dialog_content = "Então vou colocar isso à prova.",
  ui_story_5083_50831601_97_dialog_content = "Desculpe, senhor, isso é o melhor que podemos fazer... Por que a ajuda ainda não chegou...?",
  ui_story_5083_50831601_98_dialog_content = "Vejo que é hora de enganar seus soldados. Vá em frente, mostre o Lumâmbar e diga a eles que a ajuda está a caminho.",
  ui_story_5083_50831601_99_dialog_content = "Essa é a mentira que todo oficial contou em cada Subcidade que eu destruí...",
  ui_story_5083_50831601_100_dialog_content = "Nenhuma ajuda veio mesmo quando eu tirei o último suspiro deles. É a hipocrisia mais ridícula para a Illumina.",
  ui_story_5083_50831601_101_dialog_content = "Peço desculpas, meus camaradas. Vocês confiaram suas vidas a mim, mas eu não pude prometer nada em troca.",
  ui_story_5083_50831601_102_dialog_content = "Mas por favor acredite em mim quando digo que a Illumina nunca abandonaria seus defensores!",
  ui_story_5083_50831601_103_dialog_content = "<color=#e8d9bb>Pango liberou o Lumâmbar e puxou o nível em oração. A luz arqueou através da escuridão sobre o Gannon caído e para o céu.</color>",
  ui_story_5083_50831601_104_dialog_content = "<color=#e8d9bb>Os soldados lutando arduamente em Gannon olharam em uníssono para o flash, com reflexos de </color><color=#FFB400>esperança</color><color=#e8d9bb> brilhando em seus olhos.</color>",
  ui_story_5083_50831601_105_dialog_content = "Você está sozinho, mas ainda se engana e chama isso de fé. Bem, esmagar guerreiros fiéis é muito mais prazeroso do que esmagar pragas comuns!",
  ui_story_5083_50831601_106_dialog_content = "Maldito seja você, Eclipsita, é por isso que nunca conseguirá... Nós, soldados da Illumina, somos chamados de \"Defensores de Astra\" por um motivo!",
  ui_story_5083_50831601_107_dialog_content = "Eu sou Syurton. Lembre-se deste nome, o nome do seu destruidor!",
  ui_story_5083_50831601_108_dialog_content = "Mate todos eles. Destrua a Torre Central. Quero que Gannon seja arrasada até o esquecimento.",
  ui_story_5083_50831601_109_dialog_content = "A 2ª Legião nunca recua!",
  ui_story_5083_50831601_110_dialog_content = "<color=#e8d9bb>O sinal no céu escureceu e finalmente caiu. Todas as esperanças pareciam estar perdidas na escuridão.</color>",
  ui_story_5083_50831601_111_dialog_content = "2ª Legião? Ouvi isso há alguns dias. Ele até me cortou na cabeça e nas costas.",
  ui_story_5083_50831601_112_dialog_content = "Que pena que ele e seus soldados foram patéticos. Eu fiquei com a lâmina dele, no entanto. Vê isso aqui? Não é uma lembrança ruim.",
  ui_story_5083_50831601_113_dialog_content = "Cachorrinho! Sinto muito...",
  ui_story_5083_50831601_114_dialog_content = "<color=#e8d9bb>Tomados pelo desespero, os veteranos agarraram suas armas e se prepararam para atacar a entidade gigantesca.</color>",
  ui_story_5083_50831601_115_dialog_content = "<color=#e8d9bb>No entanto, as estrelas sempre brilham mais forte na mais escura das noites.</color>",
  ui_story_5083_50831601_116_dialog_content = "<size=45>Isso é longe o suficiente!</size>",
  ui_story_5083_50831601_117_dialog_content = "<size=45>Experimente isso para ver o tamanho!</size>",
  ui_story_5083_50831601_118_dialog_content = "Você é o único cavando sua própria cova, seu estúpido idiota!",
  ui_story_5083_50831601_119_dialog_content = "<color=#e8d9bb>Um veículo blindado desceu e colidiu com as costas do gigantesco Eclipsita, com a torreta causando dano máximo a tão curta distância.</color>",
  ui_story_5083_50831601_120_dialog_content = "Ahhhh!",
  ui_story_5083_50831601_121_dialog_content = "Eu te peguei... Ai!",
  ui_story_5083_50831601_122_dialog_content = "Valeu, camarada!",
  ui_story_5083_50831601_123_dialog_content = "Isso é ridículo, explodindo o veículo! E você quase...",
  ui_story_5083_50831601_124_dialog_content = "Não sou eu sem o louco, certo?",
  ui_story_5083_50831601_125_dialog_content = "Este é o verdadeiro eu, você vê!",
  ui_story_5083_50831601_126_dialog_content = "O que você está fazendo aqui, seu tolo?!",
  ui_story_5083_50831601_127_dialog_content = "Você não enviou o SOS? Eu não conto como um backup legítimo?",
  ui_story_5083_50831601_128_dialog_content = "O lado positivo caiu. Eu vim em um veículo e agora não tenho como voltar, mesmo que você não me queira aqui.",
  ui_story_5083_50831601_129_dialog_content = "Você...!",
  ui_story_5083_50831601_130_dialog_content = "Já é a terceira vez! Não continue me dizendo para sair, velhote!",
  ui_story_5083_50831601_131_dialog_content = "Recebi uma mensagem para os Eclipsitas: Mesmo no subsolo onde vocês não veem o sol, ainda assim não são donos do lugar!",
  ui_story_5083_50831601_132_dialog_content = "Gannon será brilhante novamente, com certeza!",
  ui_story_5083_50831601_133_dialog_content = "Tolo, provavelmente estaremos mortos antes que a ajuda chegue!",
  ui_story_5083_50831601_134_dialog_content = "Nesse caso, espero que a luz do farol brilhe em nossos corpos.",
  ui_story_5083_50831601_135_dialog_content = "A explosão quase me derrubou da borda, praga.",
  ui_story_5083_50831601_136_dialog_content = "O quê? Ainda vivo em duas partes?",
  ui_story_5083_50831601_137_dialog_content = "Você acha que eu poderia ser morto por meras explosões depois de destruir tantas cidades baixas? Eu sou o <color=#FFB400>nemesis de tudo que é vivo</color>!",
  ui_story_5083_50831601_138_dialog_content = "É engraçado, se autodenominar o némesis de tudo que é vivo, apenas para ter estado vivo todo esse tempo.",
  ui_story_5083_50831601_139_dialog_content = "Cale a boca e vamos nessa!",
  ui_story_5083_50831601_140_dialog_content = "Espere só até eu e os caras te mandarmos para o inferno!",
  ui_story_5083_50831602_1_dialog_content = "Você não pode me matar!",
  ui_story_5083_50831602_2_dialog_content = "Heh, toda essa conversa sobre espinhas dorsais inquebráveis... Não vejo você se levantando.",
  ui_story_5083_50831602_3_dialog_content = "Maldito! Vá para o inferno!",
  ui_story_5083_50831602_4_dialog_content = "Você também pode ir lá com ele!",
  ui_story_5083_50831602_5_dialog_content = "<color=#e8d9bb>Barton desviou de um soco e correu pelo braço da criatura.</color>",
  ui_story_5083_50831602_6_dialog_content = "<color=#e8d9bb>Antes que Syurton pudesse reagir, ele arrancou o troféu - a faca de Dogg.</color>",
  ui_story_5083_50831602_7_dialog_content = "<color=#e8d9bb>As duas lâminas se fundem em uma na mão de Barton e se tornaram dele. Ele desviou e atacou Syurton incansavelmente.</color>",
  ui_story_5083_50831602_8_dialog_content = "<color=#e8d9bb>Num piscar de olhos, o pescoço de Syurton foi cortado, fazendo-o se debater e lançar chamas.</color>",
  ui_story_5083_50831602_9_dialog_content = "<color=#e8d9bb>Mas Barton apenas continuou a cortar enquanto as chamas jorravam. O ataque impecável foi o resultado de inúmeras </color><color=#FFB400> práticas </color><color=#e8d9bb> na base.</color>",
  ui_story_5083_50831602_10_dialog_content = "<color=#e8d9bb>E o que era mais horrível era o olhar assassino nos olhos de Barton.</color>",
  ui_story_5083_50831602_11_dialog_content = "<color=#e8d9bb>Ele saltou através do fogo, dividiu a escuridão e cravou a lâmina profundamente no pescoço de Syurton.</color>",
  ui_story_5083_50831602_12_dialog_content = "Fora de mim!",
  ui_story_5083_50831602_13_dialog_content = "Nem pense em machucar o Coronel Barton! Mire nos olhos!",
  ui_story_5083_50831602_14_dialog_content = "Este é o fim... E é assim que eu uso armas, senhor!",
  ui_story_5083_50831602_15_dialog_content = "<color=#e8d9bb>Barton desenhou e disparou uma arma. A bala atingiu a lâmina dupla e a enterrou completamente dentro de Syurton.</color>",
  ui_story_5083_50831602_16_dialog_content = "<color=#e8d9bb>Ele então pressionou um controle remoto para denotar os explosivos que ele plantou dentro de sua lâmina.</color>",
  ui_story_5083_50831602_17_dialog_content = "<color=#e8d9bb>Ninguém poderia ter adivinhado que Barton sacrificaria suas armas e as de seu amigo próximo pela vitória.</color>",
  ui_story_5083_50831602_18_dialog_content = "Não! <color=#FFB400>Mãe</color>...",
  ui_story_5083_50831602_19_dialog_content = "Aproveite sua humilhação no abismo, seu idiota estúpido.",
  ui_story_5083_50831602_20_dialog_content = "Tem certeza de que isso está bem?",
  ui_story_5083_50831602_21_dialog_content = "Dogg estará para sempre em nossos corações e no memorial.",
  ui_story_5083_50831602_22_dialog_content = "A vontade dele é suficiente para nos levar adiante. Nada mais é necessário.",
  ui_story_5083_50831602_23_dialog_content = "Ah, você está bem, Comandante Pango?",
  ui_story_5083_50831602_24_dialog_content = "Não toque nele. Aquele golpe quebrou a coluna dele.",
  ui_story_5083_50831602_25_dialog_content = "Cuidado, Coronel Barton, os Eclipsitas menores ainda estão em movimento!",
  ui_story_5083_50831602_26_dialog_content = "Cuide... do estandarte da 2ª Legião... Você é o comandante agora, Barton... Lidere os homens... e lute até o último suspiro...",
  ui_story_5083_50831602_27_dialog_content = "Confie... em seus companheiros de Illumina... a ajuda virá...",
  ui_story_5083_50831602_28_dialog_content = "Ele está fora!",
  ui_story_5083_50831602_29_dialog_content = "Maldito, maldito!",
  ui_story_5083_50831602_30_dialog_content = "A 2ª Legião nunca irá comprometer!",
  ui_story_5083_50831602_31_dialog_content = "The 2nd Legion will never compromise!",
  ui_story_5083_50831602_32_dialog_content = "<color=#e8d9bb>O gigantesco Eclipsita está morto, mas a batalha continua. Mais pequenos Eclipsitas invadiram o único caminho e lutaram contra os soldados.</color>",
  ui_story_5083_50831602_33_dialog_content = "<color=#e8d9bb>Com a bandeira na mão, Barton lutou ao lado dos guerreiros até que suas costas estivessem para a estação de energia.</color>",
  ui_story_5083_50831602_34_dialog_content = "<color=#e8d9bb>Quando ele olhou em volta, restavam muito poucos homens.</color>",
  ui_story_5083_50831602_35_dialog_content = "Isso é longe o suficiente!",
  ui_story_5083_50831602_36_dialog_content = "Mesmo que só nós tenhamos sobrado, nunca vamos nos comprometer... nunca nos comprometer...",
  ui_story_5083_50831602_37_dialog_content = "Vou lutar com você até o momento final, Barton.",
  ui_story_5083_50831602_38_dialog_content = "Seguiremos o Coronel Barton até o nosso último suspiro.",
  ui_story_5083_50831602_39_dialog_content = "Morreremos defendendo esta passagem!",
  ui_story_5083_50831602_40_dialog_content = "O que estou fazendo? Que tolo eu sou! Por que só pensei nisso agora?",
  ui_story_5083_50831602_41_dialog_content = "Eu já sabia como isso iria terminar.",
  ui_story_5083_50831602_42_dialog_content = "Naquela época, fomos forçados a recuar depois de vencer por pouco aquele grande tolo, mas Pango ficou e lutou.",
  ui_story_5083_50831602_43_dialog_content = "Todos que estavam com ele morreram, e ele caiu em coma por mais de uma década devido a ferimentos.",
  ui_story_5083_50831602_44_dialog_content = "...",
  ui_story_5083_50831602_45_dialog_content = "Eu não tenho olhos como os seus, PlayerName, então invejo como você sempre consegue ver a luz.",
  ui_story_5083_50831602_46_dialog_content = "Mas eu não estou perdido, porque acredito verdadeiramente que haverá luz se lutarmos até o fim.",
  ui_story_5083_50831602_47_dialog_content = "Quando te conheci pela primeira vez, você estava realmente em um caminho de esperança.",
  ui_story_5083_50831602_48_dialog_content = "Tenho a honra de conhecê-lo. Foi você quem nos salvou inúmeras vezes.",
  ui_story_5083_50831602_49_dialog_content = "Você é um herói, mas atormentado por pesadelos... Eu queria te guiar...",
  ui_story_5083_50831602_50_dialog_content = "Eu não tenho medo de me perder com você ao meu lado, e pesadelos não são nada para mim.",
  ui_story_5083_50831602_51_dialog_content = "Mas eu simplesmente não consigo deixar isso ir...",
  ui_story_5083_50831602_52_dialog_content = "O reforço já chegou para o Comandante Pango?",
  ui_story_5083_50831602_53_dialog_content = "Certo, como eu poderia esquecer...?",
  ui_story_5083_50831602_54_dialog_content = "Comandante Pango, o verdadeiro \"pesadelo\" para mim...",
  ui_story_5083_50831602_55_dialog_content = "O futuro da Illumina é cheio de esperança, mas realmente abandonamos os veteranos no passado?",
  ui_story_5083_50831602_56_dialog_content = "Eu fico perturbado só de pensar nisso. Não desejo que eles morram com arrependimento e desespero.",
  ui_story_5083_50831602_57_dialog_content = "Não, Barton, a Illumina nunca abandonaria seus defensores.",
  ui_story_5083_50831602_58_dialog_content = "Felizmente, você finalmente está aqui. Por favor, olhe.",
  ui_story_5083_50831602_59_dialog_content = "Venha comigo, vanguardas. Rápido e não deixe os veteranos esperando!",
  ui_story_5083_50831602_60_dialog_content = "Os não combatentes estão seguros. Agora vamos retomar Gannon!",
  ui_story_5083_50831602_61_dialog_content = "<color=#e8d9bb>Reinhardt apareceu, balançando uma lança flamejante e rompendo a linha dos Eclipsitas. O incêndio iluminou a cidade como o sol da manhã.</color>",
  ui_story_5083_50831602_62_dialog_content = "Eu vejo luz...",
  ui_story_5083_50831602_63_dialog_content = "Olha, Comandante Pango, luz! A ajuda chegou! Eles voltaram!",
  ui_story_5083_50831602_64_dialog_content = "Não estamos abandonados. Acorda e vê!",
  ui_story_5083_50831602_65_dialog_content = "<color=#e8d9bb>Os sinos tocaram em Gannon, anunciando a chegada do reforço, declarando o retorno dos legítimos ocupantes da cidade.</color>",
  ui_story_5083_50831602_66_dialog_content = "<size=45>Comandante Pango...!</size>",
  ui_story_5083_50831602_67_dialog_content = "Pare de chorar, seu pirralho... Eu não estou morto ainda...",
  ui_story_5083_50831602_68_dialog_content = "Não sou surdo... Claro que ouvi...",
  ui_story_5083_50831602_69_dialog_content = "Eles apareceram bem na hora... Eu pensei que nunca mais os veria...",
  ui_story_5083_50831602_70_dialog_content = "Isso é incrível... Realmente, tão incrível...",
  ui_story_5083_50831602_71_dialog_content = "A legião e o futuro de Illumina estão em suas mãos agora, moleque... Controle seu temperamento e seja mais sério...",
  ui_story_5083_50831602_72_dialog_content = "Farei isso, Comandante Pango. Não vou te desapontar.",
  ui_story_5083_50831602_73_dialog_content = "Deixe-os cuidar do comandante, Barton. Devemos ir agora.",
  ui_story_5083_50831602_74_dialog_content = "Siga aquela luz em seu coração... Essa é a sua fé.",
  ui_story_5083_50831602_75_dialog_content = "Este é a última <color=#FFB400>viagem</color>. É hora de deixar o pesadelo para trás.",
  ui_story_5083_50831602_76_dialog_content = "Ah, claro. Nada vai me prender de novo!",
  ui_story_5083_50831602_77_dialog_content = "Adeus, Comandante Pango.",
  ui_story_5083_50831602_78_dialog_content = "?!",
  ui_story_5083_50831602_79_dialog_content = "O sonho está se transformando em realidade... Essa é a sua memória?",
  ui_story_5083_50831602_80_dialog_content = "O Comandante Pango e os veteranos nunca desistem e nem sequer permitem que a bandeira caia.",
  ui_story_5083_50831602_81_dialog_content = "Eles mantiveram Gannon e defenderam nossa luz.",
  ui_story_5083_50831602_82_dialog_content = "Durma, Barton... É um novo dia, e descansar é fácil para você quando está em casa.",
  ui_story_5083_50831602_83_dialog_content = "Comandante Pango... PlayerName... Todos... Muito obrigado... por nos deixar seguir o caminho sem dúvidas...",
  ui_story_5083_50831602_84_dialog_content = "<color=#e8d9bb>Eu testemunhei o quão resilientes as estrelas eram, surgindo e iluminando o céu noturno.</color>",
  ui_story_5083_50831602_85_dialog_content = "<color=#e8d9bb>Bem como a coragem dos Aurorianos, que emitem o brilho da vida mesmo diante da morte.</color>",
  ui_story_5083_50831602_86_dialog_content = "<color=#e8d9bb>Heróis preservaram acendalhas que se transformaram em uma chama, incinerando o Darkover para receber o amanhecer.</color>",
  ui_story_5083_50831602_87_dialog_content = "<color=#e8d9bb>Mesmo quando uma estrela perde seu brilho e cai, aqueles que ela iluminou permanecerão firmes no caminho, continuarão procurando seu caminho até o amanhecer.</color>",
  ui_story_5083_50831602_88_dialog_content = "<color=#e8d9bb>E isso seria suficiente...</color>",
  ui_story_5083_50831602_89_dialog_content = "<color=#e8d9bb>Obrigado a todos, velhas estrelas.</color>"
}
return config
